window.MG_LAZY_DATA["data/lazy/owner-courses/b015-3e9eba314df95066.json"]={sha256:"3e9eba314df950666c7cc644cbb60a0bfb4490d1257f1e4d1f39ffb81c0e7e06",value:{"id":"b015","category":"structures","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic","v7-golden-history","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"title":"舊金山金門大橋","titleEn":"Golden Gate Bridge","summary":"從海峽選址、懸索受力到橋面更換與耐震改造，用 24 道概念模型練習理解一座仍在使用的大跨橋梁。","summaryEn":"Use 24 conceptual exercises to connect strait constraints and suspension forces with deck replacement and seismic rehabilitation of a working long-span bridge.","scope":"以公開一次資料為背景的原創工程判讀課程；每步在紙上或數位示意模型中完成。自設數值、構形與工序不得當成原工程的設計、施工、設備操作或驗收程序。","scopeEn":"Original engineering interpretation exercises grounded in public primary sources. Complete each step on paper or in a schematic digital model. Invented values, geometry and sequences are not the original project’s design, construction, operating or acceptance procedures.","diagram":{"type":"suspension","labels":["需求與場址","結構與介面","施工狀態","驗證與維護"],"labelsEn":["Requirements and site","Structures and interfaces","Construction states","Verification and maintenance"],"original":true,"notToScale":true},"stepCount":64,"estimatedMinutes":1600,"stages":[{"id":"b015-stage01","order":1,"title":"場址、邊界與受力","titleEn":"Site, boundaries and force paths","description":"以六個相互銜接的練習完成「場址、邊界與受力」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on site, boundaries and force paths, retaining assumptions, diagrams and evidence.","steps":[{"id":"b015-v7-01","sequence":1,"order":1,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":[],"title":"把海峽需求放進場址圖","titleEn":"Map the strait requirements","objective":"辨認航道、岸線與跨越位置的共同限制。","objectiveEn":"Identify joint constraints from navigation, shorelines and crossing location.","instruction":"1. 自繪兩岸與航道；2. 分別標示塔位及錨碇區；3. 列出水深、地盤與航道資料缺口。","instructionEn":"1. Sketch shores and navigation corridor; 2. mark tower and anchorage zones separately; 3. list missing depth, ground and navigation evidence.","observation":"跨距相近的方案仍可能有不同的基礎及航運限制。","observationEn":"Similar spans may still imply different foundation and navigation constraints.","failure":"僅以最短跨距判定塔位可行。","failureEn":"Choose tower locations from the shortest span alone.","check":"提交有圖例的場址圖及三個待查資料欄。","checkEn":"Submit a keyed site map and three evidence gaps.","knowledge":[{"id":"b015-v7-01-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"選址同時改變側跨比例、施工可達性及支承條件，不能只比跨距。","textEn":"Siting changes side-span proportions, access and support conditions, so span alone is insufficient."},{"id":"b015-v7-01-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"地圖座標只定位工程背景；地質與海事邊界需要專門調查。","textEn":"A map pin locates project context; ground and marine boundaries require dedicated investigation."}],"quiz":{"question":"審查「把海峽需求放進場址圖」時，哪個判讀有根據？","questionEn":"When reviewing “Map the strait requirements”, which interpretation is justified?","options":["跨距相近的方案仍可能有不同的基礎及航運限制。","僅以最短跨距判定塔位可行。","塔位只影響外觀，不會改變側跨與反力。"],"optionsEn":["Similar spans may still imply different foundation and navigation constraints.","Choose tower locations from the shortest span alone.","Tower locations affect appearance only, not side spans or reactions."],"answer":0,"explanation":"選址同時改變側跨比例、施工可達性及支承條件，不能只比跨距。 地圖座標只定位工程背景；地質與海事邊界需要專門調查。","explanationEn":"Siting changes side-span proportions, access and support conditions, so span alone is insufficient. A map pin locates project context; ground and marine boundaries require dedicated investigation."}},{"id":"b015-v7-02","sequence":2,"order":2,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-01"],"title":"區分全橋與主跨尺寸","titleEn":"Separate overall and main-span dimensions","objective":"避免把不同統計邊界混成同一個橋長。","objectiveEn":"Avoid conflating different definitions of bridge length.","instruction":"1. 畫全橋、懸吊區、主跨三條尺寸線；2. 依官方表標記各自端點；3. 記錄單位與是否包含引橋。","instructionEn":"1. Draw overall, suspended and main-span dimension lines; 2. mark their endpoints from the official table; 3. record units and whether approaches are included.","observation":"尺寸比較只有在端點與單位一致時才成立。","observationEn":"Dimensions are comparable only when endpoints and units agree.","failure":"把包含引橋的長度當成兩塔之間的距離。","failureEn":"Treat a length including approaches as the distance between towers.","check":"繳交三條尺寸線和各自的邊界定義。","checkEn":"Provide three dimension lines with their boundary definitions.","knowledge":[{"id":"b015-v7-02-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"主跨是兩座主塔間的跨度；全橋長度可包含側跨及引橋。","textEn":"The main span lies between the main towers; overall length can include side spans and approaches."},{"id":"b015-v7-02-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"統計資料的精確位數不能修正錯誤的量測邊界。","textEn":"Numerical precision cannot correct an incorrectly defined measurement boundary."}],"quiz":{"question":"審查「區分全橋與主跨尺寸」時，哪個判讀有根據？","questionEn":"When reviewing “Separate overall and main-span dimensions”, which interpretation is justified?","options":["把包含引橋的長度當成兩塔之間的距離。","尺寸比較只有在端點與單位一致時才成立。","單位一致時便可以忽略兩個尺寸的起訖位置。"],"optionsEn":["Treat a length including approaches as the distance between towers.","Dimensions are comparable only when endpoints and units agree.","Matching units make dimension endpoints irrelevant."],"answer":1,"explanation":"主跨是兩座主塔間的跨度；全橋長度可包含側跨及引橋。 統計資料的精確位數不能修正錯誤的量測邊界。","explanationEn":"The main span lies between the main towers; overall length can include side spans and approaches. Numerical precision cannot correct an incorrectly defined measurement boundary."}},{"id":"b015-v7-03","sequence":3,"order":3,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-02"],"title":"追蹤橋面重力至地盤","titleEn":"Trace deck gravity to the ground","objective":"區分吊索、主纜、塔與錨碇的作用。","objectiveEn":"Distinguish the roles of hangers, main cables, towers and anchorages.","instruction":"1. 在橋面放一個假想載荷；2. 畫到吊索及主纜的傳力箭頭；3. 分別追到塔基與端部錨碇反力。","instructionEn":"1. Place a hypothetical deck load; 2. trace force arrows through hangers and main cables; 3. close the paths through tower foundations and end anchorages.","observation":"完整力路徑必須包含主纜端部的水平反力。","observationEn":"A complete force path includes horizontal reactions at the main-cable ends.","failure":"只畫塔的壓力就認為所有纜索拉力已平衡。","failureEn":"Assume tower compression alone balances every cable force.","check":"提交一張閉合到地盤的受力圖。","checkEn":"Submit a force diagram closed through the ground.","knowledge":[{"id":"b015-v7-03-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"柔性纜索主要承受拉力，塔與錨碇分擔不同方向的支承反力。","textEn":"Flexible cables act mainly in tension; towers and anchorages provide different support reactions."},{"id":"b015-v7-03-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"受力箭頭與位移箭頭應分色，否則容易把作用與反應混淆。","textEn":"Use separate symbols for forces and movements to avoid confusing actions with responses."}],"quiz":{"question":"審查「追蹤橋面重力至地盤」時，哪個判讀有根據？","questionEn":"When reviewing “Trace deck gravity to the ground”, which interpretation is justified?","options":["只畫塔的壓力就認為所有纜索拉力已平衡。","端部錨碇只供裝飾，主纜不會把力傳到它。","完整力路徑必須包含主纜端部的水平反力。"],"optionsEn":["Assume tower compression alone balances every cable force.","End anchorages are decorative and receive no cable force.","A complete force path includes horizontal reactions at the main-cable ends."],"answer":2,"explanation":"柔性纜索主要承受拉力，塔與錨碇分擔不同方向的支承反力。 受力箭頭與位移箭頭應分色，否則容易把作用與反應混淆。","explanationEn":"Flexible cables act mainly in tension; towers and anchorages provide different support reactions. Use separate symbols for forces and movements to avoid confusing actions with responses."}},{"id":"b015-v7-04","sequence":4,"order":4,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-03"],"title":"比較橋型與反力邊界","titleEn":"Compare bridge forms and reactions","objective":"看出懸索、斜張與拱橋的力學差別。","objectiveEn":"Recognize mechanical differences between suspension, cable-stayed and arch bridges.","instruction":"1. 自繪三種橋型；2. 標出主要拉力或壓力構件；3. 保持相同跨越需求，列出各型式需要的支承證據。","instructionEn":"1. Sketch three bridge forms; 2. label principal tension or compression members; 3. keep the crossing requirement fixed and list support evidence for each.","observation":"外形相似的跨越構造不一定具有相同反力方向。","observationEn":"Similar crossing silhouettes need not produce the same reaction directions.","failure":"把斜張索當成懸索橋主纜下的垂直吊索。","failureEn":"Treat cable stays as vertical hangers below a suspension main cable.","check":"提交橋型、力型與地盤需求的三欄比較表。","checkEn":"Submit a table of bridge form, force type and ground requirements.","knowledge":[{"id":"b015-v7-04-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"懸索經主纜與吊索承托橋面；斜張索則直接連接橋塔與橋面。","textEn":"Suspension decks hang from main cables through hangers; stays directly connect a tower and deck."},{"id":"b015-v7-04-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"倒置纜索曲線可幫助理解拱的壓力，但不能取代拱橋穩定分析。","textEn":"An inverted cable curve illustrates arch compression but does not replace arch stability analysis."}],"quiz":{"question":"審查「比較橋型與反力邊界」時，哪個判讀有根據？","questionEn":"When reviewing “Compare bridge forms and reactions”, which interpretation is justified?","options":["外形相似的跨越構造不一定具有相同反力方向。","把斜張索當成懸索橋主纜下的垂直吊索。","拱橋與懸索橋的主要承重構件都只承受拉力。"],"optionsEn":["Similar crossing silhouettes need not produce the same reaction directions.","Treat cable stays as vertical hangers below a suspension main cable.","The principal members of arches and suspension bridges both carry tension only."],"answer":0,"explanation":"懸索經主纜與吊索承托橋面；斜張索則直接連接橋塔與橋面。 倒置纜索曲線可幫助理解拱的壓力，但不能取代拱橋穩定分析。","explanationEn":"Suspension decks hang from main cables through hangers; stays directly connect a tower and deck. An inverted cable curve illustrates arch compression but does not replace arch stability analysis."}},{"id":"b015-v7-05","sequence":5,"order":5,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-04"],"title":"建立溫度與車流情境","titleEn":"Define temperature and traffic cases","objective":"把不同荷載組合當成不同模型狀態。","objectiveEn":"Treat different load combinations as distinct model states.","instruction":"1. 定義無量綱的冷、暖兩情境；2. 分配主跨或側跨假想車流；3. 先預測再比較橋面位移方向。","instructionEn":"1. Define dimensionless cool and warm cases; 2. distribute hypothetical traffic on main or side spans; 3. predict then compare deck-movement directions.","observation":"橋面位移同時受纜長變化與載荷分布影響。","observationEn":"Deck movement depends on cable-length changes and load distribution together.","failure":"只看車輛總數就斷言主跨一定向下同樣多。","failureEn":"Use vehicle count alone to assert identical downward main-span movement.","check":"繳交至少四個有邊界條件的情境卡。","checkEn":"Provide at least four scenario cards with boundary conditions.","knowledge":[{"id":"b015-v7-05-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"加熱造成的纜索伸長會改變懸吊幾何；活載位置也改變力的平衡。","textEn":"Thermal cable expansion changes suspension geometry, while live-load position changes equilibrium."},{"id":"b015-v7-05-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"簡化模型的位移方向可作概念比較，不能作真橋變形限值。","textEn":"A simplified model can compare movement directions, not set real-bridge deformation limits."}],"quiz":{"question":"審查「建立溫度與車流情境」時，哪個判讀有根據？","questionEn":"When reviewing “Define temperature and traffic cases”, which interpretation is justified?","options":["只看車輛總數就斷言主跨一定向下同樣多。","橋面位移同時受纜長變化與載荷分布影響。","主纜溫度改變不可能影響橋面位置。"],"optionsEn":["Use vehicle count alone to assert identical downward main-span movement.","Deck movement depends on cable-length changes and load distribution together.","Cable-temperature changes cannot affect deck position."],"answer":1,"explanation":"加熱造成的纜索伸長會改變懸吊幾何；活載位置也改變力的平衡。 簡化模型的位移方向可作概念比較，不能作真橋變形限值。","explanationEn":"Thermal cable expansion changes suspension geometry, while live-load position changes equilibrium. A simplified model can compare movement directions, not set real-bridge deformation limits."}},{"id":"b015-v7-06","sequence":6,"order":6,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-05"],"title":"做場址階段設計審查","titleEn":"Review the site-stage model","objective":"整合第一階段的尺寸、反力與不確定性。","objectiveEn":"Integrate dimensions, reactions and uncertainties from the first stage.","instruction":"1. 將場址圖與受力圖並排；2. 逐一核對尺寸端點和反力落點；3. 指定一個必須補資料才能決定的選項。","instructionEn":"1. Compare site and force diagrams; 2. audit dimension endpoints and reaction locations; 3. identify one choice that requires further evidence.","observation":"未知地盤條件應保留為待查項，而非被漂亮圖面掩蓋。","observationEn":"Unknown ground conditions should remain unresolved rather than disappear behind a polished drawing.","failure":"把所有未確認欄位填成與另一座橋相同。","failureEn":"Fill every unverified field with values borrowed from another bridge.","check":"輸出含假設、證據、待查項的三欄審查單。","checkEn":"Produce a review sheet separating assumptions, evidence and open items.","knowledge":[{"id":"b015-v7-06-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"設計審查要檢查介面是否一致，不只檢查單一構件有無畫出。","textEn":"Design review checks interface consistency, not merely whether every component is drawn."},{"id":"b015-v7-06-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"可追溯的未知項比沒有來源的確定數字更有助於後續決策。","textEn":"Traceable unknowns support later decisions better than unsupported precise numbers."}],"quiz":{"question":"審查「做場址階段設計審查」時，哪個判讀有根據？","questionEn":"When reviewing “Review the site-stage model”, which interpretation is justified?","options":["把所有未確認欄位填成與另一座橋相同。","圖畫越精細，未知地盤條件就越少。","未知地盤條件應保留為待查項，而非被漂亮圖面掩蓋。"],"optionsEn":["Fill every unverified field with values borrowed from another bridge.","More detailed drawing automatically reduces unknown ground conditions.","Unknown ground conditions should remain unresolved rather than disappear behind a polished drawing."],"answer":2,"explanation":"設計審查要檢查介面是否一致，不只檢查單一構件有無畫出。 可追溯的未知項比沒有來源的確定數字更有助於後續決策。","explanationEn":"Design review checks interface consistency, not merely whether every component is drawn. Traceable unknowns support later decisions better than unsupported precise numbers."}}]},{"id":"b015-stage02","order":2,"title":"基礎、橋塔與主纜","titleEn":"Foundations, towers and main cables","description":"以六個相互銜接的練習完成「基礎、橋塔與主纜」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on foundations, towers and main cables, retaining assumptions, diagrams and evidence.","steps":[{"id":"b015-v7-07","sequence":7,"order":1,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-06"],"title":"分開海床與塔基變形","titleEn":"Separate seabed and foundation movements","objective":"辨認基礎平移、轉動和橋塔彎曲。","objectiveEn":"Distinguish foundation translation, rotation and tower bending.","instruction":"1. 畫海床、基礎與橋塔三層；2. 分別施加假想平移與轉角；3. 比較相同塔頂位移可能對應的不同原因。","instructionEn":"1. Draw seabed, foundation and tower layers; 2. apply hypothetical translations and rotations separately; 3. compare different causes of the same tower-top displacement.","observation":"單一塔頂位移不能唯一識別基礎或塔身的變化。","observationEn":"One tower-top reading cannot uniquely identify foundation or tower changes.","failure":"塔頂偏移便直接證明海床承載失效。","failureEn":"A shifted tower top directly proves seabed bearing failure.","check":"提交兩種具有相同塔頂位移的概念反例。","checkEn":"Submit two conceptual cases with the same tower-top displacement.","knowledge":[{"id":"b015-v7-07-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"剛體轉動與構件彎曲在局部量測上可能相似，需多點觀測分辨。","textEn":"Rigid rotation and member bending may appear similar locally; multiple observations help distinguish them."},{"id":"b015-v7-07-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"把測点放在不同高度及基礎附近，可增加辨識不同變形模式的資訊。","textEn":"Observations at different heights and near foundations improve discrimination between movement modes."}],"quiz":{"question":"審查「分開海床與塔基變形」時，哪個判讀有根據？","questionEn":"When reviewing “Separate seabed and foundation movements”, which interpretation is justified?","options":["單一塔頂位移不能唯一識別基礎或塔身的變化。","塔頂偏移便直接證明海床承載失效。","剛體轉動與塔身彎曲在任何測點都能用單一讀數區分。"],"optionsEn":["One tower-top reading cannot uniquely identify foundation or tower changes.","A shifted tower top directly proves seabed bearing failure.","One reading anywhere always separates rigid rotation from tower bending."],"answer":0,"explanation":"剛體轉動與構件彎曲在局部量測上可能相似，需多點觀測分辨。 把測点放在不同高度及基礎附近，可增加辨識不同變形模式的資訊。","explanationEn":"Rigid rotation and member bending may appear similar locally; multiple observations help distinguish them. Observations at different heights and near foundations improve discrimination between movement modes."}},{"id":"b015-v7-08","sequence":8,"order":2,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-07"],"title":"拆解塔座的介面資料","titleEn":"Separate tower-base interface records","objective":"連接地質、混凝土與鋼構三種證據。","objectiveEn":"Connect ground, concrete and steel-interface evidence.","instruction":"1. 畫地盤至塔腳的剖面；2. 在每個交界列出幾何與材料紀錄；3. 將缺失資料標成不能放行的模型介面。","instructionEn":"1. Draw a section from ground to tower foot; 2. list geometry and material records at each interface; 3. flag missing records as unresolved model interfaces.","observation":"上下構件各自合格仍不保證接觸介面吻合。","observationEn":"Individually acceptable components do not guarantee a compatible interface.","failure":"上下材料強度足夠便可忽略幾何及接觸條件。","failureEn":"Adequate material strengths make geometry and contact conditions irrelevant.","check":"繳交三層介面表，至少列出一項幾何衝突。","checkEn":"Provide a three-layer interface table with at least one geometric conflict.","knowledge":[{"id":"b015-v7-08-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"介面會傳遞力、約束位移並影響施工定位，因此必須獨立檢查。","textEn":"Interfaces transmit forces, constrain movement and affect positioning, so they require explicit review."},{"id":"b015-v7-08-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"示意圖中的完美貼合是假設，不是現場接觸品質的證據。","textEn":"Perfect contact in a schematic is an assumption, not evidence of field contact quality."}],"quiz":{"question":"審查「拆解塔座的介面資料」時，哪個判讀有根據？","questionEn":"When reviewing “Separate tower-base interface records”, which interpretation is justified?","options":["上下材料強度足夠便可忽略幾何及接觸條件。","上下構件各自合格仍不保證接觸介面吻合。","材料來源相同就表示上下構件的幾何一定吻合。"],"optionsEn":["Adequate material strengths make geometry and contact conditions irrelevant.","Individually acceptable components do not guarantee a compatible interface.","A shared material supplier guarantees matching component geometry."],"answer":1,"explanation":"介面會傳遞力、約束位移並影響施工定位，因此必須獨立檢查。 示意圖中的完美貼合是假設，不是現場接觸品質的證據。","explanationEn":"Interfaces transmit forces, constrain movement and affect positioning, so they require explicit review. Perfect contact in a schematic is an assumption, not evidence of field contact quality."}},{"id":"b015-v7-09","sequence":9,"order":3,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-08"],"title":"辨認橋塔節間與側向支撐","titleEn":"Identify tower panels and lateral bracing","objective":"理解細長塔腿如何形成整體側向系統。","objectiveEn":"Understand how slender tower legs form a lateral system.","instruction":"1. 畫兩條塔腿及連接節間；2. 用不同顏色標出縱向與橫向變形；3. 比較移除一組概念支撐前後的變形趨勢。","instructionEn":"1. Draw two tower legs and connecting panels; 2. distinguish longitudinal and transverse deformation; 3. compare trends before and after removing a conceptual brace.","observation":"同樣塔高的模型可因支撐配置不同而有不同側向剛度。","observationEn":"Equal-height models can have different lateral stiffness because of bracing layout.","failure":"塔高相同就保證風中位移相同。","failureEn":"Identical tower height guarantees identical wind displacement.","check":"提交兩種配置的變形草圖及固定邊界。","checkEn":"Submit deformation sketches and support assumptions for two layouts.","knowledge":[{"id":"b015-v7-09-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"細長結構的穩定性取決於約束與構件共同作用，不能只比較截面面積。","textEn":"Slender-structure stability depends on restraints and member interaction, not cross-sectional area alone."},{"id":"b015-v7-09-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"移除支撐的數位試驗只用於概念辨識，不對應實橋可容許損傷。","textEn":"Digital brace-removal exercises explain mechanisms, not permissible damage to the actual bridge."}],"quiz":{"question":"審查「辨認橋塔節間與側向支撐」時，哪個判讀有根據？","questionEn":"When reviewing “Identify tower panels and lateral bracing”, which interpretation is justified?","options":["塔高相同就保證風中位移相同。","塔腿的連接配置不會改變整體變形。","同樣塔高的模型可因支撐配置不同而有不同側向剛度。"],"optionsEn":["Identical tower height guarantees identical wind displacement.","Connections between tower legs cannot affect overall deformation.","Equal-height models can have different lateral stiffness because of bracing layout."],"answer":2,"explanation":"細長結構的穩定性取決於約束與構件共同作用，不能只比較截面面積。 移除支撐的數位試驗只用於概念辨識，不對應實橋可容許損傷。","explanationEn":"Slender-structure stability depends on restraints and member interaction, not cross-sectional area alone. Digital brace-removal exercises explain mechanisms, not permissible damage to the actual bridge."}},{"id":"b015-v7-10","sequence":10,"order":4,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-09"],"title":"把單絲、索股與主纜分層","titleEn":"Separate wire, strand and main cable","objective":"辨認多尺度的纜索品質紀錄。","objectiveEn":"Recognize cable-quality records at multiple scales.","instruction":"1. 畫單絲、索股、主纜三級樹；2. 把材料試驗、集束幾何與外包保護分配到各級；3. 保留批次追溯連結。","instructionEn":"1. Draw a wire–strand–cable tree; 2. assign material tests, bundle geometry and wrapping to the appropriate levels; 3. retain batch-traceability links.","observation":"單絲試驗只描述局部材料，不直接證明整條主纜狀態。","observationEn":"A wire test characterizes local material, not the condition of an entire main cable.","failure":"抽到一根合格單絲即可認定所有索股與接合均正常。","failureEn":"One acceptable wire establishes that all strands and connections are sound.","check":"繳交三級追溯樹及每級一種證據。","checkEn":"Provide a three-level traceability tree with one evidence type per level.","knowledge":[{"id":"b015-v7-10-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"主纜由多根鋼絲組成，局部材料、幾何分布與防護狀態影響不同問題。","textEn":"Main cables comprise many wires; local material, geometric distribution and protection address different questions."},{"id":"b015-v7-10-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"抽樣結果必須連同抽樣位置及代表範圍解讀。","textEn":"Sampling results must be interpreted with their locations and representativeness."}],"quiz":{"question":"審查「把單絲、索股與主纜分層」時，哪個判讀有根據？","questionEn":"When reviewing “Separate wire, strand and main cable”, which interpretation is justified?","options":["單絲試驗只描述局部材料，不直接證明整條主纜狀態。","抽到一根合格單絲即可認定所有索股與接合均正常。","主纜外包保護的檢查可以直接取代鋼絲材料追溯。"],"optionsEn":["A wire test characterizes local material, not the condition of an entire main cable.","One acceptable wire establishes that all strands and connections are sound.","Cable-wrap inspection directly replaces wire-material traceability."],"answer":0,"explanation":"主纜由多根鋼絲組成，局部材料、幾何分布與防護狀態影響不同問題。 抽樣結果必須連同抽樣位置及代表範圍解讀。","explanationEn":"Main cables comprise many wires; local material, geometric distribution and protection address different questions. Sampling results must be interpreted with their locations and representativeness."}},{"id":"b015-v7-11","sequence":11,"order":5,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-10"],"title":"讀懂索鞍與主纜轉向","titleEn":"Interpret cable saddles and redirection","objective":"把主纜的拉力方向與橋塔反力連起來。","objectiveEn":"Connect main-cable tension directions with tower reactions.","instruction":"1. 畫主纜通過塔頂的兩側切線；2. 合成一組自設向量；3. 在索鞍與塔上標記相反作用力。","instructionEn":"1. Draw cable tangents on both sides of a tower; 2. combine a hypothetical vector pair; 3. mark opposite forces on saddle and tower.","observation":"塔頂反力來自兩側纜索拉力的向量合成。","observationEn":"Tower-top reaction follows the vector combination of cable tensions on both sides.","failure":"兩側纜索張力相等就表示塔頂沒有任何受力。","failureEn":"Equal tensions on both sides imply zero force on the tower top.","check":"輸出有方向、比例假設與反力的向量圖。","checkEn":"Provide a vector diagram with directions, scale assumptions and reaction.","knowledge":[{"id":"b015-v7-11-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"相同大小的斜向力仍可能形成明顯合力，方向比數字相等更重要。","textEn":"Equal-magnitude inclined forces can produce a substantial resultant; equal numbers do not erase direction."},{"id":"b015-v7-11-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"索鞍接觸與主纜轉折是局部介面問題，整橋模型通常需另外簡化。","textEn":"Saddle contact and cable redirection are local interface problems simplified separately in whole-bridge models."}],"quiz":{"question":"審查「讀懂索鞍與主纜轉向」時，哪個判讀有根據？","questionEn":"When reviewing “Interpret cable saddles and redirection”, which interpretation is justified?","options":["兩側纜索張力相等就表示塔頂沒有任何受力。","塔頂反力來自兩側纜索拉力的向量合成。","兩個拉力的大小可以直接相減而不考慮方向。"],"optionsEn":["Equal tensions on both sides imply zero force on the tower top.","Tower-top reaction follows the vector combination of cable tensions on both sides.","Two tension magnitudes can be subtracted without considering direction."],"answer":1,"explanation":"相同大小的斜向力仍可能形成明顯合力，方向比數字相等更重要。 索鞍接觸與主纜轉折是局部介面問題，整橋模型通常需另外簡化。","explanationEn":"Equal-magnitude inclined forces can produce a substantial resultant; equal numbers do not erase direction. Saddle contact and cable redirection are local interface problems simplified separately in whole-bridge models."}},{"id":"b015-v7-12","sequence":12,"order":6,"sourceIds":["v7-golden-stats","v7-golden-improvements","v7-golden-seismic"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-11"],"title":"標示索夾、吊索與防護分工","titleEn":"Distinguish cable bands, hangers and protection","objective":"理解傳力連接與腐蝕防護不是同一種功能。","objectiveEn":"Understand that load transfer and corrosion protection are different functions.","instruction":"1. 畫主纜、索夾與垂直吊索；2. 標示傳力及排水路徑；3. 將機械連接紀錄與塗覆檢查分成兩份清單。","instructionEn":"1. Sketch main cable, band and vertical hanger; 2. mark force and drainage paths; 3. separate mechanical-connection and coating-inspection records.","observation":"外表塗層完整不能單獨證明連接的機械狀態。","observationEn":"An intact surface coating alone does not establish mechanical connection condition.","failure":"外觀沒有鏽色就可省略索夾及吊索端部檢查。","failureEn":"No visible rust makes cable-band and hanger-end checks unnecessary.","check":"繳交分開力路徑與水路徑的節點圖。","checkEn":"Submit a node sketch separating force and water paths.","knowledge":[{"id":"b015-v7-12-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"局部積水及隙縫環境可能與可見大面積塗層具有不同的腐蝕條件。","textEn":"Trapped water and crevices can create corrosion conditions different from broad exposed coating surfaces."},{"id":"b015-v7-12-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"維護紀錄必須指出檢查範圍，不能把外觀檢查擴大為內部健康保證。","textEn":"Maintenance records must state inspection scope rather than turn surface observations into internal-health guarantees."}],"quiz":{"question":"審查「標示索夾、吊索與防護分工」時，哪個判讀有根據？","questionEn":"When reviewing “Distinguish cable bands, hangers and protection”, which interpretation is justified?","options":["外觀沒有鏽色就可省略索夾及吊索端部檢查。","排水路徑和傳力路徑完全相同，所以不需分開標記。","外表塗層完整不能單獨證明連接的機械狀態。"],"optionsEn":["No visible rust makes cable-band and hanger-end checks unnecessary.","Drainage and force paths are identical and need no separate labels.","An intact surface coating alone does not establish mechanical connection condition."],"answer":2,"explanation":"局部積水及隙縫環境可能與可見大面積塗層具有不同的腐蝕條件。 維護紀錄必須指出檢查範圍，不能把外觀檢查擴大為內部健康保證。","explanationEn":"Trapped water and crevices can create corrosion conditions different from broad exposed coating surfaces. Maintenance records must state inspection scope rather than turn surface observations into internal-health guarantees."}}]},{"id":"b015-stage03","order":3,"title":"橋面架設與變形","titleEn":"Deck erection and deformation","description":"以六個相互銜接的練習完成「橋面架設與變形」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on deck erection and deformation, retaining assumptions, diagrams and evidence.","steps":[{"id":"b015-v7-13","sequence":13,"order":1,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-12"],"title":"比較架設前後的受力狀態","titleEn":"Compare construction and completed states","objective":"識別未閉合系統中的臨時邊界。","objectiveEn":"Identify temporary boundaries in an incomplete system.","instruction":"1. 畫未掛橋面、部分掛設、完成三狀態；2. 在每張圖列出仍缺少的構件；3. 逐一追查剩餘支承與反力。","instructionEn":"1. Draw bare-cable, partly decked and completed states; 2. list absent components in each; 3. trace the remaining supports and reactions.","observation":"完工橋的力路徑不能直接套到尚未完成的架設狀態。","observationEn":"Completed-bridge force paths cannot simply be applied to incomplete erection states.","failure":"完工結構安全就代表每個中間狀態也必然安全。","failureEn":"A satisfactory completed structure guarantees every intermediate state.","check":"提交三張有缺件與邊界註記的狀態圖。","checkEn":"Submit three state diagrams identifying missing members and boundaries.","knowledge":[{"id":"b015-v7-13-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"施工階段的剛度、約束及荷載都會變動；臨時系統有自己的分析需求。","textEn":"Construction-stage stiffness, restraints and loads change; temporary systems need their own analysis."},{"id":"b015-v7-13-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"課程的狀態排序用來檢查依賴關係，不是吊裝作業程序。","textEn":"The educational state sequence checks dependencies and is not a lifting procedure."}],"quiz":{"question":"審查「比較架設前後的受力狀態」時，哪個判讀有根據？","questionEn":"When reviewing “Compare construction and completed states”, which interpretation is justified?","options":["完工橋的力路徑不能直接套到尚未完成的架設狀態。","完工結構安全就代表每個中間狀態也必然安全。","未安裝的構件仍可在施工模型中提供實際剛度。"],"optionsEn":["Completed-bridge force paths cannot simply be applied to incomplete erection states.","A satisfactory completed structure guarantees every intermediate state.","Uninstalled members still provide actual stiffness in construction models."],"answer":0,"explanation":"施工階段的剛度、約束及荷載都會變動；臨時系統有自己的分析需求。 課程的狀態排序用來檢查依賴關係，不是吊裝作業程序。","explanationEn":"Construction-stage stiffness, restraints and loads change; temporary systems need their own analysis. The educational state sequence checks dependencies and is not a lifting procedure."}},{"id":"b015-v7-14","sequence":14,"order":2,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-13"],"title":"追蹤橋面節段幾何累積","titleEn":"Track accumulated deck-segment geometry","objective":"理解局部尺寸誤差與全跨閉合的關係。","objectiveEn":"Relate local dimension errors to whole-span closure.","instruction":"1. 排列六個自設長度節段；2. 分別加入同向及交錯誤差；3. 比較末端閉合偏差並記錄基準。","instructionEn":"1. Arrange six hypothetical deck lengths; 2. add same-direction and alternating errors; 3. compare end closure and record the reference frame.","observation":"相同單節誤差上限可能形成不同的累積閉合差。","observationEn":"The same per-segment error bound can yield different accumulated closure errors.","failure":"每段誤差不大就不需要檢查整跨累積。","failureEn":"Small individual errors eliminate the need to check span-wide accumulation.","check":"輸出節段表、累積曲線及一個可追溯基準。","checkEn":"Provide a segment table, accumulation plot and traceable datum.","knowledge":[{"id":"b015-v7-14-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"系統性偏差會沿序列累積，不能當成互相抵消的隨機誤差。","textEn":"Systematic bias accumulates along a sequence and cannot be treated as canceling random error."},{"id":"b015-v7-14-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"幾何比較應指定溫度與模型狀態，避免把環境變化誤認為製作誤差。","textEn":"Geometry comparisons should specify temperature and model state to avoid mistaking environmental movement for fabrication error."}],"quiz":{"question":"審查「追蹤橋面節段幾何累積」時，哪個判讀有根據？","questionEn":"When reviewing “Track accumulated deck-segment geometry”, which interpretation is justified?","options":["每段誤差不大就不需要檢查整跨累積。","相同單節誤差上限可能形成不同的累積閉合差。","相同方向的節段偏差必然互相抵消。"],"optionsEn":["Small individual errors eliminate the need to check span-wide accumulation.","The same per-segment error bound can yield different accumulated closure errors.","Same-direction segment errors necessarily cancel."],"answer":1,"explanation":"系統性偏差會沿序列累積，不能當成互相抵消的隨機誤差。 幾何比較應指定溫度與模型狀態，避免把環境變化誤認為製作誤差。","explanationEn":"Systematic bias accumulates along a sequence and cannot be treated as canceling random error. Geometry comparisons should specify temperature and model state to avoid mistaking environmental movement for fabrication error."}},{"id":"b015-v7-15","sequence":15,"order":3,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-14"],"title":"區分橋面彎曲與扭轉","titleEn":"Distinguish deck bending and torsion","objective":"看出左右側位移組合代表的變形模式。","objectiveEn":"Identify deformation modes from paired edge movements.","instruction":"1. 在同一斷面設左右觀察點；2. 繪同向與反向位移；3. 比較中線升降與斷面轉角。","instructionEn":"1. Place observation points at both deck edges; 2. draw same-direction and opposite-direction movements; 3. compare centerline motion and section rotation.","observation":"兩側反向位移可能代表扭轉而非單純整體升降。","observationEn":"Opposite edge movements can indicate torsion rather than uniform vertical motion.","failure":"只量一側橋面即可完整區分所有變形模式。","failureEn":"One deck-edge measurement fully distinguishes all deformation modes.","check":"提交兩組邊緣位移及對應的模式標籤。","checkEn":"Provide two paired edge-motion cases with mode labels.","knowledge":[{"id":"b015-v7-15-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"彎曲與扭轉是不同的變形自由度；橋面橫向連接會影響兩者的耦合。","textEn":"Bending and torsion are distinct degrees of freedom; transverse connections influence their coupling."},{"id":"b015-v7-15-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"一個感測器的時間曲線不足以唯一判斷整個斷面的運動。","textEn":"One sensor time history cannot uniquely identify the motion of an entire cross-section."}],"quiz":{"question":"審查「區分橋面彎曲與扭轉」時，哪個判讀有根據？","questionEn":"When reviewing “Distinguish deck bending and torsion”, which interpretation is justified?","options":["只量一側橋面即可完整區分所有變形模式。","兩側反向位移代表橋面只做剛體平移。","兩側反向位移可能代表扭轉而非單純整體升降。"],"optionsEn":["One deck-edge measurement fully distinguishes all deformation modes.","Opposite edge movements indicate pure rigid translation.","Opposite edge movements can indicate torsion rather than uniform vertical motion."],"answer":2,"explanation":"彎曲與扭轉是不同的變形自由度；橋面橫向連接會影響兩者的耦合。 一個感測器的時間曲線不足以唯一判斷整個斷面的運動。","explanationEn":"Bending and torsion are distinct degrees of freedom; transverse connections influence their coupling. One sensor time history cannot uniquely identify the motion of an entire cross-section."}},{"id":"b015-v7-16","sequence":16,"order":4,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-15"],"title":"用風案例比較剛度與阻尼","titleEn":"Compare stiffness and damping in wind cases","objective":"避免把降低位移與消耗振動能量混為一談。","objectiveEn":"Avoid conflating reduced displacement with dissipation of vibration energy.","instruction":"1. 畫兩個自設振動衰減曲線；2. 分別改變頻率及衰減快慢；3. 標註剛度改變與阻尼改變的差別。","instructionEn":"1. Draw two hypothetical vibration-decay curves; 2. vary frequency and decay rate separately; 3. distinguish stiffness changes from damping changes.","observation":"頻率改變與衰減加快是不同的模型特徵。","observationEn":"A changed frequency and faster decay are different model features.","failure":"振幅較小就一定證明材料強度提高。","failureEn":"A smaller amplitude necessarily proves higher material strength.","check":"繳交頻率、振幅及衰減三個獨立觀察欄。","checkEn":"Provide separate observations for frequency, amplitude and decay.","knowledge":[{"id":"b015-v7-16-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"剛度影響固有頻率，阻尼描述能量耗散；兩者不能從單一最大振幅直接互換。","textEn":"Stiffness affects natural frequency while damping describes dissipation; one peak amplitude does not identify both."},{"id":"b015-v7-16-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"橋梁的風反應還受氣動形狀與來流條件影響，簡單振子只是概念工具。","textEn":"Bridge wind response also depends on aerodynamics and inflow; a simple oscillator is only a conceptual tool."}],"quiz":{"question":"審查「用風案例比較剛度與阻尼」時，哪個判讀有根據？","questionEn":"When reviewing “Compare stiffness and damping in wind cases”, which interpretation is justified?","options":["頻率改變與衰減加快是不同的模型特徵。","振幅較小就一定證明材料強度提高。","衰減曲線變快就唯一證明固有頻率提高。"],"optionsEn":["A changed frequency and faster decay are different model features.","A smaller amplitude necessarily proves higher material strength.","Faster decay uniquely proves an increased natural frequency."],"answer":0,"explanation":"剛度影響固有頻率，阻尼描述能量耗散；兩者不能從單一最大振幅直接互換。 橋梁的風反應還受氣動形狀與來流條件影響，簡單振子只是概念工具。","explanationEn":"Stiffness affects natural frequency while damping describes dissipation; one peak amplitude does not identify both. Bridge wind response also depends on aerodynamics and inflow; a simple oscillator is only a conceptual tool."}},{"id":"b015-v7-17","sequence":17,"order":5,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-16"],"title":"讀取橋面更換的介面變化","titleEn":"Interpret deck-replacement interfaces","objective":"理解更換橋面會改變質量與接合需求。","objectiveEn":"Understand how deck replacement changes mass and connection requirements.","instruction":"1. 並排畫原混凝土橋面與鋼橋面概念截面；2. 標示重量、局部剛度及排水介面；3. 列出需要重新核對的吊索與支承資料。","instructionEn":"1. Compare conceptual concrete and steel deck sections; 2. mark mass, local stiffness and drainage interfaces; 3. list hanger and support records needing review.","observation":"減輕橋面重量不表示所有結構反應都按同一比例減少。","observationEn":"Reduced deck weight does not reduce every structural response by the same proportion.","failure":"換成較輕橋面後即可沿用全部舊的動態與接合判斷。","failureEn":"A lighter deck permits every old dynamic and connection assumption to remain unchanged.","check":"輸出更換前後的介面差異清單。","checkEn":"Provide an interface-change register for the replacement.","knowledge":[{"id":"b015-v7-17-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"質量、剛度與載荷分配共同決定反應，改變其中一項便可能需要重新評估。","textEn":"Mass, stiffness and load distribution jointly govern response; changing one may require reassessment."},{"id":"b015-v7-17-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"官方記錄的橋面更換是歷史案例；本練習不重建其夜間施工安排。","textEn":"The documented deck replacement is a historical case; this exercise does not reconstruct its night-work plan."}],"quiz":{"question":"審查「讀取橋面更換的介面變化」時，哪個判讀有根據？","questionEn":"When reviewing “Interpret deck-replacement interfaces”, which interpretation is justified?","options":["換成較輕橋面後即可沿用全部舊的動態與接合判斷。","減輕橋面重量不表示所有結構反應都按同一比例減少。","重量變少就不必再核對任何橋面連接。"],"optionsEn":["A lighter deck permits every old dynamic and connection assumption to remain unchanged.","Reduced deck weight does not reduce every structural response by the same proportion.","Lower weight eliminates every deck-connection recheck."],"answer":1,"explanation":"質量、剛度與載荷分配共同決定反應，改變其中一項便可能需要重新評估。 官方記錄的橋面更換是歷史案例；本練習不重建其夜間施工安排。","explanationEn":"Mass, stiffness and load distribution jointly govern response; changing one may require reassessment. The documented deck replacement is a historical case; this exercise does not reconstruct its night-work plan."}},{"id":"b015-v7-18","sequence":18,"order":6,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-17"],"title":"做橋面階段幾何審查","titleEn":"Review deck-stage geometry","objective":"讓架設狀態與量測資料具有一致版本。","objectiveEn":"Keep construction states and measurement data under consistent versions.","instruction":"1. 選一個部分完成狀態；2. 檢查節段、溫度與基準的版本；3. 用新舊兩張圖指出一個不能直接比較的量測。","instructionEn":"1. Select a partially complete state; 2. check segment, temperature and datum versions; 3. identify one observation that cannot be directly compared across two revisions.","observation":"同一位置的讀數在不同邊界條件下不一定可直接相減。","observationEn":"Readings at the same location are not necessarily directly comparable under different boundaries.","failure":"測點名稱相同便代表兩次量測具有相同條件。","failureEn":"An identical point name guarantees identical measurement conditions.","check":"提交一份帶版本及不適用說明的比較表。","checkEn":"Submit a versioned comparison table with applicability notes.","knowledge":[{"id":"b015-v7-18-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"量測可追溯性包含儀器與模型狀態；只保留數字會丟失工程意義。","textEn":"Measurement traceability includes instruments and model state; retaining numbers alone loses engineering meaning."},{"id":"b015-v7-18-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"介面修訂應通知依賴該資料的後續判讀，否則局部正確仍可造成整體不一致。","textEn":"Interface revisions must propagate to dependent interpretations or locally correct work can remain globally inconsistent."}],"quiz":{"question":"審查「做橋面階段幾何審查」時，哪個判讀有根據？","questionEn":"When reviewing “Review deck-stage geometry”, which interpretation is justified?","options":["測點名稱相同便代表兩次量測具有相同條件。","測量紀錄只保留數字比保留溫度與版本更完整。","同一位置的讀數在不同邊界條件下不一定可直接相減。"],"optionsEn":["An identical point name guarantees identical measurement conditions.","Numbers alone are a more complete measurement record than numbers with temperature and versions.","Readings at the same location are not necessarily directly comparable under different boundaries."],"answer":2,"explanation":"量測可追溯性包含儀器與模型狀態；只保留數字會丟失工程意義。 介面修訂應通知依賴該資料的後續判讀，否則局部正確仍可造成整體不一致。","explanationEn":"Measurement traceability includes instruments and model state; retaining numbers alone loses engineering meaning. Interface revisions must propagate to dependent interpretations or locally correct work can remain globally inconsistent."}}]},{"id":"b015-stage04","order":4,"title":"維護、改造與工程移轉","titleEn":"Maintenance, rehabilitation and transfer","description":"以六個相互銜接的練習完成「維護、改造與工程移轉」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on maintenance, rehabilitation and transfer, retaining assumptions, diagrams and evidence.","steps":[{"id":"b015-v7-19","sequence":19,"order":1,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-18"],"title":"制定分區腐蝕觀察表","titleEn":"Create a corrosion-observation map","objective":"區分腐蝕環境與可見缺陷的證據層級。","objectiveEn":"Separate exposure conditions from observed-defect evidence.","instruction":"1. 在示意橋上分出海霧、排水與接頭區；2. 各列一種可觀察現象；3. 加入照片日期、位置與不可見範圍欄。","instructionEn":"1. Divide a schematic into marine-fog, drainage and joint zones; 2. list one observable condition per zone; 3. add photo date, location and unseen-scope fields.","observation":"相同外觀缺陷在不同排水與暴露條件下可能有不同進展。","observationEn":"Similar visible defects can progress differently under different drainage and exposure conditions.","failure":"只用照片顏色就判定剩餘承載能力。","failureEn":"Infer remaining load capacity from photograph color alone.","check":"提交分區觀察表並標示不能由照片推出的結論。","checkEn":"Provide a zoned observation register and conclusions photographs cannot establish.","knowledge":[{"id":"b015-v7-19-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"腐蝕評估需連接環境、材料損失與構件功能；外觀是證據的一部分。","textEn":"Corrosion assessment links exposure, material loss and function; appearance supplies only part of the evidence."},{"id":"b015-v7-19-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"照片適合做位置與變化追蹤，但沒有比例與時間基準時不能直接量化損失。","textEn":"Photos track location and change, but cannot quantify loss without scale and time references."}],"quiz":{"question":"審查「制定分區腐蝕觀察表」時，哪個判讀有根據？","questionEn":"When reviewing “Create a corrosion-observation map”, which interpretation is justified?","options":["相同外觀缺陷在不同排水與暴露條件下可能有不同進展。","只用照片顏色就判定剩餘承載能力。","所有暴露區都能由同一張近照推定腐蝕狀態。"],"optionsEn":["Similar visible defects can progress differently under different drainage and exposure conditions.","Infer remaining load capacity from photograph color alone.","One close-up establishes corrosion conditions in every exposure zone."],"answer":0,"explanation":"腐蝕評估需連接環境、材料損失與構件功能；外觀是證據的一部分。 照片適合做位置與變化追蹤，但沒有比例與時間基準時不能直接量化損失。","explanationEn":"Corrosion assessment links exposure, material loss and function; appearance supplies only part of the evidence. Photos track location and change, but cannot quantify loss without scale and time references."}},{"id":"b015-v7-20","sequence":20,"order":2,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-19"],"title":"拆解吊索更新的依賴關係","titleEn":"Map hanger-renewal dependencies","objective":"看出構件更換前後的負載轉移問題。","objectiveEn":"Recognize load-transfer questions around component replacement.","instruction":"1. 在模型標示待更新吊索；2. 畫出可能受影響的相鄰橋面區；3. 列出臨時狀態分析與復核紀錄兩類先決證據。","instructionEn":"1. Mark a hypothetical renewal hanger; 2. map adjacent deck areas potentially affected; 3. list temporary-state analysis and verification records as prerequisites.","observation":"更換一個局部承重元件會影響鄰近系統的受力與幾何。","observationEn":"Replacing one local load-bearing element affects neighboring forces and geometry.","failure":"零件尺寸相同就可忽略更換時的負載轉移。","failureEn":"Matching component dimensions makes load transfer during replacement irrelevant.","check":"輸出依賴圖，明確區分概念審查與現場作業。","checkEn":"Produce a dependency map distinguishing conceptual review from field work.","knowledge":[{"id":"b015-v7-20-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"承重構件不能被視為隨意可抽換的積木，臨時平衡也是設計問題。","textEn":"Load-bearing components are not freely removable blocks; temporary equilibrium is a design question."},{"id":"b015-v7-20-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"歷史更新案例可提示應查哪些證據，但不提供今天可直接照做的工序。","textEn":"Historical renewal cases suggest evidence needs but do not supply present-day executable procedures."}],"quiz":{"question":"審查「拆解吊索更新的依賴關係」時，哪個判讀有根據？","questionEn":"When reviewing “Map hanger-renewal dependencies”, which interpretation is justified?","options":["零件尺寸相同就可忽略更換時的負載轉移。","更換一個局部承重元件會影響鄰近系統的受力與幾何。","吊索更換只影響新吊索，不影響鄰近橋面。"],"optionsEn":["Matching component dimensions makes load transfer during replacement irrelevant.","Replacing one local load-bearing element affects neighboring forces and geometry.","Hanger replacement affects only the new hanger, not adjacent deck areas."],"answer":1,"explanation":"承重構件不能被視為隨意可抽換的積木，臨時平衡也是設計問題。 歷史更新案例可提示應查哪些證據，但不提供今天可直接照做的工序。","explanationEn":"Load-bearing components are not freely removable blocks; temporary equilibrium is a design question. Historical renewal cases suggest evidence needs but do not supply present-day executable procedures."}},{"id":"b015-v7-21","sequence":21,"order":3,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-20"],"title":"建立耐震改造的性能矩陣","titleEn":"Build a seismic-performance matrix","objective":"區分構件加強、位移容許及能量耗散。","objectiveEn":"Distinguish strengthening, movement accommodation and energy dissipation.","instruction":"1. 列出橋塔、橋面連接及引橋；2. 對每項寫下力、位移與功能問題；3. 比較三種概念改造目的而不設定實橋參數。","instructionEn":"1. List towers, deck connections and approaches; 2. identify force, displacement and function questions; 3. compare three rehabilitation aims without assigning real-bridge settings.","observation":"更強的局部構件可能把更多地震作用傳到相鄰介面。","observationEn":"A stronger local member can transfer more seismic demand into adjacent interfaces.","failure":"提高局部剛度就保證整座橋所有部位的需求都降低。","failureEn":"Increasing local stiffness guarantees lower demand everywhere in the bridge.","check":"繳交性能目標、介面影響與查證方式的矩陣。","checkEn":"Submit a matrix of performance aims, interface effects and verification methods.","knowledge":[{"id":"b015-v7-21-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"耐震性能同時包含強度、變形能力與功能維持；單一安全係數不能描述全部。","textEn":"Seismic performance involves strength, deformation capacity and function; one safety factor cannot describe all of it."},{"id":"b015-v7-21-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"營運者的分期改造提供案例背景，課程不宣稱任一期在今天已完工。","textEn":"The operator’s phased rehabilitation provides context; this course makes no claim that a particular phase is complete today."}],"quiz":{"question":"審查「建立耐震改造的性能矩陣」時，哪個判讀有根據？","questionEn":"When reviewing “Build a seismic-performance matrix”, which interpretation is justified?","options":["提高局部剛度就保證整座橋所有部位的需求都降低。","能量耗散與局部材料強度是完全相同的性能量。","更強的局部構件可能把更多地震作用傳到相鄰介面。"],"optionsEn":["Increasing local stiffness guarantees lower demand everywhere in the bridge.","Energy dissipation and local material strength are identical performance quantities.","A stronger local member can transfer more seismic demand into adjacent interfaces."],"answer":2,"explanation":"耐震性能同時包含強度、變形能力與功能維持；單一安全係數不能描述全部。 營運者的分期改造提供案例背景，課程不宣稱任一期在今天已完工。","explanationEn":"Seismic performance involves strength, deformation capacity and function; one safety factor cannot describe all of it. The operator’s phased rehabilitation provides context; this course makes no claim that a particular phase is complete today."}},{"id":"b015-v7-22","sequence":22,"order":4,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-21"],"title":"辨識量測漂移與結構變化","titleEn":"Distinguish sensor drift from structural change","objective":"避免把單一異常訊號當成唯一原因。","objectiveEn":"Avoid treating a single anomalous signal as a unique diagnosis.","instruction":"1. 自設兩個位移與一個溫度序列；2. 加入單點偏移及共同趨勢；3. 列出交叉感測與基準複測的查證次序。","instructionEn":"1. Create two displacement series and one temperature series; 2. add a single-point offset and shared trend; 3. define cross-sensor and datum rechecks.","observation":"多個獨立訊號的一致趨勢比單點跳動更能支持系統性變化。","observationEn":"Consistent trends across independent signals support system-wide change better than one jump.","failure":"任何超出過去範圍的數字都能直接定位受損構件。","failureEn":"Any reading outside its historical range directly identifies a damaged component.","check":"提交包含至少兩個替代解釋的異常判讀單。","checkEn":"Submit an anomaly review with at least two alternative explanations.","knowledge":[{"id":"b015-v7-22-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"感測器漂移、環境影響與真實變形都可能產生異常；需辨識而非只報警。","textEn":"Sensor drift, environmental effects and real deformation can all create anomalies; interpretation is needed beyond an alarm."},{"id":"b015-v7-22-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"自設數據只能驗證判讀方法，不能估計真橋的當前健康狀態。","textEn":"Synthetic data test interpretation methods and cannot estimate the actual bridge’s current condition."}],"quiz":{"question":"審查「辨識量測漂移與結構變化」時，哪個判讀有根據？","questionEn":"When reviewing “Distinguish sensor drift from structural change”, which interpretation is justified?","options":["多個獨立訊號的一致趨勢比單點跳動更能支持系統性變化。","任何超出過去範圍的數字都能直接定位受損構件。","同一感測器重複輸出的數字就等同多個獨立證據。"],"optionsEn":["Consistent trends across independent signals support system-wide change better than one jump.","Any reading outside its historical range directly identifies a damaged component.","Repeated output from one sensor equals multiple independent evidence sources."],"answer":0,"explanation":"感測器漂移、環境影響與真實變形都可能產生異常；需辨識而非只報警。 自設數據只能驗證判讀方法，不能估計真橋的當前健康狀態。","explanationEn":"Sensor drift, environmental effects and real deformation can all create anomalies; interpretation is needed beyond an alarm. Synthetic data test interpretation methods and cannot estimate the actual bridge’s current condition."}},{"id":"b015-v7-23","sequence":23,"order":5,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-22"],"title":"比較明石海峽與淡江大橋","titleEn":"Compare Akashi Kaikyo and Danjiang bridges","objective":"辨認可轉移工法與不可直接移植的假設。","objectiveEn":"Identify transferable methods and nontransferable assumptions.","instruction":"1. 並排畫金門、明石與淡江橋型；2. 對比主纜吊索與斜張索力路徑；3. 列出場址、風與基礎必須重新查證的差異。","instructionEn":"1. Sketch Golden Gate, Akashi Kaikyo and Danjiang forms; 2. contrast main-cable/hanger and stay force paths; 3. list site, wind and foundation differences needing new evidence.","observation":"量測追溯與介面審查可轉移，但橋型和場址參數須重新建立。","observationEn":"Measurement traceability and interface review transfer, but bridge form and site parameters require rebuilding.","failure":"同為跨水大橋便能沿用同一組索力與基礎條件。","failureEn":"Every water-crossing bridge can reuse identical cable forces and foundation conditions.","check":"繳交三項相似處與三項禁止直接套用的差異。","checkEn":"Provide three similarities and three differences that prevent direct reuse.","knowledge":[{"id":"b015-v7-23-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"比較工程的價值在辨認相同問題的不同解法，不在尋找外觀最相近的照片。","textEn":"Engineering comparison identifies different solutions to related problems rather than merely similar photographs."},{"id":"b015-v7-23-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"懸索與斜張橋都需幾何及張力協調，但力路徑和施工狀態不同。","textEn":"Suspension and cable-stayed bridges both coordinate geometry and tension but have different force paths and construction states."}],"quiz":{"question":"審查「比較明石海峽與淡江大橋」時，哪個判讀有根據？","questionEn":"When reviewing “Compare Akashi Kaikyo and Danjiang bridges”, which interpretation is justified?","options":["同為跨水大橋便能沿用同一組索力與基礎條件。","量測追溯與介面審查可轉移，但橋型和場址參數須重新建立。","不同場址的風與地質條件可由橋梁外觀相似程度換算。"],"optionsEn":["Every water-crossing bridge can reuse identical cable forces and foundation conditions.","Measurement traceability and interface review transfer, but bridge form and site parameters require rebuilding.","Visual similarity between bridges determines corresponding wind and ground conditions."],"answer":1,"explanation":"比較工程的價值在辨認相同問題的不同解法，不在尋找外觀最相近的照片。 懸索與斜張橋都需幾何及張力協調，但力路徑和施工狀態不同。","explanationEn":"Engineering comparison identifies different solutions to related problems rather than merely similar photographs. Suspension and cable-stayed bridges both coordinate geometry and tension but have different force paths and construction states."}},{"id":"b015-v7-24","sequence":24,"order":6,"sourceIds":["v7-golden-improvements","v7-golden-seismic","v7-golden-history"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b015-v7-23"],"title":"總工程師交付證據包","titleEn":"Deliver the chief-engineer evidence pack","objective":"把完整課程整理成可複查的工程論證。","objectiveEn":"Turn the course into an auditable engineering argument.","instruction":"1. 彙整場址、受力、狀態及維護圖；2. 給每個結論連上一個來源或模型假設；3. 保留三個仍需專業調查才能回答的問題。","instructionEn":"1. Assemble site, force, state and maintenance diagrams; 2. attach a source or model assumption to every conclusion; 3. retain three questions requiring professional investigation.","observation":"完整交付包含未解問題和適用範圍，而非只有通過標記。","observationEn":"A complete handover includes unresolved questions and applicability limits, not just pass marks.","failure":"課程操作完成就等於具備現地橋梁施工資格。","failureEn":"Completing the course establishes qualification to construct a real bridge.","check":"提交帶版本、來源及限制的四頁概念工程包。","checkEn":"Submit a four-page conceptual engineering pack with versions, sources and limits.","knowledge":[{"id":"b015-v7-24-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"工程論證由要求、模型、證據及限制串起來；漂亮圖面本身不是驗證。","textEn":"An engineering argument joins requirements, models, evidence and limits; a polished diagram is not verification."},{"id":"b015-v7-24-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本課程完成的是概念與證據組織能力，不是金門大橋的原始施工設計。","textEn":"This course develops conceptual and evidence-organizing skills, not the Golden Gate Bridge’s original construction design."}],"quiz":{"question":"審查「總工程師交付證據包」時，哪個判讀有根據？","questionEn":"When reviewing “Deliver the chief-engineer evidence pack”, which interpretation is justified?","options":["課程操作完成就等於具備現地橋梁施工資格。","未解問題應從交付資料刪除，以免影響完整性。","完整交付包含未解問題和適用範圍，而非只有通過標記。"],"optionsEn":["Completing the course establishes qualification to construct a real bridge.","Open questions should be removed from handover records to preserve completeness.","A complete handover includes unresolved questions and applicability limits, not just pass marks."],"answer":2,"explanation":"工程論證由要求、模型、證據及限制串起來；漂亮圖面本身不是驗證。 本課程完成的是概念與證據組織能力，不是金門大橋的原始施工設計。","explanationEn":"An engineering argument joins requirements, models, evidence and limits; a polished diagram is not verification. This course develops conceptual and evidence-organizing skills, not the Golden Gate Bridge’s original construction design."}}]},{"id":"b015-v13-s1","title":"工程背景、荷載與結構系統","titleEn":"Context, loads and structural system","description":"本階段聚焦「由塔頂荷重反推主纜張力」與「主纜重力勁度與橫向變位」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Back-calculating cable tension from tower load\" and \"Cable gravity stiffness and lateral deflection\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b015-v13-01","title":"由塔頂荷重反推主纜張力：機制與傳力路徑","titleEn":"Back-calculating cable tension from tower load: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v7-24"],"objective":"說明「每塔 61,500 噸纜力」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “61,500-ton cable load per tower” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"業主資料指出兩條主纜施加在每座橋塔的荷重約 61,500 噸（美噸）。這個豎向力等於主跨與邊跨主纜在索鞍兩側的豎向分量之和，因此只要知道兩側主纜在塔頂的傾角，就能反推主纜水平張力與最大張力，再與鋼絲面積及強度比較得到安全係數。這種「由支承反力反推內力」的檢核，是評估既有懸索橋時最常用的獨立驗算，可與原始計算書或有限元素模型相互印證。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「每塔 61,500 噸纜力」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Owner data state that the two main cables place about 61,500 tons (short tons) on each tower. This vertical force is the sum of the vertical components of the main-span and side-span cables on either side of the saddle, so knowing the cable angles at the tower top gives the horizontal and maximum tensions, which can then be compared with wire area and strength for a safety factor. Back-calculating internal forces from support reactions is the most common independent check when evaluating an existing suspension bridge, cross-checking the original calculations or a finite-element model. Mentor task: draw a free-body or load-path diagram showing how loads pass through “61,500-ton cable load per tower” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：V = 61,500 short ton×907.2 kg×9.81 ≈ 547 MN。","observationEn":"Order-of-magnitude cue: V = 61,500 short tons×907.2 kg×9.81 ≈ 547 MN.","failure":"常見誤解：「塔頂荷重就等於主纜張力。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The load on the tower equals the cable tension.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「每塔 61,500 噸纜力」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “61,500-ton cable load per tower”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-01-k1","title":"由塔頂荷重反推主纜張力","titleEn":"Back-calculating cable tension from tower load","text":"業主資料指出兩條主纜施加在每座橋塔的荷重約 61,500 噸（美噸）。這個豎向力等於主跨與邊跨主纜在索鞍兩側的豎向分量之和，因此只要知道兩側主纜在塔頂的傾角，就能反推主纜水平張力與最大張力，再與鋼絲面積及強度比較得到安全係數。","textEn":"Owner data state that the two main cables place about 61,500 tons (short tons) on each tower. This vertical force is the sum of the vertical components of the main-span and side-span cables on either side of the saddle, so knowing the cable angles at the tower top gives the horizontal and maximum tensions, which can then be compared with wire area and strength for a safety factor.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：塔頂荷重就等於主纜張力。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The load on the tower equals the cable tension. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「由塔頂荷重反推主纜張力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Back-calculating cable tension from tower load\" is correct?","options":["塔頂荷重就等於主纜張力。","業主資料指出兩條主纜施加在每座橋塔的荷重約 61,500 噸（美噸）。","懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。"],"optionsEn":["The load on the tower equals the cable tension.","Owner data state that the two main cables place about 61,500 tons (short tons) on each tower.","A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load."],"answer":1,"explanation":"業主資料指出兩條主纜施加在每座橋塔的荷重約 61,500 噸（美噸）。 其餘選項是常見誤解。","explanationEn":"Owner data state that the two main cables place about 61,500 tons (short tons) on each tower. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b015-v13-02","title":"由塔頂荷重反推主纜張力：定量估算","titleEn":"Back-calculating cable tension from tower load: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-01"],"objective":"以數值模型估算「每塔 61,500 噸纜力」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “61,500-ton cable load per tower” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：V = 61,500 short ton×907.2 kg×9.81 ≈ 547 MN。取主跨 tanθ_m = 0.44、邊跨 tanθ_s = 0.40：H = V/(0.44+0.40) ≈ 651 MN（兩纜），每纜 326 MN；T = 326×√(1+0.44²) ≈ 356 MN。每纜鋼絲面積 27,572×18.68 mm² ≈ 515,000 mm²，應力 ≈ 691 N/mm²，對最低強度 1,517 N/mm² 的係數約 2.19。傾角為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: V = 61,500 short tons×907.2 kg×9.81 ≈ 547 MN. Taking tanθ_m = 0.44 for the main span and tanθ_s = 0.40 for the side span: H = V/(0.44+0.40) ≈ 651 MN for both cables, 326 MN each; T = 326×√(1+0.44²) ≈ 356 MN. Wire area per cable 27,572×18.68 mm² ≈ 515,000 mm² gives a stress of about 691 N/mm², a factor of about 2.19 on the 1,517 N/mm² minimum strength. The angles are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以竣工測量或光達掃描取得塔頂兩側主纜實際傾角，代回計算 H 與 T，並與原設計值和有限元素模型比較；若三者差異超過約定範圍，檢查恆載假設（例如 1986 年更換後的橋面重量）與塔頂索鞍位置。","observationEn":"How to cross-check: Obtain actual cable angles on both sides of the tower top from as-built survey or lidar, recompute H and T, and compare with original design values and the finite-element model; if the three differ beyond an agreed band, check dead-load assumptions such as the deck weight after the 1986 replacement and the saddle positions.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"V = 61,500 short ton×907.2 kg×9.81 ≈ 547 MN。取主跨 tanθ_m = 0.44、邊跨 tanθ_s = 0.40：H = V/(0.44+0.40) ≈ 651 MN（兩纜），每纜 326 MN；T = 326×√(1+0.44²) ≈ 356 MN。每纜鋼絲面積 27,572×18.68 mm² ≈ 515,000 mm²，應力 ≈ 691 N/mm²，對最低強度 1,517 N/mm² 的係數約 2.19。傾角為教學假設。","textEn":"V = 61,500 short tons×907.2 kg×9.81 ≈ 547 MN. Taking tanθ_m = 0.44 for the main span and tanθ_s = 0.40 for the side span: H = V/(0.44+0.40) ≈ 651 MN for both cables, 326 MN each; T = 326×√(1+0.44²) ≈ 356 MN. Wire area per cable 27,572×18.68 mm² ≈ 515,000 mm² gives a stress of about 691 N/mm², a factor of about 2.19 on the 1,517 N/mm² minimum strength. The angles are teaching assumptions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「由塔頂荷重反推主纜張力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Back-calculating cable tension from tower load\", which statement holds?","options":["吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。","把橋面換輕只會讓橋更安全，不會改變幾何。","V = 61,500 short ton×907.2 kg×9.81 ≈ 547 MN。"],"optionsEn":["Suspenders are just thin ropes hanging the deck; losing one or two does not matter.","A lighter deck only makes the bridge safer; it does not change the geometry.","V = 61,500 short tons×907.2 kg×9.81 ≈ 547 MN."],"answer":2,"explanation":"V = 61,500 short ton×907.2 kg×9.81 ≈ 547 MN。 重算時請保留單位。","explanationEn":"V = 61,500 short tons×907.2 kg×9.81 ≈ 547 MN. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":26},{"id":"b015-v13-03","title":"由塔頂荷重反推主纜張力：試驗與驗證","titleEn":"Back-calculating cable tension from tower load: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「每塔 61,500 噸纜力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “61,500-ton cable load per tower” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以竣工測量或光達掃描取得塔頂兩側主纜實際傾角，代回計算 H 與 T，並與原設計值和有限元素模型比較；若三者差異超過約定範圍，檢查恆載假設（例如 1986 年更換後的橋面重量）與塔頂索鞍位置。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Obtain actual cable angles on both sides of the tower top from as-built survey or lidar, recompute H and T, and compare with original design values and the finite-element model; if the three differ beyond an agreed band, check dead-load assumptions such as the deck weight after the 1986 replacement and the saddle positions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：既有懸索橋的評估報告應附一份「恆載履歷表」，逐項列出歷次改造增減的重量與日期，並以塔頂反力與主纜幾何做獨立驗算，作為與有限元素模型比對的基準。","observationEn":"Site practice: An evaluation of an existing suspension bridge should include a dead-load history listing the weight added or removed by each modification with dates, and an independent check from tower reactions and cable geometry as the benchmark for the finite-element model.","failure":"注意干擾：若評估仍沿用 1937 年的恆載而忽略後來的橋面更換、加勁與附加設施，計算出的主纜應力與安全係數會偏離實際；反過來若遺漏新增荷重（防墜網、抗風整流板），可能高估剩餘容量。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: An evaluation still using 1937 dead loads, ignoring later deck replacement, bracing and attachments, misstates cable stress and safety factor; conversely, missing added loads such as the deterrent net or wind fairings can overstate remaining capacity. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-03-k1","title":"驗證方法","titleEn":"Verification method","text":"以竣工測量或光達掃描取得塔頂兩側主纜實際傾角，代回計算 H 與 T，並與原設計值和有限元素模型比較；若三者差異超過約定範圍，檢查恆載假設（例如 1986 年更換後的橋面重量）與塔頂索鞍位置。","textEn":"Obtain actual cable angles on both sides of the tower top from as-built survey or lidar, recompute H and T, and compare with original design values and the finite-element model; if the three differ beyond an agreed band, check dead-load assumptions such as the deck weight after the 1986 replacement and the saddle positions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-03-k2","title":"現場實務","titleEn":"Site practice","text":"既有懸索橋的評估報告應附一份「恆載履歷表」，逐項列出歷次改造增減的重量與日期，並以塔頂反力與主纜幾何做獨立驗算，作為與有限元素模型比對的基準。","textEn":"An evaluation of an existing suspension bridge should include a dead-load history listing the weight added or removed by each modification with dates, and an independent check from tower reactions and cable geometry as the benchmark for the finite-element model.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「由塔頂荷重反推主纜張力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Back-calculating cable tension from tower load\"?","options":["以竣工測量或光達掃描取得塔頂兩側主纜實際傾角，代回計算 H 與 T，並與原設計值和有限元素模型比較。","量測時不必記錄溫度、日照、風與施工荷重，因為它們不會影響結果。","螺栓一旦鎖到規定張力，就能永久保持。"],"optionsEn":["Obtain actual cable angles on both sides of the tower top from as-built survey or lidar, recompute H and T, and compare with original design values and the finite-element model.","Temperature, sunshine, wind and construction loads need not be recorded because they cannot affect the result.","Once bolts are tightened to the specified tension, they keep it forever."],"answer":0,"explanation":"以竣工測量或光達掃描取得塔頂兩側主纜實際傾角，代回計算 H 與 T，並與原設計值和有限元素模型比較；若三者差異超過約定範圍，檢查恆載假設（例如 1986 年更換後的橋面重量）與塔頂索鞍位置。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Obtain actual cable angles on both sides of the tower top from as-built survey or lidar, recompute H and T, and compare with original design values and the finite-element model; if the three differ beyond an agreed band, check dead-load assumptions such as the deck weight after the 1986 replacement and the saddle positions. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":27},{"id":"b015-v13-04","title":"由塔頂荷重反推主纜張力：失效診斷","titleEn":"Back-calculating cable tension from tower load: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-03"],"objective":"從症狀倒推「每塔 61,500 噸纜力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “61,500-ton cable load per tower” and propose discriminating checks, corrective actions and prevention.","instruction":"若評估仍沿用 1937 年的恆載而忽略後來的橋面更換、加勁與附加設施，計算出的主纜應力與安全係數會偏離實際；反過來若遺漏新增荷重（防墜網、抗風整流板），可能高估剩餘容量。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"An evaluation still using 1937 dead loads, ignoring later deck replacement, bracing and attachments, misstates cable stress and safety factor; conversely, missing added loads such as the deterrent net or wind fairings can overstate remaining capacity. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：這種「由支承反力反推內力」的檢核，是評估既有懸索橋時最常用的獨立驗算，可與原始計算書或有限元素模型相互印證。","observationEn":"Link to the mechanism: Back-calculating internal forces from support reactions is the most common independent check when evaluating an existing suspension bridge, cross-checking the original calculations or a finite-element model.","failure":"誤判風險：若相信「塔頂荷重就等於主纜張力。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The load on the tower equals the cable tension.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-04-k1","title":"失效模式","titleEn":"Failure mode","text":"若評估仍沿用 1937 年的恆載而忽略後來的橋面更換、加勁與附加設施，計算出的主纜應力與安全係數會偏離實際；反過來若遺漏新增荷重（防墜網、抗風整流板），可能高估剩餘容量。","textEn":"An evaluation still using 1937 dead loads, ignoring later deck replacement, bracing and attachments, misstates cable stress and safety factor; conversely, missing added loads such as the deterrent net or wind fairings can overstate remaining capacity.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「由塔頂荷重反推主纜張力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Back-calculating cable tension from tower load\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","若評估仍沿用 1937 年的恆載而忽略後來的橋面更換、加勁與附加設施，計算出的主纜應力與安全係數會偏離實際。","懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","An evaluation still using 1937 dead loads, ignoring later deck replacement, bracing and attachments, misstates cable stress and safety factor.","A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load."],"answer":1,"explanation":"若評估仍沿用 1937 年的恆載而忽略後來的橋面更換、加勁與附加設施，計算出的主纜應力與安全係數會偏離實際；反過來若遺漏新增荷重（防墜網、抗風整流板），可能高估剩餘容量。 需以量測區分可能原因。","explanationEn":"An evaluation still using 1937 dead loads, ignoring later deck replacement, bracing and attachments, misstates cable stress and safety factor; conversely, missing added loads such as the deterrent net or wind fairings can overstate remaining capacity. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":28},{"id":"b015-v13-05","title":"主纜重力勁度與橫向變位：機制與傳力路徑","titleEn":"Cable gravity stiffness and lateral deflection: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-04"],"objective":"說明「27.7 ft 橫向變位」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “27.7 ft lateral deflection” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"業主資料列出主跨中央最大橫向變位約 27.7 ft（約 8.4 m），遠大於最大下垂 10.8 ft 與上揚 5.8 ft。懸索橋抵抗側風的勁度主要不是來自加勁桁架的側向彎曲，而是來自主纜的「重力勁度」：受張的主纜像鐘擺一樣，被側向推開時，張力的水平分量會把它拉回中心。張力越大、跨徑越短，回復力越強；1950 年代增設的下層橫向斜撐則提高了橋面本身的側向與扭轉勁度，兩者共同決定側風下的變位與振動特性。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「27.7 ft 橫向變位」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Owner data list a maximum transverse deflection at mid-span of about 27.7 ft (about 8.4 m), far more than the maximum downward 10.8 ft and upward 5.8 ft. A suspension bridge resists crosswind mainly not through lateral bending of the stiffening truss but through the gravity stiffness of the cables: like a pendulum, a tensioned cable pushed sideways is pulled back by the horizontal component of its tension. Higher tension and shorter span give stronger restoring force; the lower lateral bracing added in the 1950s raised the deck's own lateral and torsional stiffness, and the two together set deflection and vibration in crosswinds. Mentor task: draw a free-body or load-path diagram showing how loads pass through “27.7 ft lateral deflection” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：以弦受側向均布力估算 δ = w_L·l²/(8H)。","observationEn":"Order-of-magnitude cue: Estimate with a string under uniform lateral load δ = w_L·l²/(8H).","failure":"常見誤解：「懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「27.7 ft 橫向變位」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “27.7 ft lateral deflection”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-05-k1","title":"主纜重力勁度與橫向變位","titleEn":"Cable gravity stiffness and lateral deflection","text":"業主資料列出主跨中央最大橫向變位約 27.7 ft（約 8.4 m），遠大於最大下垂 10.8 ft 與上揚 5.8 ft。懸索橋抵抗側風的勁度主要不是來自加勁桁架的側向彎曲，而是來自主纜的「重力勁度」：受張的主纜像鐘擺一樣，被側向推開時，張力的水平分量會把它拉回中心。","textEn":"Owner data list a maximum transverse deflection at mid-span of about 27.7 ft (about 8.4 m), far more than the maximum downward 10.8 ft and upward 5.8 ft. A suspension bridge resists crosswind mainly not through lateral bending of the stiffening truss but through the gravity stiffness of the cables: like a pendulum, a tensioned cable pushed sideways is pulled back by the horizontal component of its tension.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「主纜重力勁度與橫向變位」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cable gravity stiffness and lateral deflection\" is correct?","options":["懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。","老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。","業主資料列出主跨中央最大橫向變位約 27.7 ft（約 8.4 m），遠大於最大下垂 10.8 ft 與上揚 5.8 ft。"],"optionsEn":["A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load.","Old bridge wire is always far below its specification, so testing is pointless.","Owner data list a maximum transverse deflection at mid-span of about 27.7 ft (about 8.4 m), far more than the maximum downward 10.8 ft and upward 5.8 ft."],"answer":2,"explanation":"業主資料列出主跨中央最大橫向變位約 27.7 ft（約 8.4 m），遠大於最大下垂 10.8 ft 與上揚 5.8 ft。 其餘選項是常見誤解。","explanationEn":"Owner data list a maximum transverse deflection at mid-span of about 27.7 ft (about 8.4 m), far more than the maximum downward 10.8 ft and upward 5.8 ft. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b015-v13-06","title":"主纜重力勁度與橫向變位：定量估算","titleEn":"Cable gravity stiffness and lateral deflection: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-05"],"objective":"以數值模型估算「27.7 ft 橫向變位」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “27.7 ft lateral deflection” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：以弦受側向均布力估算 δ = w_L·l²/(8H)。取 H = 651 MN（兩纜合計）、l = 1,280 m、側向風力 w_L = 15 kN/m：δ = 15×1,280²/(8×651,000) ≈ 4.7 m；反算達到 8.4 m 需 w_L ≈ 8×651,000×8.44/1,280² ≈ 26.9 kN/m。忽略桁架側向勁度，為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Estimate with a string under uniform lateral load δ = w_L·l²/(8H). With H = 651 MN for both cables, l = 1,280 m and lateral wind load w_L = 15 kN/m: δ = 15×1,280²/(8×651,000) ≈ 4.7 m; reaching 8.4 m would need w_L ≈ 8×651,000×8.44/1,280² ≈ 26.9 kN/m. Truss lateral stiffness is ignored; values are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以 GNSS 在跨中與四分點量測強風中的側向位移，同步記錄橋面高度的風速風向，將位移對風壓（∝U²）作圖，檢查斜率是否符合重力勁度加桁架勁度的模型；並比較伸縮縫與風支承在側向位移時的行程。","observationEn":"How to cross-check: Measure lateral displacement in strong wind with GNSS at mid-span and quarter points, recording deck-level wind speed and direction, plot displacement against wind pressure (∝U²) and check the slope against a gravity-plus-truss stiffness model; also compare the travel of expansion joints and wind shoes during lateral movement.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"以弦受側向均布力估算 δ = w_L·l²/(8H)。取 H = 651 MN（兩纜合計）、l = 1,280 m、側向風力 w_L = 15 kN/m：δ = 15×1,280²/(8×651,000) ≈ 4.7 m；反算達到 8.4 m 需 w_L ≈ 8×651,000×8.44/1,280² ≈ 26.9 kN/m。忽略桁架側向勁度，為教學假設。","textEn":"Estimate with a string under uniform lateral load δ = w_L·l²/(8H). With H = 651 MN for both cables, l = 1,280 m and lateral wind load w_L = 15 kN/m: δ = 15×1,280²/(8×651,000) ≈ 4.7 m; reaching 8.4 m would need w_L ≈ 8×651,000×8.44/1,280² ≈ 26.9 kN/m. Truss lateral stiffness is ignored; values are teaching assumptions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「主纜重力勁度與橫向變位」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cable gravity stiffness and lateral deflection\", which statement holds?","options":["以弦受側向均布力估算 δ = w_L·l²/(8H)。","空中紡線的速度只取決於紡線輪跑多快。","只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。"],"optionsEn":["Estimate with a string under uniform lateral load δ = w_L·l²/(8H).","Aerial-spinning speed depends only on how fast the wheels run.","If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems."],"answer":0,"explanation":"以弦受側向均布力估算 δ = w_L·l²/(8H)。 重算時請保留單位。","explanationEn":"Estimate with a string under uniform lateral load δ = w_L·l²/(8H). Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":30},{"id":"b015-v13-07","title":"主纜重力勁度與橫向變位：試驗與驗證","titleEn":"Cable gravity stiffness and lateral deflection: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「27.7 ft 橫向變位」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “27.7 ft lateral deflection” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以 GNSS 在跨中與四分點量測強風中的側向位移，同步記錄橋面高度的風速風向，將位移對風壓（∝U²）作圖，檢查斜率是否符合重力勁度加桁架勁度的模型；並比較伸縮縫與風支承在側向位移時的行程。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure lateral displacement in strong wind with GNSS at mid-span and quarter points, recording deck-level wind speed and direction, plot displacement against wind pressure (∝U²) and check the slope against a gravity-plus-truss stiffness model; also compare the travel of expansion joints and wind shoes during lateral movement. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：任何會增加橋面受風面積或改變斷面形狀的工程，都要在設計階段提出側風變位與氣動穩定的評估，並由業主的風工程顧問核可；評估須同時列出伸縮縫、風支承與管線的位移容量。","observationEn":"Site practice: Any work that adds wind area or changes the deck section must come with an assessment of lateral deflection and aerodynamic stability at design stage, approved by the owner's wind consultant, listing the displacement capacity of joints, wind shoes and services.","failure":"注意干擾：若改造增加了橋面側向受風面積（例如加裝圍欄或設備）而未更新側風分析，實際橫向變位與伸縮縫行程需求可能超出原設計；側向勁度不足也會讓渦振與扭轉耦合更容易發生。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: If a modification increases the deck's lateral wind area, such as new fencing or equipment, without updating the crosswind analysis, actual lateral deflection and joint travel demand may exceed design; low lateral stiffness also makes vortex and torsional coupling easier. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-07-k1","title":"驗證方法","titleEn":"Verification method","text":"以 GNSS 在跨中與四分點量測強風中的側向位移，同步記錄橋面高度的風速風向，將位移對風壓（∝U²）作圖，檢查斜率是否符合重力勁度加桁架勁度的模型；並比較伸縮縫與風支承在側向位移時的行程。","textEn":"Measure lateral displacement in strong wind with GNSS at mid-span and quarter points, recording deck-level wind speed and direction, plot displacement against wind pressure (∝U²) and check the slope against a gravity-plus-truss stiffness model; also compare the travel of expansion joints and wind shoes during lateral movement.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-07-k2","title":"現場實務","titleEn":"Site practice","text":"任何會增加橋面受風面積或改變斷面形狀的工程，都要在設計階段提出側風變位與氣動穩定的評估，並由業主的風工程顧問核可；評估須同時列出伸縮縫、風支承與管線的位移容量。","textEn":"Any work that adds wind area or changes the deck section must come with an assessment of lateral deflection and aerodynamic stability at design stage, approved by the owner's wind consultant, listing the displacement capacity of joints, wind shoes and services.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「主纜重力勁度與橫向變位」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cable gravity stiffness and lateral deflection\"?","options":["沿用另一座橋或另一棟建築的量測結果，就可視為本工程已完成驗證。","以 GNSS 在跨中與四分點量測強風中的側向位移，同步記錄橋面高度的風速風向，將位移對風壓（∝U²）作圖，檢查斜率是否符合重力勁度加桁架勁度的模型。","1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。"],"optionsEn":["Reusing results from another bridge or building counts as verifying this structure.","Measure lateral displacement in strong wind with GNSS at mid-span and quarter points, recording deck-level wind speed and direction, plot displacement against wind pressure (∝U²) and check the slope against a gravity-plus-truss stiffness model.","Because the bridge was undamaged in 1989, it does not need seismic retrofit."],"answer":1,"explanation":"以 GNSS 在跨中與四分點量測強風中的側向位移，同步記錄橋面高度的風速風向，將位移對風壓（∝U²）作圖，檢查斜率是否符合重力勁度加桁架勁度的模型；並比較伸縮縫與風支承在側向位移時的行程。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure lateral displacement in strong wind with GNSS at mid-span and quarter points, recording deck-level wind speed and direction, plot displacement against wind pressure (∝U²) and check the slope against a gravity-plus-truss stiffness model; also compare the travel of expansion joints and wind shoes during lateral movement. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":31},{"id":"b015-v13-08","title":"主纜重力勁度與橫向變位：失效診斷","titleEn":"Cable gravity stiffness and lateral deflection: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-07"],"objective":"從症狀倒推「27.7 ft 橫向變位」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “27.7 ft lateral deflection” and propose discriminating checks, corrective actions and prevention.","instruction":"若改造增加了橋面側向受風面積（例如加裝圍欄或設備）而未更新側風分析，實際橫向變位與伸縮縫行程需求可能超出原設計；側向勁度不足也會讓渦振與扭轉耦合更容易發生。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"If a modification increases the deck's lateral wind area, such as new fencing or equipment, without updating the crosswind analysis, actual lateral deflection and joint travel demand may exceed design; low lateral stiffness also makes vortex and torsional coupling easier. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：張力越大、跨徑越短，回復力越強；1950 年代增設的下層橫向斜撐則提高了橋面本身的側向與扭轉勁度，兩者共同決定側風下的變位與振動特性。","observationEn":"Link to the mechanism: Higher tension and shorter span give stronger restoring force; the lower lateral bracing added in the 1950s raised the deck's own lateral and torsional stiffness, and the two together set deflection and vibration in crosswinds.","failure":"誤判風險：若相信「懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-08-k1","title":"失效模式","titleEn":"Failure mode","text":"若改造增加了橋面側向受風面積（例如加裝圍欄或設備）而未更新側風分析，實際橫向變位與伸縮縫行程需求可能超出原設計；側向勁度不足也會讓渦振與扭轉耦合更容易發生。","textEn":"If a modification increases the deck's lateral wind area, such as new fencing or equipment, without updating the crosswind analysis, actual lateral deflection and joint travel demand may exceed design; low lateral stiffness also makes vortex and torsional coupling easier.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「主纜重力勁度與橫向變位」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cable gravity stiffness and lateral deflection\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。","若改造增加了橋面側向受風面積（例如加裝圍欄或設備）而未更新側風分析，實際橫向變位與伸縮縫行程需求可能超出原設計；側向勁度不足也會讓渦振與扭轉耦合更容易發生。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Old bridge wire is always far below its specification, so testing is pointless.","If a modification increases the deck's lateral wind area, such as new fencing or equipment, without updating the crosswind analysis, actual lateral deflection and joint travel demand may exceed design."],"answer":2,"explanation":"若改造增加了橋面側向受風面積（例如加裝圍欄或設備）而未更新側風分析，實際橫向變位與伸縮縫行程需求可能超出原設計；側向勁度不足也會讓渦振與扭轉耦合更容易發生。 需以量測區分可能原因。","explanationEn":"If a modification increases the deck's lateral wind area, such as new fencing or equipment, without updating the crosswind analysis, actual lateral deflection and joint travel demand may exceed design; low lateral stiffness also makes vortex and torsional coupling easier. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":32}],"order":5},{"id":"b015-v13-s2","title":"材料、構件與接合細部","titleEn":"Materials, members and connection details","description":"本階段聚焦「1930 年代鋼絲的強度與延性」與「吊索受力與 1970 年代全面更換」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Strength and ductility of the 1930s wire\" and \"Suspender forces and the 1970s full replacement\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b015-v13-09","title":"1930 年代鋼絲的強度與延性：機制與傳力路徑","titleEn":"Strength and ductility of the 1930s wire: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-08"],"objective":"說明「0.192 in 鍍鋅鋼絲」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “0.192 in galvanised wire” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"金門大橋每條主纜含 27,572 根直徑 0.192 in（約 4.88 mm）的鍍鋅鋼絲，分成 61 束、平均每束約 452 根，連同纏繞外徑約 36⅜ in（0.92 m）。業主公布的鋼絲平均抗拉強度 235,600 psi（規格最低 220,000 psi）、降伏強度 182,600 psi、斷裂伸長率 6.3%（最低 4.0%）。與現代 1,770 至 1,960 MPa 級鋼絲相比強度較低，但延性與降伏比較寬裕；評估既有主纜時，要用當時規格的最低值與實際抽樣結果，而不是現代鋼絲的數字。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「0.192 in 鍍鋅鋼絲」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Each Golden Gate cable contains 27,572 galvanised wires of 0.192 in (about 4.88 mm) diameter in 61 strands averaging about 452 wires, about 36⅜ in (0.92 m) in diameter with wrapping. The owner lists average wire tensile strength of 235,600 psi (220,000 psi specified minimum), yield of 182,600 psi and elongation at rupture of 6.3% (4.0% minimum). The strength is lower than modern 1,770 to 1,960 MPa wire, but ductility and yield ratio are generous; evaluating an existing cable must use the period specification minimum and actual sample results, not modern wire figures. Mentor task: draw a free-body or load-path diagram showing how loads pass through “0.192 in galvanised wire” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：換算：235,600 psi ≈ 1,624 N/mm²、220,000 psi ≈ 1,517 N/mm²、182,600 psi ≈ 1,259 N/mm²，降伏比 ≈ 0.775。","observationEn":"Order-of-magnitude cue: Conversions: 235,600 psi ≈ 1,624 N/mm², 220,000 psi ≈ 1,517 N/mm², 182,600 psi ≈ 1,259 N/mm², a yield ratio ≈ 0.775.","failure":"常見誤解：「老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Old bridge wire is always far below its specification, so testing is pointless.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「0.192 in 鍍鋅鋼絲」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “0.192 in galvanised wire”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-09-k1","title":"1930 年代鋼絲的強度與延性","titleEn":"Strength and ductility of the 1930s wire","text":"金門大橋每條主纜含 27,572 根直徑 0.192 in（約 4.88 mm）的鍍鋅鋼絲，分成 61 束、平均每束約 452 根，連同纏繞外徑約 36⅜ in（0.92 m）。業主公布的鋼絲平均抗拉強度 235,600 psi（規格最低 220,000 psi）、降伏強度 182,600 psi、斷裂伸長率 6.3%（最低 4.0%）。","textEn":"Each Golden Gate cable contains 27,572 galvanised wires of 0.192 in (about 4.88 mm) diameter in 61 strands averaging about 452 wires, about 36⅜ in (0.92 m) in diameter with wrapping. The owner lists average wire tensile strength of 235,600 psi (220,000 psi specified minimum), yield of 182,600 psi and elongation at rupture of 6.3% (4.0% minimum).","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Old bridge wire is always far below its specification, so testing is pointless. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「1930 年代鋼絲的強度與延性」，下列哪一項敘述正確？","questionEn":"Which statement about \"Strength and ductility of the 1930s wire\" is correct?","options":["金門大橋每條主纜含 27,572 根直徑 0.192 in（約 4.88 mm）的鍍鋅鋼絲，分成 61 束、平均每束約 452 根，連同纏繞外徑約 36⅜ in（0.92 m）。","老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。","吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。"],"optionsEn":["Each Golden Gate cable contains 27,572 galvanised wires of 0.192 in (about 4.88 mm) diameter in 61 strands averaging about 452 wires, about 36⅜ in (0.92 m) in diameter with wrapping.","Old bridge wire is always far below its specification, so testing is pointless.","Suspenders are just thin ropes hanging the deck; losing one or two does not matter."],"answer":0,"explanation":"金門大橋每條主纜含 27,572 根直徑 0.192 in（約 4.88 mm）的鍍鋅鋼絲，分成 61 束、平均每束約 452 根，連同纏繞外徑約 36⅜ in（0.92 m）。 其餘選項是常見誤解。","explanationEn":"Each Golden Gate cable contains 27,572 galvanised wires of 0.192 in (about 4.88 mm) diameter in 61 strands averaging about 452 wires, about 36⅜ in (0.92 m) in diameter with wrapping. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b015-v13-10","title":"1930 年代鋼絲的強度與延性：定量估算","titleEn":"Strength and ductility of the 1930s wire: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-09"],"objective":"以數值模型估算「0.192 in 鍍鋅鋼絲」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “0.192 in galvanised wire” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：換算：235,600 psi ≈ 1,624 N/mm²、220,000 psi ≈ 1,517 N/mm²、182,600 psi ≈ 1,259 N/mm²，降伏比 ≈ 0.775。單絲面積 π/4×4.877² ≈ 18.68 mm²，每纜面積 ≈ 515,000 mm²，以最低強度計破斷力 ≈ 781 MN。兩纜總長核算：2×27,572×2,332 m ≈ 128,600 km，與公布的約 129,000 km 一致。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Conversions: 235,600 psi ≈ 1,624 N/mm², 220,000 psi ≈ 1,517 N/mm², 182,600 psi ≈ 1,259 N/mm², a yield ratio ≈ 0.775. Wire area π/4×4.877² ≈ 18.68 mm², about 515,000 mm² per cable, for a minimum breaking force ≈ 781 MN. Total length check: 2×27,572×2,332 m ≈ 128,600 km, matching the published 129,000 km or so. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：開纜檢查時取出代表性鋼絲做拉伸、伸長率與扭轉試驗，並以金相與鍍鋅層量測判斷腐蝕階段；依試驗結果與斷絲統計建立剩餘強度模型，比較設計時的最低強度與實際分布。","observationEn":"How to cross-check: During cable openings remove representative wires for tensile, elongation and torsion tests, and assess corrosion stage by metallography and zinc measurement; build a remaining-strength model from test results and broken-wire counts, comparing the original specified minimum with the actual distribution.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"換算：235,600 psi ≈ 1,624 N/mm²、220,000 psi ≈ 1,517 N/mm²、182,600 psi ≈ 1,259 N/mm²，降伏比 ≈ 0.775。單絲面積 π/4×4.877² ≈ 18.68 mm²，每纜面積 ≈ 515,000 mm²，以最低強度計破斷力 ≈ 781 MN。兩纜總長核算：2×27,572×2,332 m ≈ 128,600 km，與公布的約 129,000 km 一致。","textEn":"Conversions: 235,600 psi ≈ 1,624 N/mm², 220,000 psi ≈ 1,517 N/mm², 182,600 psi ≈ 1,259 N/mm², a yield ratio ≈ 0.775. Wire area π/4×4.877² ≈ 18.68 mm², about 515,000 mm² per cable, for a minimum breaking force ≈ 781 MN. Total length check: 2×27,572×2,332 m ≈ 128,600 km, matching the published 129,000 km or so.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「1930 年代鋼絲的強度與延性」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Strength and ductility of the 1930s wire\", which statement holds?","options":["把橋面換輕只會讓橋更安全，不會改變幾何。","換算：235,600 psi ≈ 1,624 N/mm²、220,000 psi ≈ 1,517 N/mm²、182,600 psi ≈ 1,259 N/mm²，降伏比 ≈ 0.775。","螺栓一旦鎖到規定張力，就能永久保持。"],"optionsEn":["A lighter deck only makes the bridge safer; it does not change the geometry.","Conversions: 235,600 psi ≈ 1,624 N/mm², 220,000 psi ≈ 1,517 N/mm², 182,600 psi ≈ 1,259 N/mm², a yield ratio ≈ 0.775.","Once bolts are tightened to the specified tension, they keep it forever."],"answer":1,"explanation":"換算：235,600 psi ≈ 1,624 N/mm²、220,000 psi ≈ 1,517 N/mm²、182,600 psi ≈ 1,259 N/mm²，降伏比 ≈ 0.775。 重算時請保留單位。","explanationEn":"Conversions: 235,600 psi ≈ 1,624 N/mm², 220,000 psi ≈ 1,517 N/mm², 182,600 psi ≈ 1,259 N/mm², a yield ratio ≈ 0.775. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":34},{"id":"b015-v13-11","title":"1930 年代鋼絲的強度與延性：試驗與驗證","titleEn":"Strength and ductility of the 1930s wire: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「0.192 in 鍍鋅鋼絲」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “0.192 in galvanised wire” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"開纜檢查時取出代表性鋼絲做拉伸、伸長率與扭轉試驗，並以金相與鍍鋅層量測判斷腐蝕階段；依試驗結果與斷絲統計建立剩餘強度模型，比較設計時的最低強度與實際分布。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"During cable openings remove representative wires for tensile, elongation and torsion tests, and assess corrosion stage by metallography and zinc measurement; build a remaining-strength model from test results and broken-wire counts, comparing the original specified minimum with the actual distribution. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保存原始鋼絲規格與出廠試驗紀錄，每次開纜取樣都要記錄位置、束號與試驗結果，納入同一資料庫，讓日後的剩餘強度評估能追溯並比較趨勢。","observationEn":"Site practice: Keep the original wire specification and mill test records, and log location, strand number and results for every cable sample in one database so later remaining-strength evaluations can trace and compare trends.","failure":"注意干擾：若評估直接套用現代鋼絲強度，主纜安全係數會被高估；反之若只依外觀判斷而不做試驗，可能忽略內部鋼絲的脆化或腐蝕裂縫，延誤除濕或補強決策。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Applying modern wire strengths overstates the cable's safety factor; judging only by appearance without testing can miss embrittlement or corrosion cracking of inner wires and delay dehumidification or strengthening decisions. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-11-k1","title":"驗證方法","titleEn":"Verification method","text":"開纜檢查時取出代表性鋼絲做拉伸、伸長率與扭轉試驗，並以金相與鍍鋅層量測判斷腐蝕階段；依試驗結果與斷絲統計建立剩餘強度模型，比較設計時的最低強度與實際分布。","textEn":"During cable openings remove representative wires for tensile, elongation and torsion tests, and assess corrosion stage by metallography and zinc measurement; build a remaining-strength model from test results and broken-wire counts, comparing the original specified minimum with the actual distribution.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-11-k2","title":"現場實務","titleEn":"Site practice","text":"保存原始鋼絲規格與出廠試驗紀錄，每次開纜取樣都要記錄位置、束號與試驗結果，納入同一資料庫，讓日後的剩餘強度評估能追溯並比較趨勢。","textEn":"Keep the original wire specification and mill test records, and log location, strand number and results for every cable sample in one database so later remaining-strength evaluations can trace and compare trends.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「1930 年代鋼絲的強度與延性」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Strength and ductility of the 1930s wire\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。","開纜檢查時取出代表性鋼絲做拉伸、伸長率與扭轉試驗，並以金相與鍍鋅層量測判斷腐蝕階段；依試驗結果與斷絲統計建立剩餘強度模型，比較設計時的最低強度與實際分布。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","The deterrent net is a light accessory with no effect on structure or wind stability.","During cable openings remove representative wires for tensile, elongation and torsion tests, and assess corrosion stage by metallography and zinc measurement."],"answer":2,"explanation":"開纜檢查時取出代表性鋼絲做拉伸、伸長率與扭轉試驗，並以金相與鍍鋅層量測判斷腐蝕階段；依試驗結果與斷絲統計建立剩餘強度模型，比較設計時的最低強度與實際分布。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"During cable openings remove representative wires for tensile, elongation and torsion tests, and assess corrosion stage by metallography and zinc measurement; build a remaining-strength model from test results and broken-wire counts, comparing the original specified minimum with the actual distribution. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":35},{"id":"b015-v13-12","title":"1930 年代鋼絲的強度與延性：失效診斷","titleEn":"Strength and ductility of the 1930s wire: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-11"],"objective":"從症狀倒推「0.192 in 鍍鋅鋼絲」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “0.192 in galvanised wire” and propose discriminating checks, corrective actions and prevention.","instruction":"若評估直接套用現代鋼絲強度，主纜安全係數會被高估；反之若只依外觀判斷而不做試驗，可能忽略內部鋼絲的脆化或腐蝕裂縫，延誤除濕或補強決策。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Applying modern wire strengths overstates the cable's safety factor; judging only by appearance without testing can miss embrittlement or corrosion cracking of inner wires and delay dehumidification or strengthening decisions. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：與現代 1,770 至 1,960 MPa 級鋼絲相比強度較低，但延性與降伏比較寬裕；評估既有主纜時，要用當時規格的最低值與實際抽樣結果，而不是現代鋼絲的數字。","observationEn":"Link to the mechanism: The strength is lower than modern 1,770 to 1,960 MPa wire, but ductility and yield ratio are generous; evaluating an existing cable must use the period specification minimum and actual sample results, not modern wire figures.","failure":"誤判風險：若相信「老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Old bridge wire is always far below its specification, so testing is pointless.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-12-k1","title":"失效模式","titleEn":"Failure mode","text":"若評估直接套用現代鋼絲強度，主纜安全係數會被高估；反之若只依外觀判斷而不做試驗，可能忽略內部鋼絲的脆化或腐蝕裂縫，延誤除濕或補強決策。","textEn":"Applying modern wire strengths overstates the cable's safety factor; judging only by appearance without testing can miss embrittlement or corrosion cracking of inner wires and delay dehumidification or strengthening decisions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「1930 年代鋼絲的強度與延性」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Strength and ductility of the 1930s wire\" shows distress, which diagnosis is most reasonable?","options":["若評估直接套用現代鋼絲強度，主纜安全係數會被高估；反之若只依外觀判斷而不做試驗，可能忽略內部鋼絲的脆化或腐蝕裂縫，延誤除濕或補強決策。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。"],"optionsEn":["Applying modern wire strengths overstates the cable's safety factor.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Suspenders are just thin ropes hanging the deck; losing one or two does not matter."],"answer":0,"explanation":"若評估直接套用現代鋼絲強度，主纜安全係數會被高估；反之若只依外觀判斷而不做試驗，可能忽略內部鋼絲的脆化或腐蝕裂縫，延誤除濕或補強決策。 需以量測區分可能原因。","explanationEn":"Applying modern wire strengths overstates the cable's safety factor; judging only by appearance without testing can miss embrittlement or corrosion cracking of inner wires and delay dehumidification or strengthening decisions. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":36},{"id":"b015-v13-13","title":"吊索受力與 1970 年代全面更換：機制與傳力路徑","titleEn":"Suspender forces and the 1970s full replacement: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-12"],"objective":"說明「250 對吊索」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “250 pairs of suspenders” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"金門大橋有 250 對豎向吊索，間距 50 ft，每根直徑 2-11/16 in；原吊索於 1972 至 1976 年間全部更換，最後一根於 1976 年 5 月 4 日完成。吊索把橋面荷重傳到索夾與主纜，最脆弱的部位通常是下端錨頭附近：雨水沿吊索流下積聚、海鹽與鋼絲彎曲應力在此疊加。更換吊索時，必須在不中斷交通的情況下以臨時吊具分擔荷重，逐根卸載、拆除與張拉，並控制橋面高程與相鄰吊索的受力變化。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「250 對吊索」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Golden Gate has 250 pairs of vertical suspender ropes at 50 ft spacing, each 2-11/16 in in diameter; the originals were all replaced between 1972 and 1976, the last on 4 May 1976. Suspenders carry deck load to the cable bands and main cables, and the weakest zone is usually near the lower socket, where rainwater running down the rope collects and salt and wire bending stress combine. Replacing suspenders without stopping traffic means sharing load through temporary hangers, then unloading, removing and tensioning ropes one at a time while controlling deck level and force changes in neighbouring suspenders. Mentor task: draw a free-body or load-path diagram showing how loads pass through “250 pairs of suspenders” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：每對吊索承擔 50 ft（15.24 m）橋面。","observationEn":"Order-of-magnitude cue: Each pair carries 50 ft (15.24 m) of deck.","failure":"常見誤解：「吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Suspenders are just thin ropes hanging the deck; losing one or two does not matter.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「250 對吊索」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “250 pairs of suspenders”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-13-k1","title":"吊索受力與 1970 年代全面更換","titleEn":"Suspender forces and the 1970s full replacement","text":"金門大橋有 250 對豎向吊索，間距 50 ft，每根直徑 2-11/16 in；原吊索於 1972 至 1976 年間全部更換，最後一根於 1976 年 5 月 4 日完成。吊索把橋面荷重傳到索夾與主纜，最脆弱的部位通常是下端錨頭附近：雨水沿吊索流下積聚、海鹽與鋼絲彎曲應力在此疊加。","textEn":"Golden Gate has 250 pairs of vertical suspender ropes at 50 ft spacing, each 2-11/16 in in diameter; the originals were all replaced between 1972 and 1976, the last on 4 May 1976. Suspenders carry deck load to the cable bands and main cables, and the weakest zone is usually near the lower socket, where rainwater running down the rope collects and salt and wire bending stress combine.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Suspenders are just thin ropes hanging the deck; losing one or two does not matter. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「吊索受力與 1970 年代全面更換」，下列哪一項敘述正確？","questionEn":"Which statement about \"Suspender forces and the 1970s full replacement\" is correct?","options":["吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。","金門大橋有 250 對豎向吊索，間距 50 ft，每根直徑 2-11/16 in。","空中紡線的速度只取決於紡線輪跑多快。"],"optionsEn":["Suspenders are just thin ropes hanging the deck; losing one or two does not matter.","Golden Gate has 250 pairs of vertical suspender ropes at 50 ft spacing, each 2-11/16 in in diameter.","Aerial-spinning speed depends only on how fast the wheels run."],"answer":1,"explanation":"金門大橋有 250 對豎向吊索，間距 50 ft，每根直徑 2-11/16 in；原吊索於 1972 至 1976 年間全部更換，最後一根於 1976 年 5 月 4 日完成。 其餘選項是常見誤解。","explanationEn":"Golden Gate has 250 pairs of vertical suspender ropes at 50 ft spacing, each 2-11/16 in in diameter; the originals were all replaced between 1972 and 1976, the last on 4 May 1976. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b015-v13-14","title":"吊索受力與 1970 年代全面更換：定量估算","titleEn":"Suspender forces and the 1970s full replacement: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-13"],"objective":"以數值模型估算「250 對吊索」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “250 pairs of suspenders” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：每對吊索承擔 50 ft（15.24 m）橋面。若每側橋面恆載 100 kN/m，每對受力 100×15.24 ≈ 1,524 kN，每根 762 kN。直徑 68.3 mm 鋼索若金屬面積約為毛面積的 60%，A ≈ 0.6×π/4×68.3² ≈ 2,196 mm²，應力 ≈ 347 N/mm²。恆載與填充率為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Each pair carries 50 ft (15.24 m) of deck. With 100 kN/m of dead load per side, a pair carries 100×15.24 ≈ 1,524 kN, or 762 kN per rope. For a 68.3 mm rope with metallic area about 60% of gross, A ≈ 0.6×π/4×68.3² ≈ 2,196 mm², a stress of about 347 N/mm². Dead load and fill factor are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：更換時以千斤頂讀值與吊索應變計量測新舊吊索受力轉移，量測橋面高程變化與相鄰吊索力，確保偏差在容許範圍；完成後以振動法或荷重計抽測吊索力，並以磁通檢測建立新吊索的基準剖面。","observationEn":"How to cross-check: During replacement measure the force transfer between old and new ropes with jack readings and strain gauges, monitoring deck level and neighbouring forces within tolerance; afterwards spot-check forces by vibration method or load cell and record a magnetic-flux baseline for each new rope.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"每對吊索承擔 50 ft（15.24 m）橋面。若每側橋面恆載 100 kN/m，每對受力 100×15.24 ≈ 1,524 kN，每根 762 kN。直徑 68.3 mm 鋼索若金屬面積約為毛面積的 60%，A ≈ 0.6×π/4×68.3² ≈ 2,196 mm²，應力 ≈ 347 N/mm²。恆載與填充率為教學假設。","textEn":"Each pair carries 50 ft (15.24 m) of deck. With 100 kN/m of dead load per side, a pair carries 100×15.24 ≈ 1,524 kN, or 762 kN per rope. For a 68.3 mm rope with metallic area about 60% of gross, A ≈ 0.6×π/4×68.3² ≈ 2,196 mm², a stress of about 347 N/mm². Dead load and fill factor are teaching assumptions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「吊索受力與 1970 年代全面更換」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Suspender forces and the 1970s full replacement\", which statement holds?","options":["只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。","1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。","每對吊索承擔 50 ft（15.24 m）橋面。"],"optionsEn":["If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems.","Because the bridge was undamaged in 1989, it does not need seismic retrofit.","Each pair carries 50 ft (15.24 m) of deck."],"answer":2,"explanation":"每對吊索承擔 50 ft（15.24 m）橋面。 重算時請保留單位。","explanationEn":"Each pair carries 50 ft (15.24 m) of deck. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":38},{"id":"b015-v13-15","title":"吊索受力與 1970 年代全面更換：試驗與驗證","titleEn":"Suspender forces and the 1970s full replacement: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「250 對吊索」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “250 pairs of suspenders” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"更換時以千斤頂讀值與吊索應變計量測新舊吊索受力轉移，量測橋面高程變化與相鄰吊索力，確保偏差在容許範圍；完成後以振動法或荷重計抽測吊索力，並以磁通檢測建立新吊索的基準剖面。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"During replacement measure the force transfer between old and new ropes with jack readings and strain gauges, monitoring deck level and neighbouring forces within tolerance; afterwards spot-check forces by vibration method or load cell and record a magnetic-flux baseline for each new rope. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：吊索更換計畫應列出臨時吊具容量、逐根卸載與張拉的停留點、橋面高程允差與停止條件，並由結構工程師現場核可；新吊索要建立可追溯的出廠證明與安裝張力紀錄。","observationEn":"Site practice: A suspender replacement plan should list temporary hanger capacity, hold points for unloading and tensioning each rope, deck-level tolerance and stop conditions, approved on site by the structural engineer; new ropes need traceable mill certificates and installation tension records.","failure":"注意干擾：下端錨頭附近的腐蝕斷絲常被護套或塗裝遮蔽，若只做目視檢查可能延誤更換；更換時若荷重轉移順序錯誤，相鄰吊索過載或橋面局部下陷，可能造成桁架構件附加應力。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Broken wires near lower sockets are often hidden under sleeves or paint, so visual inspection alone can delay replacement; a wrong load-transfer order during replacement can overload neighbouring ropes or locally drop the deck, adding stress to truss members. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-15-k1","title":"驗證方法","titleEn":"Verification method","text":"更換時以千斤頂讀值與吊索應變計量測新舊吊索受力轉移，量測橋面高程變化與相鄰吊索力，確保偏差在容許範圍；完成後以振動法或荷重計抽測吊索力，並以磁通檢測建立新吊索的基準剖面。","textEn":"During replacement measure the force transfer between old and new ropes with jack readings and strain gauges, monitoring deck level and neighbouring forces within tolerance; afterwards spot-check forces by vibration method or load cell and record a magnetic-flux baseline for each new rope.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-15-k2","title":"現場實務","titleEn":"Site practice","text":"吊索更換計畫應列出臨時吊具容量、逐根卸載與張拉的停留點、橋面高程允差與停止條件，並由結構工程師現場核可；新吊索要建立可追溯的出廠證明與安裝張力紀錄。","textEn":"A suspender replacement plan should list temporary hanger capacity, hold points for unloading and tensioning each rope, deck-level tolerance and stop conditions, approved on site by the structural engineer; new ropes need traceable mill certificates and installation tension records.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「吊索受力與 1970 年代全面更換」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Suspender forces and the 1970s full replacement\"?","options":["更換時以千斤頂讀值與吊索應變計量測新舊吊索受力轉移，量測橋面高程變化與相鄰吊索力，確保偏差在容許範圍。","不確定度太難估計，報告中只寫最佳值即可。","塔頂荷重就等於主纜張力。"],"optionsEn":["During replacement measure the force transfer between old and new ropes with jack readings and strain gauges, monitoring deck level and neighbouring forces within tolerance.","Uncertainty is too hard to estimate, so the report may state only the best value.","The load on the tower equals the cable tension."],"answer":0,"explanation":"更換時以千斤頂讀值與吊索應變計量測新舊吊索受力轉移，量測橋面高程變化與相鄰吊索力，確保偏差在容許範圍；完成後以振動法或荷重計抽測吊索力，並以磁通檢測建立新吊索的基準剖面。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"During replacement measure the force transfer between old and new ropes with jack readings and strain gauges, monitoring deck level and neighbouring forces within tolerance; afterwards spot-check forces by vibration method or load cell and record a magnetic-flux baseline for each new rope. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":39},{"id":"b015-v13-16","title":"吊索受力與 1970 年代全面更換：失效診斷","titleEn":"Suspender forces and the 1970s full replacement: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-15"],"objective":"從症狀倒推「250 對吊索」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “250 pairs of suspenders” and propose discriminating checks, corrective actions and prevention.","instruction":"下端錨頭附近的腐蝕斷絲常被護套或塗裝遮蔽，若只做目視檢查可能延誤更換；更換時若荷重轉移順序錯誤，相鄰吊索過載或橋面局部下陷，可能造成桁架構件附加應力。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Broken wires near lower sockets are often hidden under sleeves or paint, so visual inspection alone can delay replacement; a wrong load-transfer order during replacement can overload neighbouring ropes or locally drop the deck, adding stress to truss members. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：更換吊索時，必須在不中斷交通的情況下以臨時吊具分擔荷重，逐根卸載、拆除與張拉，並控制橋面高程與相鄰吊索的受力變化。","observationEn":"Link to the mechanism: Replacing suspenders without stopping traffic means sharing load through temporary hangers, then unloading, removing and tensioning ropes one at a time while controlling deck level and force changes in neighbouring suspenders.","failure":"誤判風險：若相信「吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Suspenders are just thin ropes hanging the deck; losing one or two does not matter.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-16-k1","title":"失效模式","titleEn":"Failure mode","text":"下端錨頭附近的腐蝕斷絲常被護套或塗裝遮蔽，若只做目視檢查可能延誤更換；更換時若荷重轉移順序錯誤，相鄰吊索過載或橋面局部下陷，可能造成桁架構件附加應力。","textEn":"Broken wires near lower sockets are often hidden under sleeves or paint, so visual inspection alone can delay replacement; a wrong load-transfer order during replacement can overload neighbouring ropes or locally drop the deck, adding stress to truss members.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「吊索受力與 1970 年代全面更換」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Suspender forces and the 1970s full replacement\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","下端錨頭附近的腐蝕斷絲常被護套或塗裝遮蔽，若只做目視檢查可能延誤更換；更換時若荷重轉移順序錯誤，相鄰吊索過載或橋面局部下陷，可能造成桁架構件附加應力。","空中紡線的速度只取決於紡線輪跑多快。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Broken wires near lower sockets are often hidden under sleeves or paint, so visual inspection alone can delay replacement.","Aerial-spinning speed depends only on how fast the wheels run."],"answer":1,"explanation":"下端錨頭附近的腐蝕斷絲常被護套或塗裝遮蔽，若只做目視檢查可能延誤更換；更換時若荷重轉移順序錯誤，相鄰吊索過載或橋面局部下陷，可能造成桁架構件附加應力。 需以量測區分可能原因。","explanationEn":"Broken wires near lower sockets are often hidden under sleeves or paint, so visual inspection alone can delay replacement; a wrong load-transfer order during replacement can overload neighbouring ropes or locally drop the deck, adding stress to truss members. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":40}],"order":6},{"id":"b015-v13-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「1930 年代空中紡線的進度估算」與「橋面更換減重後的主纜抬升」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Estimating 1930s aerial-spinning progress\" and \"Cable rise after the lighter deck\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b015-v13-17","title":"1930 年代空中紡線的進度估算：機制與傳力路徑","titleEn":"Estimating 1930s aerial-spinning progress: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-16"],"objective":"說明「6 個月又 9 天的紡線」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Six months and nine days of spinning” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"業主資料記載金門大橋主纜鋼絲紡線在 6 個月又 9 天內完成，兩條主纜共用約 80,000 mi（約 129,000 km）的鍍鋅鋼絲。空中紡線讓紡線輪沿貓道上方來回運行，每趟把鋼絲環從一座錨碇帶到另一座，在兩端錨碇的索靴上繞回；工人在塔頂與跨中逐根調整鋼絲垂度，使每束鋼絲受力一致。速度受限於紡線輪數量、運行速度、調整垂度所需的時間與風。這個進度數字可以用來回推每天必須鋪設的鋼絲長度與每束完成所需時間。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「6 個月又 9 天的紡線」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Owner data record that wire spinning for the Golden Gate cables was completed in six months and nine days, using about 80,000 mi (about 129,000 km) of galvanised wire for both cables. Aerial spinning runs spinning wheels back and forth above the catwalk, each trip carrying a loop of wire from one anchorage to the other, where it turns around strand shoes; crews at the towers and mid-span adjust wire sag one by one so every wire in a strand carries the same force. Speed is limited by the number of wheels, their travel speed, the time to adjust sag, and wind. The progress figure lets us back-calculate the wire length that had to be laid each day and the time per strand. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Six months and nine days of spinning” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：總長 129,000 km ÷ 190 天 ≈ 679 km/天。","observationEn":"Order-of-magnitude cue: Total 129,000 km ÷ 190 days ≈ 679 km a day.","failure":"常見誤解：「空中紡線的速度只取決於紡線輪跑多快。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Aerial-spinning speed depends only on how fast the wheels run.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「6 個月又 9 天的紡線」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Six months and nine days of spinning”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-17-k1","title":"1930 年代空中紡線的進度估算","titleEn":"Estimating 1930s aerial-spinning progress","text":"業主資料記載金門大橋主纜鋼絲紡線在 6 個月又 9 天內完成，兩條主纜共用約 80,000 mi（約 129,000 km）的鍍鋅鋼絲。空中紡線讓紡線輪沿貓道上方來回運行，每趟把鋼絲環從一座錨碇帶到另一座，在兩端錨碇的索靴上繞回；工人在塔頂與跨中逐根調整鋼絲垂度，使每束鋼絲受力一致。","textEn":"Owner data record that wire spinning for the Golden Gate cables was completed in six months and nine days, using about 80,000 mi (about 129,000 km) of galvanised wire for both cables. Aerial spinning runs spinning wheels back and forth above the catwalk, each trip carrying a loop of wire from one anchorage to the other, where it turns around strand shoes; crews at the towers and mid-span adjust wire sag one by one so every wire in a strand carries the same force.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：空中紡線的速度只取決於紡線輪跑多快。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Aerial-spinning speed depends only on how fast the wheels run. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「1930 年代空中紡線的進度估算」，下列哪一項敘述正確？","questionEn":"Which statement about \"Estimating 1930s aerial-spinning progress\" is correct?","options":["空中紡線的速度只取決於紡線輪跑多快。","把橋面換輕只會讓橋更安全，不會改變幾何。","業主資料記載金門大橋主纜鋼絲紡線在 6 個月又 9 天內完成，兩條主纜共用約 80,000 mi（約 129,000 km）的鍍鋅鋼絲。"],"optionsEn":["Aerial-spinning speed depends only on how fast the wheels run.","A lighter deck only makes the bridge safer; it does not change the geometry.","Owner data record that wire spinning for the Golden Gate cables was completed in six months and nine days, using about 80,000 mi (about 129,000 km) of galvanised wire for both cables."],"answer":2,"explanation":"業主資料記載金門大橋主纜鋼絲紡線在 6 個月又 9 天內完成，兩條主纜共用約 80,000 mi（約 129,000 km）的鍍鋅鋼絲。 其餘選項是常見誤解。","explanationEn":"Owner data record that wire spinning for the Golden Gate cables was completed in six months and nine days, using about 80,000 mi (about 129,000 km) of galvanised wire for both cables. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":41},{"id":"b015-v13-18","title":"1930 年代空中紡線的進度估算：定量估算","titleEn":"Estimating 1930s aerial-spinning progress: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-17"],"objective":"以數值模型估算「6 個月又 9 天的紡線」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Six months and nine days of spinning” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：總長 129,000 km ÷ 190 天 ≈ 679 km/天。單根主纜鋼絲長約 2,332 m，相當於每天約 679,000/2,332 ≈ 291 根全長鋼絲；兩纜共 122 束，平均每束約 190/122 ≈ 1.6 天完成（忽略並行作業）。若因強風停工 20 天，日進度需提高到約 129,000/170 ≈ 759 km/天。工作日假設為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Total 129,000 km ÷ 190 days ≈ 679 km a day. With each cable wire about 2,332 m long, that is about 679,000/2,332 ≈ 291 full-length wires a day; across 122 strands in both cables, about 190/122 ≈ 1.6 days per strand on average (ignoring parallel work). Losing 20 days to wind would require about 129,000/170 ≈ 759 km a day. Working-day assumptions are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：紡線期間每日記錄各紡線輪趟數、完成鋼絲數、停工時間與天氣，並以每束完成後的垂度量測確認品質；進度曲線與計畫比較，落後時優先檢討停工原因而不是縮短垂度調整時間。","observationEn":"How to cross-check: During spinning log trips per wheel, wires completed, downtime and weather daily, confirming quality by sag survey after each strand; compare the progress curve with the plan and, when behind, examine causes of downtime first rather than shortening sag adjustment.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"總長 129,000 km ÷ 190 天 ≈ 679 km/天。單根主纜鋼絲長約 2,332 m，相當於每天約 679,000/2,332 ≈ 291 根全長鋼絲；兩纜共 122 束，平均每束約 190/122 ≈ 1.6 天完成（忽略並行作業）。若因強風停工 20 天，日進度需提高到約 129,000/170 ≈ 759 km/天。工作日假設為教學假設。","textEn":"Total 129,000 km ÷ 190 days ≈ 679 km a day. With each cable wire about 2,332 m long, that is about 679,000/2,332 ≈ 291 full-length wires a day; across 122 strands in both cables, about 190/122 ≈ 1.6 days per strand on average (ignoring parallel work). Losing 20 days to wind would require about 129,000/170 ≈ 759 km a day. Working-day assumptions are teaching assumptions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「1930 年代空中紡線的進度估算」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Estimating 1930s aerial-spinning progress\", which statement holds?","options":["總長 129,000 km ÷ 190 天 ≈ 679 km/天。","螺栓一旦鎖到規定張力，就能永久保持。","防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。"],"optionsEn":["Total 129,000 km ÷ 190 days ≈ 679 km a day.","Once bolts are tightened to the specified tension, they keep it forever.","The deterrent net is a light accessory with no effect on structure or wind stability."],"answer":0,"explanation":"總長 129,000 km ÷ 190 天 ≈ 679 km/天。 重算時請保留單位。","explanationEn":"Total 129,000 km ÷ 190 days ≈ 679 km a day. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":42},{"id":"b015-v13-19","title":"1930 年代空中紡線的進度估算：試驗與驗證","titleEn":"Estimating 1930s aerial-spinning progress: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「6 個月又 9 天的紡線」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Six months and nine days of spinning” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"紡線期間每日記錄各紡線輪趟數、完成鋼絲數、停工時間與天氣，並以每束完成後的垂度量測確認品質；進度曲線與計畫比較，落後時優先檢討停工原因而不是縮短垂度調整時間。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"During spinning log trips per wheel, wires completed, downtime and weather daily, confirming quality by sag survey after each strand; compare the progress curve with the plan and, when behind, examine causes of downtime first rather than shortening sag adjustment. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：紡線施工規範要寫明每束垂度允差、量測時段與溫度修正，以及停工風速；進度壓力下任何放寬品質門檻的提議都必須經設計者書面核可。","observationEn":"Site practice: The spinning specification should state sag tolerance per strand, survey windows and temperature correction, and the stop-work wind speed; any proposal to relax quality thresholds under schedule pressure needs the designer's written approval.","failure":"注意干擾：為追趕進度而縮短垂度調整，會讓同一束鋼絲受力不均，壓擠後產生鬆弛絲，長期影響主纜耐久與索夾夾緊；強風中強行紡線則可能使鋼絲纏繞或斷裂。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Cutting sag adjustment to catch up leaves uneven forces in a strand and slack wires after compaction, harming long-term durability and cable-band grip; spinning in strong wind can tangle or break wires. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-19-k1","title":"驗證方法","titleEn":"Verification method","text":"紡線期間每日記錄各紡線輪趟數、完成鋼絲數、停工時間與天氣，並以每束完成後的垂度量測確認品質；進度曲線與計畫比較，落後時優先檢討停工原因而不是縮短垂度調整時間。","textEn":"During spinning log trips per wheel, wires completed, downtime and weather daily, confirming quality by sag survey after each strand; compare the progress curve with the plan and, when behind, examine causes of downtime first rather than shortening sag adjustment.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-19-k2","title":"現場實務","titleEn":"Site practice","text":"紡線施工規範要寫明每束垂度允差、量測時段與溫度修正，以及停工風速；進度壓力下任何放寬品質門檻的提議都必須經設計者書面核可。","textEn":"The spinning specification should state sag tolerance per strand, survey windows and temperature correction, and the stop-work wind speed; any proposal to relax quality thresholds under schedule pressure needs the designer's written approval.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「1930 年代空中紡線的進度估算」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Estimating 1930s aerial-spinning progress\"?","options":["允收準則可以等看到量測數據後再決定。","紡線期間每日記錄各紡線輪趟數、完成鋼絲數、停工時間與天氣，並以每束完成後的垂度量測確認品質；進度曲線與計畫比較，落後時優先檢討停工原因而不是縮短垂度調整時間。","懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","During spinning log trips per wheel, wires completed, downtime and weather daily, confirming quality by sag survey after each strand.","A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load."],"answer":1,"explanation":"紡線期間每日記錄各紡線輪趟數、完成鋼絲數、停工時間與天氣，並以每束完成後的垂度量測確認品質；進度曲線與計畫比較，落後時優先檢討停工原因而不是縮短垂度調整時間。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"During spinning log trips per wheel, wires completed, downtime and weather daily, confirming quality by sag survey after each strand; compare the progress curve with the plan and, when behind, examine causes of downtime first rather than shortening sag adjustment. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":43},{"id":"b015-v13-20","title":"1930 年代空中紡線的進度估算：失效診斷","titleEn":"Estimating 1930s aerial-spinning progress: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-19"],"objective":"從症狀倒推「6 個月又 9 天的紡線」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Six months and nine days of spinning” and propose discriminating checks, corrective actions and prevention.","instruction":"為追趕進度而縮短垂度調整，會讓同一束鋼絲受力不均，壓擠後產生鬆弛絲，長期影響主纜耐久與索夾夾緊；強風中強行紡線則可能使鋼絲纏繞或斷裂。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Cutting sag adjustment to catch up leaves uneven forces in a strand and slack wires after compaction, harming long-term durability and cable-band grip; spinning in strong wind can tangle or break wires. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：這個進度數字可以用來回推每天必須鋪設的鋼絲長度與每束完成所需時間。","observationEn":"Link to the mechanism: The progress figure lets us back-calculate the wire length that had to be laid each day and the time per strand.","failure":"誤判風險：若相信「空中紡線的速度只取決於紡線輪跑多快。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Aerial-spinning speed depends only on how fast the wheels run.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-20-k1","title":"失效模式","titleEn":"Failure mode","text":"為追趕進度而縮短垂度調整，會讓同一束鋼絲受力不均，壓擠後產生鬆弛絲，長期影響主纜耐久與索夾夾緊；強風中強行紡線則可能使鋼絲纏繞或斷裂。","textEn":"Cutting sag adjustment to catch up leaves uneven forces in a strand and slack wires after compaction, harming long-term durability and cable-band grip; spinning in strong wind can tangle or break wires.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「1930 年代空中紡線的進度估算」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Estimating 1930s aerial-spinning progress\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","把橋面換輕只會讓橋更安全，不會改變幾何。","為追趕進度而縮短垂度調整，會讓同一束鋼絲受力不均，壓擠後產生鬆弛絲，長期影響主纜耐久與索夾夾緊；強風中強行紡線則可能使鋼絲纏繞或斷裂。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","A lighter deck only makes the bridge safer; it does not change the geometry.","Cutting sag adjustment to catch up leaves uneven forces in a strand and slack wires after compaction, harming long-term durability and cable-band grip."],"answer":2,"explanation":"為追趕進度而縮短垂度調整，會讓同一束鋼絲受力不均，壓擠後產生鬆弛絲，長期影響主纜耐久與索夾夾緊；強風中強行紡線則可能使鋼絲纏繞或斷裂。 需以量測區分可能原因。","explanationEn":"Cutting sag adjustment to catch up leaves uneven forces in a strand and slack wires after compaction, harming long-term durability and cable-band grip; spinning in strong wind can tangle or break wires. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":44},{"id":"b015-v13-21","title":"橋面更換減重後的主纜抬升：機制與傳力路徑","titleEn":"Cable rise after the lighter deck: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-20"],"objective":"說明「1986 年橋面減重 12,300 噸」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “1986 deck lightening of 12,300 tons” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"1980 年代金門大橋把原有鋼筋混凝土橋面與縱梁更換為正交異性鋼橋面，業主資料記載重量減少約 12,300 噸，相當於每延英尺約 1.37 噸。施工多在夜間分段進行，每天早上恢復通車。橋面變輕後主纜張力下降、彈性伸長減少，主跨垂度隨之變小，橋面整體抬升；同時塔頂索鞍兩側的平衡改變，塔頂可能朝邊跨方向移動。因此更換順序必須控制左右對稱與跨間平衡，並預先計算完工後的路面縱斷面與伸縮縫位置。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「1986 年橋面減重 12,300 噸」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"In the 1980s the original reinforced-concrete deck and stringers were replaced with an orthotropic steel deck; owner data record a weight reduction of about 12,300 tons, about 1.37 tons per lineal foot. Work was done mostly at night in sections, reopening to traffic each morning. A lighter deck lowers cable tension and elastic stretch, so main-span sag decreases and the deck rises; the balance on either side of the tower saddles also changes and tower tops may move toward the side spans. The replacement sequence therefore had to control symmetry and balance between spans, and the final road profile and joint positions had to be predicted in advance. Mentor task: draw a free-body or load-path diagram showing how loads pass through “1986 deck lightening of 12,300 tons” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：Δw = 1.37 short ton/ft ≈ 40 kN/m（兩纜合計）。","observationEn":"Order-of-magnitude cue: Δw = 1.37 short tons/ft ≈ 40 kN/m for both cables.","failure":"常見誤解：「把橋面換輕只會讓橋更安全，不會改變幾何。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A lighter deck only makes the bridge safer; it does not change the geometry.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「1986 年橋面減重 12,300 噸」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “1986 deck lightening of 12,300 tons”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-21-k1","title":"橋面更換減重後的主纜抬升","titleEn":"Cable rise after the lighter deck","text":"1980 年代金門大橋把原有鋼筋混凝土橋面與縱梁更換為正交異性鋼橋面，業主資料記載重量減少約 12,300 噸，相當於每延英尺約 1.37 噸。施工多在夜間分段進行，每天早上恢復通車。","textEn":"In the 1980s the original reinforced-concrete deck and stringers were replaced with an orthotropic steel deck; owner data record a weight reduction of about 12,300 tons, about 1.37 tons per lineal foot. Work was done mostly at night in sections, reopening to traffic each morning.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：把橋面換輕只會讓橋更安全，不會改變幾何。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A lighter deck only makes the bridge safer; it does not change the geometry. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「橋面更換減重後的主纜抬升」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cable rise after the lighter deck\" is correct?","options":["1980 年代金門大橋把原有鋼筋混凝土橋面與縱梁更換為正交異性鋼橋面，業主資料記載重量減少約 12,300 噸，相當於每延英尺約 1.37 噸。","把橋面換輕只會讓橋更安全，不會改變幾何。","只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。"],"optionsEn":["In the 1980s the original reinforced-concrete deck and stringers were replaced with an orthotropic steel deck.","A lighter deck only makes the bridge safer; it does not change the geometry.","If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems."],"answer":0,"explanation":"1980 年代金門大橋把原有鋼筋混凝土橋面與縱梁更換為正交異性鋼橋面，業主資料記載重量減少約 12,300 噸，相當於每延英尺約 1.37 噸。 其餘選項是常見誤解。","explanationEn":"In the 1980s the original reinforced-concrete deck and stringers were replaced with an orthotropic steel deck; owner data record a weight reduction of about 12,300 tons, about 1.37 tons per lineal foot. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":45},{"id":"b015-v13-22","title":"橋面更換減重後的主纜抬升：定量估算","titleEn":"Cable rise after the lighter deck: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-21"],"objective":"以數值模型估算「1986 年橋面減重 12,300 噸」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “1986 deck lightening of 12,300 tons” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：Δw = 1.37 short ton/ft ≈ 40 kN/m（兩纜合計）。取 f = 142 m：ΔH = Δw·l²/(8f) = 40×1,280²/(8×142) ≈ 57,700 kN，每纜 28.8 MN；主跨主纜縮短 ΔS ≈ 28.8×10⁶×1,320/(2×10¹¹×0.515) ≈ 0.37 m；Δf = (3l/(16f))·ΔS ≈ 1.69×0.37 ≈ 0.62 m 抬升。垂度、E 與纜長為教學假設，忽略塔頂位移。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Δw = 1.37 short tons/ft ≈ 40 kN/m for both cables. With f = 142 m: ΔH = Δw·l²/(8f) = 40×1,280²/(8×142) ≈ 57,700 kN, or 28.8 MN per cable; the main-span cable shortens by ΔS ≈ 28.8×10⁶×1,320/(2×10¹¹×0.515) ≈ 0.37 m, and Δf = (3l/(16f))·ΔS ≈ 1.69×0.37 ≈ 0.62 m of rise. Sag, E and cable length are teaching assumptions; tower-top movement is ignored. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：每一施工段完成後量測橋面高程、塔頂位移與主纜垂度，並與分段更換分析比較；全部完成後重新測量路面縱斷面、伸縮縫開口與吊索力，更新恆載履歷與結構模型。","observationEn":"How to cross-check: After each section measure deck levels, tower-top movement and cable sag against the staged-replacement analysis; at completion re-survey the road profile, joint openings and suspender forces, updating the dead-load history and structural model.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"Δw = 1.37 short ton/ft ≈ 40 kN/m（兩纜合計）。取 f = 142 m：ΔH = Δw·l²/(8f) = 40×1,280²/(8×142) ≈ 57,700 kN，每纜 28.8 MN；主跨主纜縮短 ΔS ≈ 28.8×10⁶×1,320/(2×10¹¹×0.515) ≈ 0.37 m；Δf = (3l/(16f))·ΔS ≈ 1.69×0.37 ≈ 0.62 m 抬升。垂度、E 與纜長為教學假設，忽略塔頂位移。","textEn":"Δw = 1.37 short tons/ft ≈ 40 kN/m for both cables. With f = 142 m: ΔH = Δw·l²/(8f) = 40×1,280²/(8×142) ≈ 57,700 kN, or 28.8 MN per cable; the main-span cable shortens by ΔS ≈ 28.8×10⁶×1,320/(2×10¹¹×0.515) ≈ 0.37 m, and Δf = (3l/(16f))·ΔS ≈ 1.69×0.37 ≈ 0.62 m of rise. Sag, E and cable length are teaching assumptions; tower-top movement is ignored.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「橋面更換減重後的主纜抬升」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cable rise after the lighter deck\", which statement holds?","options":["1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。","Δw = 1.37 short ton/ft ≈ 40 kN/m（兩纜合計）。","塔頂荷重就等於主纜張力。"],"optionsEn":["Because the bridge was undamaged in 1989, it does not need seismic retrofit.","Δw = 1.37 short tons/ft ≈ 40 kN/m for both cables.","The load on the tower equals the cable tension."],"answer":1,"explanation":"Δw = 1.37 short ton/ft ≈ 40 kN/m（兩纜合計）。 重算時請保留單位。","explanationEn":"Δw = 1.37 short tons/ft ≈ 40 kN/m for both cables. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":46},{"id":"b015-v13-23","title":"橋面更換減重後的主纜抬升：試驗與驗證","titleEn":"Cable rise after the lighter deck: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「1986 年橋面減重 12,300 噸」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “1986 deck lightening of 12,300 tons” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"每一施工段完成後量測橋面高程、塔頂位移與主纜垂度，並與分段更換分析比較；全部完成後重新測量路面縱斷面、伸縮縫開口與吊索力，更新恆載履歷與結構模型。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"After each section measure deck levels, tower-top movement and cable sag against the staged-replacement analysis; at completion re-survey the road profile, joint openings and suspender forces, updating the dead-load history and structural model. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：大規模恆載改變的工程，應事先完成分段施工分析、列出每階段允許的不平衡重量與幾何監測點，並在每夜施工結束時核對量測值；超出觸發值即停止下一段，由設計者評估後才繼續。","observationEn":"Site practice: Major dead-load changes require a staged analysis listing the allowable unbalanced weight and geometric checkpoints for each stage, with readings checked at the end of every night shift; exceeding a trigger stops the next section until the designer has assessed it.","failure":"注意干擾：若更換不對稱推進，單側或單跨減重過多，塔頂索鞍兩側張力差增大，塔身彎矩與伸縮縫偏位可能超限；未預先調整路面高程則完工後出現縱斷面不平順與排水問題。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Asymmetric progress that lightens one side or span too much increases the tension difference across the saddles, possibly overstressing tower bending and shifting joints beyond limits; failing to plan road levels leaves an uneven profile and drainage problems after completion. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-23-k1","title":"驗證方法","titleEn":"Verification method","text":"每一施工段完成後量測橋面高程、塔頂位移與主纜垂度，並與分段更換分析比較；全部完成後重新測量路面縱斷面、伸縮縫開口與吊索力，更新恆載履歷與結構模型。","textEn":"After each section measure deck levels, tower-top movement and cable sag against the staged-replacement analysis; at completion re-survey the road profile, joint openings and suspender forces, updating the dead-load history and structural model.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-23-k2","title":"現場實務","titleEn":"Site practice","text":"大規模恆載改變的工程，應事先完成分段施工分析、列出每階段允許的不平衡重量與幾何監測點，並在每夜施工結束時核對量測值；超出觸發值即停止下一段，由設計者評估後才繼續。","textEn":"Major dead-load changes require a staged analysis listing the allowable unbalanced weight and geometric checkpoints for each stage, with readings checked at the end of every night shift; exceeding a trigger stops the next section until the designer has assessed it.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「橋面更換減重後的主纜抬升」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cable rise after the lighter deck\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。","每一施工段完成後量測橋面高程、塔頂位移與主纜垂度，並與分段更換分析比較；全部完成後重新測量路面縱斷面、伸縮縫開口與吊索力，更新恆載履歷與結構模型。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Old bridge wire is always far below its specification, so testing is pointless.","After each section measure deck levels, tower-top movement and cable sag against the staged-replacement analysis."],"answer":2,"explanation":"每一施工段完成後量測橋面高程、塔頂位移與主纜垂度，並與分段更換分析比較；全部完成後重新測量路面縱斷面、伸縮縫開口與吊索力，更新恆載履歷與結構模型。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"After each section measure deck levels, tower-top movement and cable sag against the staged-replacement analysis; at completion re-survey the road profile, joint openings and suspender forces, updating the dead-load history and structural model. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":47},{"id":"b015-v13-24","title":"橋面更換減重後的主纜抬升：失效診斷","titleEn":"Cable rise after the lighter deck: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-23"],"objective":"從症狀倒推「1986 年橋面減重 12,300 噸」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “1986 deck lightening of 12,300 tons” and propose discriminating checks, corrective actions and prevention.","instruction":"若更換不對稱推進，單側或單跨減重過多，塔頂索鞍兩側張力差增大，塔身彎矩與伸縮縫偏位可能超限；未預先調整路面高程則完工後出現縱斷面不平順與排水問題。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Asymmetric progress that lightens one side or span too much increases the tension difference across the saddles, possibly overstressing tower bending and shifting joints beyond limits; failing to plan road levels leaves an uneven profile and drainage problems after completion. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：因此更換順序必須控制左右對稱與跨間平衡，並預先計算完工後的路面縱斷面與伸縮縫位置。","observationEn":"Link to the mechanism: The replacement sequence therefore had to control symmetry and balance between spans, and the final road profile and joint positions had to be predicted in advance.","failure":"誤判風險：若相信「把橋面換輕只會讓橋更安全，不會改變幾何。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A lighter deck only makes the bridge safer; it does not change the geometry.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-24-k1","title":"失效模式","titleEn":"Failure mode","text":"若更換不對稱推進，單側或單跨減重過多，塔頂索鞍兩側張力差增大，塔身彎矩與伸縮縫偏位可能超限；未預先調整路面高程則完工後出現縱斷面不平順與排水問題。","textEn":"Asymmetric progress that lightens one side or span too much increases the tension difference across the saddles, possibly overstressing tower bending and shifting joints beyond limits; failing to plan road levels leaves an uneven profile and drainage problems after completion.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「橋面更換減重後的主纜抬升」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cable rise after the lighter deck\" shows distress, which diagnosis is most reasonable?","options":["若更換不對稱推進，單側或單跨減重過多，塔頂索鞍兩側張力差增大，塔身彎矩與伸縮縫偏位可能超限；未預先調整路面高程則完工後出現縱斷面不平順與排水問題。","只要結構還沒倒，就代表安全餘裕仍然足夠。","只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。"],"optionsEn":["Asymmetric progress that lightens one side or span too much increases the tension difference across the saddles, possibly overstressing tower bending and shifting joints beyond limits.","As long as the structure is still standing, its safety margin must still be adequate.","If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems."],"answer":0,"explanation":"若更換不對稱推進，單側或單跨減重過多，塔頂索鞍兩側張力差增大，塔身彎矩與伸縮縫偏位可能超限；未預先調整路面高程則完工後出現縱斷面不平順與排水問題。 需以量測區分可能原因。","explanationEn":"Asymmetric progress that lightens one side or span too much increases the tension difference across the saddles, possibly overstressing tower bending and shifting joints beyond limits; failing to plan road levels leaves an uneven profile and drainage problems after completion. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":48}],"order":7},{"id":"b015-v13-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「抗風改造欄杆的風鳴試驗」與「索夾螺栓預力損失與再張拉」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Wind-tunnel tests of the singing retrofit railing\" and \"Cable-band bolt preload loss and re-tensioning\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b015-v13-25","title":"抗風改造欄杆的風鳴試驗：機制與傳力路徑","titleEn":"Wind-tunnel tests of the singing retrofit railing: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-24"],"objective":"說明「西側欄杆鋼條風鳴」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “West railing slat tones” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"為了讓金門大橋在持續 100 mph 的風中保持結構完整，並承擔新增防墜網帶來的風阻，抗風改造把兩塔之間的西側人行道欄杆換成較透風的細長直立鋼條，並在人行道下方的桁架加裝整流板。2020 年春天起，強風中出現明顯的鳴聲：風以某些角度穿過鋼條時，渦流脫落頻率與鋼條或條間空氣的自然振動吻合。業主公布兩種音調：西風垂直吹向欄杆且達 22 mph 以上時約 280 至 700 Hz，風以小角度吹來且達 27 mph 以上時約 1.1 kHz。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「西側欄杆鋼條風鳴」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"To keep the Golden Gate structurally sound in sustained winds up to 100 mph and to carry the extra wind resistance of the new deterrent net, the wind retrofit replaced the west sidewalk railing between the towers with thin vertical slats that let more air through, and added a wind fairing on the truss below the sidewalk. From spring 2020 a distinct tone was heard in strong wind: as wind passed through the slats at certain angles, the vortex-shedding frequency matched the natural vibration of the slats or of the air between them. The owner reports two tones: about 280 to 700 Hz with west wind perpendicular to the railing at 22 mph or more, and about 1.1 kHz with wind at a slight angle at 27 mph or more. Mentor task: draw a free-body or load-path diagram showing how loads pass through “West railing slat tones” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：渦流脫落 f = St·U/d。","observationEn":"Order-of-magnitude cue: Vortex shedding f = St·U/d.","failure":"常見誤解：「只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「西側欄杆鋼條風鳴」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “West railing slat tones”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-25-k1","title":"抗風改造欄杆的風鳴試驗","titleEn":"Wind-tunnel tests of the singing retrofit railing","text":"為了讓金門大橋在持續 100 mph 的風中保持結構完整，並承擔新增防墜網帶來的風阻，抗風改造把兩塔之間的西側人行道欄杆換成較透風的細長直立鋼條，並在人行道下方的桁架加裝整流板。2020 年春天起，強風中出現明顯的鳴聲：風以某些角度穿過鋼條時，渦流脫落頻率與鋼條或條間空氣的自然振動吻合。","textEn":"To keep the Golden Gate structurally sound in sustained winds up to 100 mph and to carry the extra wind resistance of the new deterrent net, the wind retrofit replaced the west sidewalk railing between the towers with thin vertical slats that let more air through, and added a wind fairing on the truss below the sidewalk. From spring 2020 a distinct tone was heard in strong wind: as wind passed through the slats at certain angles, the vortex-shedding frequency matched the natural vibration of the slats or of the air between them.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「抗風改造欄杆的風鳴試驗」，下列哪一項敘述正確？","questionEn":"Which statement about \"Wind-tunnel tests of the singing retrofit railing\" is correct?","options":["只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。","為了讓金門大橋在持續 100 mph 的風中保持結構完整，並承擔新增防墜網帶來的風阻，抗風改造把兩塔之間的西側人行道欄杆換成較透風的細長直立鋼條，並在人行道下方的桁架加裝整流板。","螺栓一旦鎖到規定張力，就能永久保持。"],"optionsEn":["If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems.","To keep the Golden Gate structurally sound in sustained winds up to 100 mph and to carry the extra wind resistance of the new deterrent net, the wind retrofit replaced the west sidewalk railing between the towers with thin vertical slats that let more air through, and added a wind fairing on the truss below the sidewalk.","Once bolts are tightened to the specified tension, they keep it forever."],"answer":1,"explanation":"為了讓金門大橋在持續 100 mph 的風中保持結構完整，並承擔新增防墜網帶來的風阻，抗風改造把兩塔之間的西側人行道欄杆換成較透風的細長直立鋼條，並在人行道下方的桁架加裝整流板。 其餘選項是常見誤解。","explanationEn":"To keep the Golden Gate structurally sound in sustained winds up to 100 mph and to carry the extra wind resistance of the new deterrent net, the wind retrofit replaced the west sidewalk railing between the towers with thin vertical slats that let more air through, and added a wind fairing on the truss below the sidewalk. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":49},{"id":"b015-v13-26","title":"抗風改造欄杆的風鳴試驗：定量估算","titleEn":"Wind-tunnel tests of the singing retrofit railing: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-25"],"objective":"以數值模型估算「西側欄杆鋼條風鳴」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “West railing slat tones” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：渦流脫落 f = St·U/d。U = 22 mph ≈ 9.8 m/s、f = 280 Hz、St = 0.2 時，對應特徵尺寸 d = St·U/f ≈ 0.2×9.8/280 ≈ 7.0 mm；27 mph（12.1 m/s）、1.1 kHz 則 d ≈ 2.2 mm，暗示高音調來自不同的流動特徵（例如邊緣或條間間隙）。St 為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Vortex shedding f = St·U/d. With U = 22 mph ≈ 9.8 m/s, f = 280 Hz and St = 0.2, the implied characteristic size is d = St·U/f ≈ 0.2×9.8/280 ≈ 7.0 mm; 27 mph (12.1 m/s) at 1.1 kHz gives d ≈ 2.2 mm, suggesting the higher tone comes from a different flow feature such as an edge or the gap between slats. St is a teaching assumption. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：業主自 2020 年秋以足尺欄杆模型做風洞試驗，比較橫桿、粗糙膠帶、U 形夾、紋理塗料與填頂等方案，最後以附薄橡膠墊的 U 形夾在 110 種風速與風向組合中消除或大幅降低聲音；剩餘情境預估每年平均約 70 小時與 18 小時。","observationEn":"How to cross-check: From autumn 2020 the owner tested a full-scale railing model in a wind tunnel, comparing horizontal bars, coarse tape, U-shaped clips, textured paint and top fillers; U-shaped clips with a thin rubber insert eliminated or greatly reduced sound across 110 wind speed and direction combinations, with the remaining cases expected for about 70 and 18 hours a year on average.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"渦流脫落 f = St·U/d。U = 22 mph ≈ 9.8 m/s、f = 280 Hz、St = 0.2 時，對應特徵尺寸 d = St·U/f ≈ 0.2×9.8/280 ≈ 7.0 mm；27 mph（12.1 m/s）、1.1 kHz 則 d ≈ 2.2 mm，暗示高音調來自不同的流動特徵（例如邊緣或條間間隙）。St 為教學假設。","textEn":"Vortex shedding f = St·U/d. With U = 22 mph ≈ 9.8 m/s, f = 280 Hz and St = 0.2, the implied characteristic size is d = St·U/f ≈ 0.2×9.8/280 ≈ 7.0 mm; 27 mph (12.1 m/s) at 1.1 kHz gives d ≈ 2.2 mm, suggesting the higher tone comes from a different flow feature such as an edge or the gap between slats. St is a teaching assumption.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「抗風改造欄杆的風鳴試驗」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Wind-tunnel tests of the singing retrofit railing\", which statement holds?","options":["防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。","懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。","渦流脫落 f = St·U/d。"],"optionsEn":["The deterrent net is a light accessory with no effect on structure or wind stability.","A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load.","Vortex shedding f = St·U/d."],"answer":2,"explanation":"渦流脫落 f = St·U/d。 重算時請保留單位。","explanationEn":"Vortex shedding f = St·U/d. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":50},{"id":"b015-v13-27","title":"抗風改造欄杆的風鳴試驗：試驗與驗證","titleEn":"Wind-tunnel tests of the singing retrofit railing: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「西側欄杆鋼條風鳴」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “West railing slat tones” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"業主自 2020 年秋以足尺欄杆模型做風洞試驗，比較橫桿、粗糙膠帶、U 形夾、紋理塗料與填頂等方案，最後以附薄橡膠墊的 U 形夾在 110 種風速與風向組合中消除或大幅降低聲音；剩餘情境預估每年平均約 70 小時與 18 小時。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"From autumn 2020 the owner tested a full-scale railing model in a wind tunnel, comparing horizontal bars, coarse tape, U-shaped clips, textured paint and top fillers; U-shaped clips with a thin rubber insert eliminated or greatly reduced sound across 110 wind speed and direction combinations, with the remaining cases expected for about 70 and 18 hours a year on average. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：改變橋面細部的工程，風洞試驗範圍應包含局部構件的渦振與聲學，並在合約中訂出可接受的聲音與振動準則；改善措施（例如 12,000 根鋼條的夾具）須有安裝品質抽查與維修計畫。","observationEn":"Site practice: For work that changes deck details, wind-tunnel scope should include local vortex shedding and acoustics, with acceptable sound and vibration criteria in the contract; remedies such as clips on 12,000 slats need installation sampling and a maintenance plan.","failure":"注意干擾：若改造只檢核結構氣動穩定而未評估聲學與局部渦振，細長構件可能在常見風速下鳴響並承受高頻應力循環；高頻振動長期也可能使鋼條銲道或螺栓疲勞。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Checking only global aerodynamic stability without assessing acoustics and local vortex shedding can leave slender parts singing at common wind speeds and seeing high-frequency stress cycles, which over time can fatigue slat welds or bolts. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-27-k1","title":"驗證方法","titleEn":"Verification method","text":"業主自 2020 年秋以足尺欄杆模型做風洞試驗，比較橫桿、粗糙膠帶、U 形夾、紋理塗料與填頂等方案，最後以附薄橡膠墊的 U 形夾在 110 種風速與風向組合中消除或大幅降低聲音；剩餘情境預估每年平均約 70 小時與 18 小時。","textEn":"From autumn 2020 the owner tested a full-scale railing model in a wind tunnel, comparing horizontal bars, coarse tape, U-shaped clips, textured paint and top fillers; U-shaped clips with a thin rubber insert eliminated or greatly reduced sound across 110 wind speed and direction combinations, with the remaining cases expected for about 70 and 18 hours a year on average.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-27-k2","title":"現場實務","titleEn":"Site practice","text":"改變橋面細部的工程，風洞試驗範圍應包含局部構件的渦振與聲學，並在合約中訂出可接受的聲音與振動準則；改善措施（例如 12,000 根鋼條的夾具）須有安裝品質抽查與維修計畫。","textEn":"For work that changes deck details, wind-tunnel scope should include local vortex shedding and acoustics, with acceptable sound and vibration criteria in the contract; remedies such as clips on 12,000 slats need installation sampling and a maintenance plan.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「抗風改造欄杆的風鳴試驗」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Wind-tunnel tests of the singing retrofit railing\"?","options":["業主自 2020 年秋以足尺欄杆模型做風洞試驗，比較橫桿、粗糙膠帶、U 形夾、紋理塗料與填頂等方案，最後以附薄橡膠墊的 U 形夾在 110 種風速與風向組合中消除或大幅降低聲音。","量測時不必記錄溫度、日照、風與施工荷重，因為它們不會影響結果。","吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。"],"optionsEn":["From autumn 2020 the owner tested a full-scale railing model in a wind tunnel, comparing horizontal bars, coarse tape, U-shaped clips, textured paint and top fillers.","Temperature, sunshine, wind and construction loads need not be recorded because they cannot affect the result.","Suspenders are just thin ropes hanging the deck; losing one or two does not matter."],"answer":0,"explanation":"業主自 2020 年秋以足尺欄杆模型做風洞試驗，比較橫桿、粗糙膠帶、U 形夾、紋理塗料與填頂等方案，最後以附薄橡膠墊的 U 形夾在 110 種風速與風向組合中消除或大幅降低聲音；剩餘情境預估每年平均約 70 小時與 18 小時。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"From autumn 2020 the owner tested a full-scale railing model in a wind tunnel, comparing horizontal bars, coarse tape, U-shaped clips, textured paint and top fillers; U-shaped clips with a thin rubber insert eliminated or greatly reduced sound across 110 wind speed and direction combinations, with the remaining cases expected for about 70 and 18 hours a year on average. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":51},{"id":"b015-v13-28","title":"抗風改造欄杆的風鳴試驗：失效診斷","titleEn":"Wind-tunnel tests of the singing retrofit railing: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-27"],"objective":"從症狀倒推「西側欄杆鋼條風鳴」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “West railing slat tones” and propose discriminating checks, corrective actions and prevention.","instruction":"若改造只檢核結構氣動穩定而未評估聲學與局部渦振，細長構件可能在常見風速下鳴響並承受高頻應力循環；高頻振動長期也可能使鋼條銲道或螺栓疲勞。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Checking only global aerodynamic stability without assessing acoustics and local vortex shedding can leave slender parts singing at common wind speeds and seeing high-frequency stress cycles, which over time can fatigue slat welds or bolts. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：業主公布兩種音調：西風垂直吹向欄杆且達 22 mph 以上時約 280 至 700 Hz，風以小角度吹來且達 27 mph 以上時約 1.1 kHz。","observationEn":"Link to the mechanism: The owner reports two tones: about 280 to 700 Hz with west wind perpendicular to the railing at 22 mph or more, and about 1.1 kHz with wind at a slight angle at 27 mph or more.","failure":"誤判風險：若相信「只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-28-k1","title":"失效模式","titleEn":"Failure mode","text":"若改造只檢核結構氣動穩定而未評估聲學與局部渦振，細長構件可能在常見風速下鳴響並承受高頻應力循環；高頻振動長期也可能使鋼條銲道或螺栓疲勞。","textEn":"Checking only global aerodynamic stability without assessing acoustics and local vortex shedding can leave slender parts singing at common wind speeds and seeing high-frequency stress cycles, which over time can fatigue slat welds or bolts.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「抗風改造欄杆的風鳴試驗」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Wind-tunnel tests of the singing retrofit railing\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","若改造只檢核結構氣動穩定而未評估聲學與局部渦振，細長構件可能在常見風速下鳴響並承受高頻應力循環；高頻振動長期也可能使鋼條銲道或螺栓疲勞。","螺栓一旦鎖到規定張力，就能永久保持。"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Checking only global aerodynamic stability without assessing acoustics and local vortex shedding can leave slender parts singing at common wind speeds and seeing high-frequency stress cycles, which over time can fatigue slat welds or bolts.","Once bolts are tightened to the specified tension, they keep it forever."],"answer":1,"explanation":"若改造只檢核結構氣動穩定而未評估聲學與局部渦振，細長構件可能在常見風速下鳴響並承受高頻應力循環；高頻振動長期也可能使鋼條銲道或螺栓疲勞。 需以量測區分可能原因。","explanationEn":"Checking only global aerodynamic stability without assessing acoustics and local vortex shedding can leave slender parts singing at common wind speeds and seeing high-frequency stress cycles, which over time can fatigue slat welds or bolts. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":52},{"id":"b015-v13-29","title":"索夾螺栓預力損失與再張拉：機制與傳力路徑","titleEn":"Cable-band bolt preload loss and re-tensioning: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-28"],"objective":"說明「索夾螺栓預力」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Cable-band bolt preload” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"索夾靠螺栓夾緊主纜，以摩擦力抵抗吊索力沿主纜方向的下滑分量。業主資料記載，1953 至 1954 年增設下層橫向斜撐時發現索夾螺栓最多損失了規定張力的 50%，1954 年重新張拉，1970 年代再張拉至 90,000 lb；1999 年做過張力檢查，2000 至 2001 年把 256 根直徑 2⅛ in、長 3 ft 的繫固螺栓再張拉至 92,000 lb。預力流失的主因是主纜鋼絲在夾壓下逐漸重新排列與壓密、鍍鋅層潛變，以及溫度循環；螺栓伸長量只有零點幾毫米，因此很小的直徑變化就能吃掉大半預力。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「索夾螺栓預力」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Cable bands grip the main cable by bolt clamping, using friction to resist the component of suspender force acting down the cable slope. Owner data record that when the lower lateral bracing was added in 1953–1954, cable-band bolts were found to have lost as much as 50% of their specified tension; they were re-tensioned in 1954, again to 90,000 lb in the 1970s, checked in 1999, and in 2000–2001 the 256 tie-down bolts, each 2⅛ in in diameter and 3 ft long, were re-tensioned to 92,000 lb. Preload is lost mainly as cable wires rearrange and compact under clamping, as zinc creeps and through thermal cycles; bolt elongation is only fractions of a millimetre, so a tiny diameter change can consume most of the preload. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Cable-band bolt preload” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：90,000 lb ≈ 400 kN，2⅛ in 螺栓毛面積 ≈ 2,288 mm²，應力 ≈ 175 N/mm²；夾緊長度取 0.6 m，彈性伸長 = 175×600/200,000 ≈ 0.52 mm。","observationEn":"Order-of-magnitude cue: 90,000 lb ≈ 400 kN; a 2⅛ in bolt has a gross area ≈ 2,288 mm², a stress ≈ 175 N/mm²; with a 0.6 m grip the elastic elongation = 175×600/200,000 ≈ 0.52 mm, so just 0.26 mm of cable compaction under the band loses about 50% of preload.","failure":"常見誤解：「螺栓一旦鎖到規定張力，就能永久保持。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Once bolts are tightened to the specified tension, they keep it forever.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「索夾螺栓預力」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Cable-band bolt preload”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-29-k1","title":"索夾螺栓預力損失與再張拉","titleEn":"Cable-band bolt preload loss and re-tensioning","text":"索夾靠螺栓夾緊主纜，以摩擦力抵抗吊索力沿主纜方向的下滑分量。業主資料記載，1953 至 1954 年增設下層橫向斜撐時發現索夾螺栓最多損失了規定張力的 50%，1954 年重新張拉，1970 年代再張拉至 90,000 lb；1999 年做過張力檢查，2000 至 2001 年把 256 根直徑 2⅛ in、長 3 ft 的繫固螺栓再張拉至 92,000 lb。","textEn":"Cable bands grip the main cable by bolt clamping, using friction to resist the component of suspender force acting down the cable slope. Owner data record that when the lower lateral bracing was added in 1953–1954, cable-band bolts were found to have lost as much as 50% of their specified tension; they were re-tensioned in 1954, again to 90,000 lb in the 1970s, checked in 1999, and in 2000–2001 the 256 tie-down bolts, each 2⅛ in in diameter and 3 ft long, were re-tensioned to 92,000 lb.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：螺栓一旦鎖到規定張力，就能永久保持。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Once bolts are tightened to the specified tension, they keep it forever. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「索夾螺栓預力損失與再張拉」，下列哪一項敘述正確？","questionEn":"Which statement about \"Cable-band bolt preload loss and re-tensioning\" is correct?","options":["螺栓一旦鎖到規定張力，就能永久保持。","1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。","索夾靠螺栓夾緊主纜，以摩擦力抵抗吊索力沿主纜方向的下滑分量。"],"optionsEn":["Once bolts are tightened to the specified tension, they keep it forever.","Because the bridge was undamaged in 1989, it does not need seismic retrofit.","Cable bands grip the main cable by bolt clamping, using friction to resist the component of suspender force acting down the cable slope."],"answer":2,"explanation":"索夾靠螺栓夾緊主纜，以摩擦力抵抗吊索力沿主纜方向的下滑分量。 其餘選項是常見誤解。","explanationEn":"Cable bands grip the main cable by bolt clamping, using friction to resist the component of suspender force acting down the cable slope. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":53},{"id":"b015-v13-30","title":"索夾螺栓預力損失與再張拉：定量估算","titleEn":"Cable-band bolt preload loss and re-tensioning: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-29"],"objective":"以數值模型估算「索夾螺栓預力」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Cable-band bolt preload” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：90,000 lb ≈ 400 kN，2⅛ in 螺栓毛面積 ≈ 2,288 mm²，應力 ≈ 175 N/mm²；夾緊長度取 0.6 m，彈性伸長 = 175×600/200,000 ≈ 0.52 mm。只要主纜在索夾處壓密約 0.26 mm，預力即損失約 50%。3 ft 長、92,000 lb 的繫固螺栓伸長約 179×914/200,000 ≈ 0.82 mm。夾緊長度為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: 90,000 lb ≈ 400 kN; a 2⅛ in bolt has a gross area ≈ 2,288 mm², a stress ≈ 175 N/mm²; with a 0.6 m grip the elastic elongation = 175×600/200,000 ≈ 0.52 mm, so just 0.26 mm of cable compaction under the band loses about 50% of preload. A 3 ft tie-down bolt at 92,000 lb stretches about 179×914/200,000 ≈ 0.82 mm. The grip length is a teaching assumption. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以超音波量測螺栓伸長或以液壓張拉器做起始脫離（lift-off）試驗求現有預力，抽樣範圍涵蓋不同跨段與坡度；再張拉後記錄每根螺栓的目標值與實際值，數年後複測以求預力流失曲線，並檢查索夾是否有滑移痕跡。","observationEn":"How to cross-check: Measure existing preload by ultrasonic bolt elongation or hydraulic lift-off tests on a sample covering different spans and slopes; after re-tensioning record target and achieved values for each bolt, re-test after some years to derive the preload-loss curve, and inspect bands for slip marks.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"90,000 lb ≈ 400 kN，2⅛ in 螺栓毛面積 ≈ 2,288 mm²，應力 ≈ 175 N/mm²；夾緊長度取 0.6 m，彈性伸長 = 175×600/200,000 ≈ 0.52 mm。只要主纜在索夾處壓密約 0.26 mm，預力即損失約 50%。3 ft 長、92,000 lb 的繫固螺栓伸長約 179×914/200,000 ≈ 0.82 mm。夾緊長度為教學假設。","textEn":"90,000 lb ≈ 400 kN; a 2⅛ in bolt has a gross area ≈ 2,288 mm², a stress ≈ 175 N/mm²; with a 0.6 m grip the elastic elongation = 175×600/200,000 ≈ 0.52 mm, so just 0.26 mm of cable compaction under the band loses about 50% of preload. A 3 ft tie-down bolt at 92,000 lb stretches about 179×914/200,000 ≈ 0.82 mm. The grip length is a teaching assumption.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「索夾螺栓預力損失與再張拉」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Cable-band bolt preload loss and re-tensioning\", which statement holds?","options":["90,000 lb ≈ 400 kN，2⅛ in 螺栓毛面積 ≈ 2,288 mm²，應力 ≈ 175 N/mm²。","塔頂荷重就等於主纜張力。","老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。"],"optionsEn":["90,000 lb ≈ 400 kN.","The load on the tower equals the cable tension.","Old bridge wire is always far below its specification, so testing is pointless."],"answer":0,"explanation":"90,000 lb ≈ 400 kN，2⅛ in 螺栓毛面積 ≈ 2,288 mm²，應力 ≈ 175 N/mm²；夾緊長度取 0.6 m，彈性伸長 = 175×600/200,000 ≈ 0.52 mm。 重算時請保留單位。","explanationEn":"90,000 lb ≈ 400 kN; a 2⅛ in bolt has a gross area ≈ 2,288 mm², a stress ≈ 175 N/mm²; with a 0.6 m grip the elastic elongation = 175×600/200,000 ≈ 0.52 mm, so just 0.26 mm of cable compaction under the band loses about 50% of preload. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":54},{"id":"b015-v13-31","title":"索夾螺栓預力損失與再張拉：試驗與驗證","titleEn":"Cable-band bolt preload loss and re-tensioning: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「索夾螺栓預力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Cable-band bolt preload” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以超音波量測螺栓伸長或以液壓張拉器做起始脫離（lift-off）試驗求現有預力，抽樣範圍涵蓋不同跨段與坡度；再張拉後記錄每根螺栓的目標值與實際值，數年後複測以求預力流失曲線，並檢查索夾是否有滑移痕跡。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure existing preload by ultrasonic bolt elongation or hydraulic lift-off tests on a sample covering different spans and slopes; after re-tensioning record target and achieved values for each bolt, re-test after some years to derive the preload-loss curve, and inspect bands for slip marks. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：索夾螺栓應列入定期抽測的檢查項目，訂出觸發全面再張拉的預力門檻；任何會增加吊索力或改變主纜壓密狀態的工程（加撐、換橋面、除濕包覆）完成後，都要安排一次螺栓預力複測。","observationEn":"Site practice: Make cable-band bolts a periodic sampling item with a preload threshold that triggers full re-tensioning; after any work that raises suspender forces or changes cable compaction, such as bracing, deck replacement or dehumidification wrapping, schedule a preload re-check.","failure":"注意干擾：預力流失到摩擦力不足時，陡坡段的索夾會沿主纜下滑，吊索偏斜、索夾邊緣刮傷鋼絲並破壞防護包覆，水分隨之進入主纜；滑移也會改變吊索長度分配與橋面線形。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: When preload falls until friction is inadequate, bands on steep cable slopes slide down, tilting suspenders, scoring wires at band edges and breaking the wrapping so water enters the cable; slip also redistributes suspender lengths and alters the deck profile. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-31-k1","title":"驗證方法","titleEn":"Verification method","text":"以超音波量測螺栓伸長或以液壓張拉器做起始脫離（lift-off）試驗求現有預力，抽樣範圍涵蓋不同跨段與坡度；再張拉後記錄每根螺栓的目標值與實際值，數年後複測以求預力流失曲線，並檢查索夾是否有滑移痕跡。","textEn":"Measure existing preload by ultrasonic bolt elongation or hydraulic lift-off tests on a sample covering different spans and slopes; after re-tensioning record target and achieved values for each bolt, re-test after some years to derive the preload-loss curve, and inspect bands for slip marks.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-31-k2","title":"現場實務","titleEn":"Site practice","text":"索夾螺栓應列入定期抽測的檢查項目，訂出觸發全面再張拉的預力門檻；任何會增加吊索力或改變主纜壓密狀態的工程（加撐、換橋面、除濕包覆）完成後，都要安排一次螺栓預力複測。","textEn":"Make cable-band bolts a periodic sampling item with a preload threshold that triggers full re-tensioning; after any work that raises suspender forces or changes cable compaction, such as bracing, deck replacement or dehumidification wrapping, schedule a preload re-check.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「索夾螺栓預力損失與再張拉」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Cable-band bolt preload loss and re-tensioning\"?","options":["沿用另一座橋或另一棟建築的量測結果，就可視為本工程已完成驗證。","以超音波量測螺栓伸長或以液壓張拉器做起始脫離（lift-off）試驗求現有預力，抽樣範圍涵蓋不同跨段與坡度。","空中紡線的速度只取決於紡線輪跑多快。"],"optionsEn":["Reusing results from another bridge or building counts as verifying this structure.","Measure existing preload by ultrasonic bolt elongation or hydraulic lift-off tests on a sample covering different spans and slopes.","Aerial-spinning speed depends only on how fast the wheels run."],"answer":1,"explanation":"以超音波量測螺栓伸長或以液壓張拉器做起始脫離（lift-off）試驗求現有預力，抽樣範圍涵蓋不同跨段與坡度；再張拉後記錄每根螺栓的目標值與實際值，數年後複測以求預力流失曲線，並檢查索夾是否有滑移痕跡。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure existing preload by ultrasonic bolt elongation or hydraulic lift-off tests on a sample covering different spans and slopes; after re-tensioning record target and achieved values for each bolt, re-test after some years to derive the preload-loss curve, and inspect bands for slip marks. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":55},{"id":"b015-v13-32","title":"索夾螺栓預力損失與再張拉：失效診斷","titleEn":"Cable-band bolt preload loss and re-tensioning: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-31"],"objective":"從症狀倒推「索夾螺栓預力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Cable-band bolt preload” and propose discriminating checks, corrective actions and prevention.","instruction":"預力流失到摩擦力不足時，陡坡段的索夾會沿主纜下滑，吊索偏斜、索夾邊緣刮傷鋼絲並破壞防護包覆，水分隨之進入主纜；滑移也會改變吊索長度分配與橋面線形。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"When preload falls until friction is inadequate, bands on steep cable slopes slide down, tilting suspenders, scoring wires at band edges and breaking the wrapping so water enters the cable; slip also redistributes suspender lengths and alters the deck profile. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：預力流失的主因是主纜鋼絲在夾壓下逐漸重新排列與壓密、鍍鋅層潛變，以及溫度循環；螺栓伸長量只有零點幾毫米，因此很小的直徑變化就能吃掉大半預力。","observationEn":"Link to the mechanism: Preload is lost mainly as cable wires rearrange and compact under clamping, as zinc creeps and through thermal cycles; bolt elongation is only fractions of a millimetre, so a tiny diameter change can consume most of the preload.","failure":"誤判風險：若相信「螺栓一旦鎖到規定張力，就能永久保持。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Once bolts are tightened to the specified tension, they keep it forever.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-32-k1","title":"失效模式","titleEn":"Failure mode","text":"預力流失到摩擦力不足時，陡坡段的索夾會沿主纜下滑，吊索偏斜、索夾邊緣刮傷鋼絲並破壞防護包覆，水分隨之進入主纜；滑移也會改變吊索長度分配與橋面線形。","textEn":"When preload falls until friction is inadequate, bands on steep cable slopes slide down, tilting suspenders, scoring wires at band edges and breaking the wrapping so water enters the cable; slip also redistributes suspender lengths and alters the deck profile.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「索夾螺栓預力損失與再張拉」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Cable-band bolt preload loss and re-tensioning\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。","預力流失到摩擦力不足時，陡坡段的索夾會沿主纜下滑，吊索偏斜、索夾邊緣刮傷鋼絲並破壞防護包覆，水分隨之進入主纜；滑移也會改變吊索長度分配與橋面線形。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Because the bridge was undamaged in 1989, it does not need seismic retrofit.","When preload falls until friction is inadequate, bands on steep cable slopes slide down, tilting suspenders, scoring wires at band edges and breaking the wrapping so water enters the cable."],"answer":2,"explanation":"預力流失到摩擦力不足時，陡坡段的索夾會沿主纜下滑，吊索偏斜、索夾邊緣刮傷鋼絲並破壞防護包覆，水分隨之進入主纜；滑移也會改變吊索長度分配與橋面線形。 需以量測區分可能原因。","explanationEn":"When preload falls until friction is inadequate, bands on steep cable slopes slide down, tilting suspenders, scoring wires at band edges and breaking the wrapping so water enters the cable; slip also redistributes suspender lengths and alters the deck profile. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":56}],"order":8},{"id":"b015-v13-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「第 3B 期主橋耐震改造」與「防墜網、整流板與斷面變更管理」：先建立傳力機制與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Phase 3B seismic retrofit of the main bridge\" and \"Deterrent net, fairing and section-change management\": build the load path and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b015-v13-33","title":"第 3B 期主橋耐震改造：機制與傳力路徑","titleEn":"Phase 3B seismic retrofit of the main bridge: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-32"],"objective":"說明「38 組消能裝置」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “38 energy-dissipation devices” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"1989 年洛馬普列塔地震後的脆弱度研究指出，近距離 7.0 級以上地震可能造成嚴重損壞，8.0 級以上則可能使引橋與 Fort Point 拱段倒塌。改造以 10% 50 年超越機率（約 0.46 g）的中度地震與 1,000 年回歸期（約 0.65 g、相當於 1906 年舊金山地震）的最大可信地震為準則，分三期進行；第 2 期於 2008 年 7 月完成，消除了引橋倒塌風險。第 3B 期涵蓋主跨、兩邊跨、兩座橋塔與南塔基座：塔底以大型鋼板補強、塔內桁架補強、更換橋面與主塔及混凝土塔柱交接處的伸縮縫以容納三維位移、補強橋面橫向斜撐、改造 255 根橫梁，並安裝 38 組消能裝置，大幅減少傳入橋梁的地震能量。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「38 組消能裝置」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A vulnerability study after the 1989 Loma Prieta earthquake found that a nearby magnitude 7.0 or larger event could cause severe damage, and one of 8.0 or larger could collapse the approach viaducts and Fort Point Arch. The retrofit uses a moderate earthquake with 10% exceedance in 50 years (about 0.46 g) and a maximum credible earthquake with a 1,000-year return period (about 0.65 g, equivalent to the 1906 San Francisco earthquake), in three phases; Phase 2, finished in July 2008, removed the approach collapse risk. Phase 3B covers the main span, both side spans, both towers and the South Tower pier: steel plates at the tower bases, strengthened tower trusses, new expansion joints at the towers and pylons for three-dimensional movement, reinforced roadway lateral bracing, 255 retrofitted floor beams and 38 energy-dissipation devices that greatly reduce seismic energy entering the bridge. Mentor task: draw a free-body or load-path diagram showing how loads pass through “38 energy-dissipation devices” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：以非線性黏滯阻尼器說明消能：F = C·v^α。","observationEn":"Order-of-magnitude cue: Illustrate dissipation with a nonlinear viscous damper F = C·v^α.","failure":"常見誤解：「1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Because the bridge was undamaged in 1989, it does not need seismic retrofit.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「38 組消能裝置」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “38 energy-dissipation devices”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-33-k1","title":"第 3B 期主橋耐震改造","titleEn":"Phase 3B seismic retrofit of the main bridge","text":"1989 年洛馬普列塔地震後的脆弱度研究指出，近距離 7.0 級以上地震可能造成嚴重損壞，8.0 級以上則可能使引橋與 Fort Point 拱段倒塌。改造以 10% 50 年超越機率（約 0.46 g）的中度地震與 1,000 年回歸期（約 0.65 g、相當於 1906 年舊金山地震）的最大可信地震為準則，分三期進行；第 2 期於 2008 年 7 月完成，消除了引橋倒塌風險。","textEn":"A vulnerability study after the 1989 Loma Prieta earthquake found that a nearby magnitude 7.0 or larger event could cause severe damage, and one of 8.0 or larger could collapse the approach viaducts and Fort Point Arch. The retrofit uses a moderate earthquake with 10% exceedance in 50 years (about 0.46 g) and a maximum credible earthquake with a 1,000-year return period (about 0.65 g, equivalent to the 1906 San Francisco earthquake), in three phases; Phase 2, finished in July 2008, removed the approach collapse risk.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Because the bridge was undamaged in 1989, it does not need seismic retrofit. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「第 3B 期主橋耐震改造」，下列哪一項敘述正確？","questionEn":"Which statement about \"Phase 3B seismic retrofit of the main bridge\" is correct?","options":["1989 年洛馬普列塔地震後的脆弱度研究指出，近距離 7.0 級以上地震可能造成嚴重損壞，8.0 級以上則可能使引橋與 Fort Point 拱段倒塌。","1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。","防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。"],"optionsEn":["A vulnerability study after the 1989 Loma Prieta earthquake found that a nearby magnitude 7.0 or larger event could cause severe damage, and one of 8.0 or larger could collapse the approach viaducts and Fort Point Arch.","Because the bridge was undamaged in 1989, it does not need seismic retrofit.","The deterrent net is a light accessory with no effect on structure or wind stability."],"answer":0,"explanation":"1989 年洛馬普列塔地震後的脆弱度研究指出，近距離 7.0 級以上地震可能造成嚴重損壞，8.0 級以上則可能使引橋與 Fort Point 拱段倒塌。 其餘選項是常見誤解。","explanationEn":"A vulnerability study after the 1989 Loma Prieta earthquake found that a nearby magnitude 7.0 or larger event could cause severe damage, and one of 8.0 or larger could collapse the approach viaducts and Fort Point Arch. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":57},{"id":"b015-v13-34","title":"第 3B 期主橋耐震改造：定量估算","titleEn":"Phase 3B seismic retrofit of the main bridge: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-33"],"objective":"以數值模型估算「38 組消能裝置」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “38 energy-dissipation devices” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：以非線性黏滯阻尼器說明消能：F = C·v^α。取 C = 3,000 kN·(s/m)^0.4、α = 0.4、振幅 X = 0.5 m、週期 4 s（ω = 1.571 rad/s）：峰值速度 0.785 m/s，F ≈ 3,000×0.785^0.4 ≈ 2,720 kN；每循環耗能 E = λ·C·X^(1+α)·ω^α，λ ≈ 3.58，E ≈ 4,880 kJ。裝置型式與參數為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Illustrate dissipation with a nonlinear viscous damper F = C·v^α. With C = 3,000 kN·(s/m)^0.4, α = 0.4, amplitude X = 0.5 m and a 4 s period (ω = 1.571 rad/s): peak velocity 0.785 m/s and F ≈ 3,000×0.785^0.4 ≈ 2,720 kN; energy per cycle E = λ·C·X^(1+α)·ω^α with λ ≈ 3.58 gives E ≈ 4,880 kJ. Device type and parameters are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：消能裝置須做原型與逐件試驗，涵蓋設計速度範圍、溫度與循環次數，力—位移遲滯迴圈的耗能與規格比較；全橋以非線性時間歷程分析輸入多組近斷層紀錄，檢查塔底應力、伸縮縫三維位移與橋面斜撐受力是否符合兩級地震的性能目標。","observationEn":"How to cross-check: Damping devices need prototype and production tests over the design velocity range, temperatures and cycle counts, comparing hysteresis-loop energy with the specification; the whole bridge is analysed by nonlinear time history with several near-fault records to check tower-base stress, three-dimensional joint movement and lateral-bracing forces against the performance goals for both earthquake levels.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"以非線性黏滯阻尼器說明消能：F = C·v^α。取 C = 3,000 kN·(s/m)^0.4、α = 0.4、振幅 X = 0.5 m、週期 4 s（ω = 1.571 rad/s）：峰值速度 0.785 m/s，F ≈ 3,000×0.785^0.4 ≈ 2,720 kN；每循環耗能 E = λ·C·X^(1+α)·ω^α，λ ≈ 3.58，E ≈ 4,880 kJ。裝置型式與參數為教學假設。","textEn":"Illustrate dissipation with a nonlinear viscous damper F = C·v^α. With C = 3,000 kN·(s/m)^0.4, α = 0.4, amplitude X = 0.5 m and a 4 s period (ω = 1.571 rad/s): peak velocity 0.785 m/s and F ≈ 3,000×0.785^0.4 ≈ 2,720 kN; energy per cycle E = λ·C·X^(1+α)·ω^α with λ ≈ 3.58 gives E ≈ 4,880 kJ. Device type and parameters are teaching assumptions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「第 3B 期主橋耐震改造」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Phase 3B seismic retrofit of the main bridge\", which statement holds?","options":["懸索橋的橫向勁度主要來自橋面桁架，主纜只負責垂直荷重。","以非線性黏滯阻尼器說明消能：F = C·v^α。","吊索只是把橋面掛起來的細鋼索，壞一兩根不影響整體。"],"optionsEn":["A suspension bridge's lateral stiffness comes mainly from the deck truss; the cables only carry vertical load.","Illustrate dissipation with a nonlinear viscous damper F = C·v^α.","Suspenders are just thin ropes hanging the deck; losing one or two does not matter."],"answer":1,"explanation":"以非線性黏滯阻尼器說明消能：F = C·v^α。 重算時請保留單位。","explanationEn":"Illustrate dissipation with a nonlinear viscous damper F = C·v^α. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":58},{"id":"b015-v13-35","title":"第 3B 期主橋耐震改造：試驗與驗證","titleEn":"Phase 3B seismic retrofit of the main bridge: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「38 組消能裝置」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “38 energy-dissipation devices” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"消能裝置須做原型與逐件試驗，涵蓋設計速度範圍、溫度與循環次數，力—位移遲滯迴圈的耗能與規格比較；全橋以非線性時間歷程分析輸入多組近斷層紀錄，檢查塔底應力、伸縮縫三維位移與橋面斜撐受力是否符合兩級地震的性能目標。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Damping devices need prototype and production tests over the design velocity range, temperatures and cycle counts, comparing hysteresis-loop energy with the specification; the whole bridge is analysed by nonlinear time history with several near-fault records to check tower-base stress, three-dimensional joint movement and lateral-bracing forces against the performance goals for both earthquake levels. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：耐震改造的分期順序應依構件勁度與倒塌後果排定（業主先做較不柔的橋塔與邊跨），每期完工都要更新全橋模型與性能矩陣；消能裝置需納入定期檢查與抽測計畫，並保存原型試驗曲線作為基準。","observationEn":"Site practice: Sequence retrofit phases by stiffness and collapse consequence (the owner starts with the less flexible towers and side spans), updating the whole-bridge model and performance matrix at the end of each phase; put damping devices on a periodic inspection and sampling programme with prototype test curves kept as the baseline.","failure":"注意干擾：只補強主橋而不處理伸縮縫，大地震時橋面與塔之間的相對位移可能使伸縮縫破壞、支承脫落；消能裝置若在長期風與交通的小振幅循環中磨耗而未檢查，地震時的耗能可能遠低於設計。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Strengthening the main bridge without new joints lets relative movement between deck and towers in a large earthquake destroy joints and unseat bearings; dampers worn by years of small wind and traffic cycles without inspection may dissipate far less energy than designed in an earthquake. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-35-k1","title":"驗證方法","titleEn":"Verification method","text":"消能裝置須做原型與逐件試驗，涵蓋設計速度範圍、溫度與循環次數，力—位移遲滯迴圈的耗能與規格比較；全橋以非線性時間歷程分析輸入多組近斷層紀錄，檢查塔底應力、伸縮縫三維位移與橋面斜撐受力是否符合兩級地震的性能目標。","textEn":"Damping devices need prototype and production tests over the design velocity range, temperatures and cycle counts, comparing hysteresis-loop energy with the specification; the whole bridge is analysed by nonlinear time history with several near-fault records to check tower-base stress, three-dimensional joint movement and lateral-bracing forces against the performance goals for both earthquake levels.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-35-k2","title":"現場實務","titleEn":"Site practice","text":"耐震改造的分期順序應依構件勁度與倒塌後果排定（業主先做較不柔的橋塔與邊跨），每期完工都要更新全橋模型與性能矩陣；消能裝置需納入定期檢查與抽測計畫，並保存原型試驗曲線作為基準。","textEn":"Sequence retrofit phases by stiffness and collapse consequence (the owner starts with the less flexible towers and side spans), updating the whole-bridge model and performance matrix at the end of each phase; put damping devices on a periodic inspection and sampling programme with prototype test curves kept as the baseline.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「第 3B 期主橋耐震改造」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Phase 3B seismic retrofit of the main bridge\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","把橋面換輕只會讓橋更安全，不會改變幾何。","消能裝置須做原型與逐件試驗，涵蓋設計速度範圍、溫度與循環次數，力—位移遲滯迴圈的耗能與規格比較。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","A lighter deck only makes the bridge safer; it does not change the geometry.","Damping devices need prototype and production tests over the design velocity range, temperatures and cycle counts, comparing hysteresis-loop energy with the specification."],"answer":2,"explanation":"消能裝置須做原型與逐件試驗，涵蓋設計速度範圍、溫度與循環次數，力—位移遲滯迴圈的耗能與規格比較；全橋以非線性時間歷程分析輸入多組近斷層紀錄，檢查塔底應力、伸縮縫三維位移與橋面斜撐受力是否符合兩級地震的性能目標。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Damping devices need prototype and production tests over the design velocity range, temperatures and cycle counts, comparing hysteresis-loop energy with the specification; the whole bridge is analysed by nonlinear time history with several near-fault records to check tower-base stress, three-dimensional joint movement and lateral-bracing forces against the performance goals for both earthquake levels. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":59},{"id":"b015-v13-36","title":"第 3B 期主橋耐震改造：失效診斷","titleEn":"Phase 3B seismic retrofit of the main bridge: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-35"],"objective":"從症狀倒推「38 組消能裝置」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “38 energy-dissipation devices” and propose discriminating checks, corrective actions and prevention.","instruction":"只補強主橋而不處理伸縮縫，大地震時橋面與塔之間的相對位移可能使伸縮縫破壞、支承脫落；消能裝置若在長期風與交通的小振幅循環中磨耗而未檢查，地震時的耗能可能遠低於設計。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Strengthening the main bridge without new joints lets relative movement between deck and towers in a large earthquake destroy joints and unseat bearings; dampers worn by years of small wind and traffic cycles without inspection may dissipate far less energy than designed in an earthquake. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：第 3B 期涵蓋主跨、兩邊跨、兩座橋塔與南塔基座：塔底以大型鋼板補強、塔內桁架補強、更換橋面與主塔及混凝土塔柱交接處的伸縮縫以容納三維位移、補強橋面橫向斜撐、改造 255 根橫梁，並安裝 38 組消能裝置，大幅減少傳入橋梁的地震能量。","observationEn":"Link to the mechanism: Phase 3B covers the main span, both side spans, both towers and the South Tower pier: steel plates at the tower bases, strengthened tower trusses, new expansion joints at the towers and pylons for three-dimensional movement, reinforced roadway lateral bracing, 255 retrofitted floor beams and 38 energy-dissipation devices that greatly reduce seismic energy entering the bridge.","failure":"誤判風險：若相信「1989 年地震中金門大橋沒有損壞，代表它不需要耐震改造。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Because the bridge was undamaged in 1989, it does not need seismic retrofit.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-36-k1","title":"失效模式","titleEn":"Failure mode","text":"只補強主橋而不處理伸縮縫，大地震時橋面與塔之間的相對位移可能使伸縮縫破壞、支承脫落；消能裝置若在長期風與交通的小振幅循環中磨耗而未檢查，地震時的耗能可能遠低於設計。","textEn":"Strengthening the main bridge without new joints lets relative movement between deck and towers in a large earthquake destroy joints and unseat bearings; dampers worn by years of small wind and traffic cycles without inspection may dissipate far less energy than designed in an earthquake.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「第 3B 期主橋耐震改造」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Phase 3B seismic retrofit of the main bridge\" shows distress, which diagnosis is most reasonable?","options":["只補強主橋而不處理伸縮縫，大地震時橋面與塔之間的相對位移可能使伸縮縫破壞、支承脫落。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。"],"optionsEn":["Strengthening the main bridge without new joints lets relative movement between deck and towers in a large earthquake destroy joints and unseat bearings.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","The deterrent net is a light accessory with no effect on structure or wind stability."],"answer":0,"explanation":"只補強主橋而不處理伸縮縫，大地震時橋面與塔之間的相對位移可能使伸縮縫破壞、支承脫落；消能裝置若在長期風與交通的小振幅循環中磨耗而未檢查，地震時的耗能可能遠低於設計。 需以量測區分可能原因。","explanationEn":"Strengthening the main bridge without new joints lets relative movement between deck and towers in a large earthquake destroy joints and unseat bearings; dampers worn by years of small wind and traffic cycles without inspection may dissipate far less energy than designed in an earthquake. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":60},{"id":"b015-v13-37","title":"防墜網、整流板與斷面變更管理：機制與傳力路徑","titleEn":"Deterrent net, fairing and section-change management: mechanism and load path","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-36"],"objective":"說明「防墜網與整流板」如何影響舊金山金門大橋的受力、變形或耐久表現，並畫出荷載的來源、傳遞路徑與支承邊界。","objectiveEn":"Explain how “Deterrent net and wind fairing” governs force, deformation or durability in “Golden Gate Bridge”, and map where loads come from, how they travel and where they are supported.","instruction":"防墜系統在東西兩側人行道下方 20 ft 處裝設海洋級不鏽鋼網，向外伸出 20 ft，沿 1.7 mi 全長連續，2018 年動工、2024 年初完成。網片與支架改變了橋面邊緣的流場並增加風阻，因此必須搭配抗風改造：透風的西側欄杆與人行道下方整流板，確保橋梁在持續 100 mph 的風中仍保有結構完整與氣動穩定。這說明一座 1937 年的懸索橋，每次在斷面上加東西，都要重新回答「顫振、抖振、渦振與側向變位是否仍可接受」的問題。 師傅任務：以自由體圖或傳力路徑圖畫出荷載如何經過「防墜網與整流板」傳到支承或基礎，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The deterrent system hangs marine-grade stainless-steel netting 20 ft below the sidewalks on both sides, extending 20 ft out and running continuously for the full 1.7 miles; it began in 2018 and was complete in early 2024. The netting and its supports change the flow at the deck edges and add wind resistance, so it had to be paired with the wind retrofit, the more porous west railing and a fairing below the sidewalk, to keep the bridge structurally sound and aerodynamically stable in sustained winds up to 100 mph. It shows that every addition to the section of a 1937 suspension bridge reopens the question of whether flutter, buffeting, vortex shedding and lateral deflection remain acceptable. Mentor task: draw a free-body or load-path diagram showing how loads pass through “Deterrent net and wind fairing” to the supports or foundation, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：100 mph（44.7 m/s）風壓 q = ½ρU² ≈ 1,249 Pa。","observationEn":"Order-of-magnitude cue: At 100 mph (44.7 m/s) the wind pressure q = ½ρU² ≈ 1,249 Pa.","failure":"常見誤解：「防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。」這個說法忽略了上述機制；請在傳力圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The deterrent net is a light accessory with no effect on structure or wind stability.\" It ignores the mechanism above; mark on your load-path diagram where it breaks down.","check":"傳力圖標明「防墜網與整流板」的荷載來源、傳遞路徑與支承；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The load-path diagram shows load sources, path and supports for “Deterrent net and wind fairing”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b015-v13-37-k1","title":"防墜網、整流板與斷面變更管理","titleEn":"Deterrent net, fairing and section-change management","text":"防墜系統在東西兩側人行道下方 20 ft 處裝設海洋級不鏽鋼網，向外伸出 20 ft，沿 1.7 mi 全長連續，2018 年動工、2024 年初完成。網片與支架改變了橋面邊緣的流場並增加風阻，因此必須搭配抗風改造：透風的西側欄杆與人行道下方整流板，確保橋梁在持續 100 mph 的風中仍保有結構完整與氣動穩定。","textEn":"The deterrent system hangs marine-grade stainless-steel netting 20 ft below the sidewalks on both sides, extending 20 ft out and running continuously for the full 1.7 miles; it began in 2018 and was complete in early 2024. The netting and its supports change the flow at the deck edges and add wind resistance, so it had to be paired with the wind retrofit, the more porous west railing and a fairing below the sidewalk, to keep the bridge structurally sound and aerodynamically stable in sustained winds up to 100 mph.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The deterrent net is a light accessory with no effect on structure or wind stability. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"關於「防墜網、整流板與斷面變更管理」，下列哪一項敘述正確？","questionEn":"Which statement about \"Deterrent net, fairing and section-change management\" is correct?","options":["防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。","防墜系統在東西兩側人行道下方 20 ft 處裝設海洋級不鏽鋼網，向外伸出 20 ft，沿 1.7 mi 全長連續，2018 年動工、2024 年初完成。","塔頂荷重就等於主纜張力。"],"optionsEn":["The deterrent net is a light accessory with no effect on structure or wind stability.","The deterrent system hangs marine-grade stainless-steel netting 20 ft below the sidewalks on both sides, extending 20 ft out and running continuously for the full 1.7 miles.","The load on the tower equals the cable tension."],"answer":1,"explanation":"防墜系統在東西兩側人行道下方 20 ft 處裝設海洋級不鏽鋼網，向外伸出 20 ft，沿 1.7 mi 全長連續，2018 年動工、2024 年初完成。 其餘選項是常見誤解。","explanationEn":"The deterrent system hangs marine-grade stainless-steel netting 20 ft below the sidewalks on both sides, extending 20 ft out and running continuously for the full 1.7 miles; it began in 2018 and was complete in early 2024. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":61},{"id":"b015-v13-38","title":"防墜網、整流板與斷面變更管理：定量估算","titleEn":"Deterrent net, fairing and section-change management: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-37"],"objective":"以數值模型估算「防墜網與整流板」的關鍵量，並判斷跨度、荷載、溫度或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Deterrent net and wind fairing” with a numerical model and judge the direction and size of change when span, load, temperature or material parameters move.","instruction":"依下列模型逐步重算：100 mph（44.7 m/s）風壓 q = ½ρU² ≈ 1,249 Pa。若網片與支架在兩側合計增加等效投影深度 0.6 m、阻力係數 1.2：ΔF ≈ 1,249×1.2×0.6 ≈ 0.90 kN/m；以重力勁度估算跨中附加側向變位 Δδ = ΔF·l²/(8H) ≈ 0.90×1,280²/(8×651,000) ≈ 0.28 m。投影深度與係數為教學假設。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: At 100 mph (44.7 m/s) the wind pressure q = ½ρU² ≈ 1,249 Pa. If the net and supports add an equivalent projected depth of 0.6 m in total with a drag coefficient of 1.2: ΔF ≈ 1,249×1.2×0.6 ≈ 0.90 kN/m; the gravity-stiffness estimate of added mid-span lateral deflection is Δδ = ΔF·l²/(8H) ≈ 0.90×1,280²/(8×651,000) ≈ 0.28 m. Projected depth and coefficient are teaching assumptions. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以含網片、整流板與新欄杆的斷面模型重新量測靜力係數與氣動導數，檢查顫振臨界風速、抖振反應與渦振；施工後以監測資料比較改造前後同風況下的位移與加速度，並持續記錄網片與支架的腐蝕與鬆動。","observationEn":"How to cross-check: Re-measure static coefficients and aerodynamic derivatives on a section model including the net, fairing and new railing, checking flutter onset, buffeting and vortex shedding; after construction compare monitored displacement and acceleration before and after under similar winds, and keep recording corrosion and loosening of the net and supports.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"重現模型中的數值（取整誤差在 ±5% 內），並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values (within ±5% rounding) and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b015-v13-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"100 mph（44.7 m/s）風壓 q = ½ρU² ≈ 1,249 Pa。若網片與支架在兩側合計增加等效投影深度 0.6 m、阻力係數 1.2：ΔF ≈ 1,249×1.2×0.6 ≈ 0.90 kN/m；以重力勁度估算跨中附加側向變位 Δδ = ΔF·l²/(8H) ≈ 0.90×1,280²/(8×651,000) ≈ 0.28 m。投影深度與係數為教學假設。","textEn":"At 100 mph (44.7 m/s) the wind pressure q = ½ρU² ≈ 1,249 Pa. If the net and supports add an equivalent projected depth of 0.6 m in total with a drag coefficient of 1.2: ΔF ≈ 1,249×1.2×0.6 ≈ 0.90 kN/m; the gravity-stiffness estimate of added mid-span lateral deflection is Δδ = ΔF·l²/(8H) ≈ 0.90×1,280²/(8×651,000) ≈ 0.28 m. Projected depth and coefficient are teaching assumptions.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"依「防墜網、整流板與斷面變更管理」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Deterrent net, fairing and section-change management\", which statement holds?","options":["老橋的鋼絲強度一定比規格值低很多，所以不值得試驗。","空中紡線的速度只取決於紡線輪跑多快。","100 mph（44.7 m/s）風壓 q = ½ρU² ≈ 1,249 Pa。"],"optionsEn":["Old bridge wire is always far below its specification, so testing is pointless.","Aerial-spinning speed depends only on how fast the wheels run.","At 100 mph (44.7 m/s) the wind pressure q = ½ρU² ≈ 1,249 Pa."],"answer":2,"explanation":"100 mph（44.7 m/s）風壓 q = ½ρU² ≈ 1,249 Pa。 重算時請保留單位。","explanationEn":"At 100 mph (44.7 m/s) the wind pressure q = ½ρU² ≈ 1,249 Pa. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":62},{"id":"b015-v13-39","title":"防墜網、整流板與斷面變更管理：試驗與驗證","titleEn":"Deterrent net, fairing and section-change management: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「防墜網與整流板」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Deterrent net and wind fairing” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以含網片、整流板與新欄杆的斷面模型重新量測靜力係數與氣動導數，檢查顫振臨界風速、抖振反應與渦振；施工後以監測資料比較改造前後同風況下的位移與加速度，並持續記錄網片與支架的腐蝕與鬆動。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Re-measure static coefficients and aerodynamic derivatives on a section model including the net, fairing and new railing, checking flutter onset, buffeting and vortex shedding; after construction compare monitored displacement and acceleration before and after under similar winds, and keep recording corrosion and loosening of the net and supports. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：業主應建立「斷面變更管理」制度：任何附加於橋面或桁架的設施，先登錄重量、受風面積與連接細部，由結構與風工程顧問評估並核准，完工後更新恆載履歷、風洞基準與檢查清單，作為交接文件的一部分。","observationEn":"Site practice: The owner should run section-change management: any attachment to deck or truss is first registered with its weight, wind area and connection details, assessed and approved by structural and wind consultants, and after completion the dead-load history, wind-tunnel baseline and inspection checklist are updated as part of the handover record.","failure":"注意干擾：若附加物在未經氣動評估下裝上，可能降低顫振裕度或在某風向引發新的渦振；網片支架與桁架的連接若疲勞或腐蝕鬆脫，部件墜落還會危及航道。 只量一次、沒有可追溯的基準，或不記錄溫度、日照與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Attachments installed without aerodynamic assessment can lower flutter margin or start new vortex vibration in some wind directions; fatigued or corroded connections between net supports and the truss can loosen and drop parts into the shipping channel. A single reading, no traceable datum, or unrecorded temperature, sunshine and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b015-v13-39-k1","title":"驗證方法","titleEn":"Verification method","text":"以含網片、整流板與新欄杆的斷面模型重新量測靜力係數與氣動導數，檢查顫振臨界風速、抖振反應與渦振；施工後以監測資料比較改造前後同風況下的位移與加速度，並持續記錄網片與支架的腐蝕與鬆動。","textEn":"Re-measure static coefficients and aerodynamic derivatives on a section model including the net, fairing and new railing, checking flutter onset, buffeting and vortex shedding; after construction compare monitored displacement and acceleration before and after under similar winds, and keep recording corrosion and loosening of the net and supports.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-39-k2","title":"現場實務","titleEn":"Site practice","text":"業主應建立「斷面變更管理」制度：任何附加於橋面或桁架的設施，先登錄重量、受風面積與連接細部，由結構與風工程顧問評估並核准，完工後更新恆載履歷、風洞基準與檢查清單，作為交接文件的一部分。","textEn":"The owner should run section-change management: any attachment to deck or truss is first registered with its weight, wind area and connection details, assessed and approved by structural and wind consultants, and after completion the dead-load history, wind-tunnel baseline and inspection checklist are updated as part of the handover record.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"要驗證「防墜網、整流板與斷面變更管理」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Deterrent net, fairing and section-change management\"?","options":["以含網片、整流板與新欄杆的斷面模型重新量測靜力係數與氣動導數，檢查顫振臨界風速、抖振反應與渦振。","不確定度太難估計，報告中只寫最佳值即可。","只要整座橋在強風中穩定，欄杆的振動與聲音就不是工程問題。"],"optionsEn":["Re-measure static coefficients and aerodynamic derivatives on a section model including the net, fairing and new railing, checking flutter onset, buffeting and vortex shedding.","Uncertainty is too hard to estimate, so the report may state only the best value.","If the whole bridge is stable in strong wind, railing vibration and noise are not engineering problems."],"answer":0,"explanation":"以含網片、整流板與新欄杆的斷面模型重新量測靜力係數與氣動導數，檢查顫振臨界風速、抖振反應與渦振；施工後以監測資料比較改造前後同風況下的位移與加速度，並持續記錄網片與支架的腐蝕與鬆動。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Re-measure static coefficients and aerodynamic derivatives on a section model including the net, fairing and new railing, checking flutter onset, buffeting and vortex shedding; after construction compare monitored displacement and acceleration before and after under similar winds, and keep recording corrosion and loosening of the net and supports. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":63},{"id":"b015-v13-40","title":"防墜網、整流板與斷面變更管理：失效診斷","titleEn":"Deterrent net, fairing and section-change management: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"],"prerequisiteIds":["b015-v13-39"],"objective":"從症狀倒推「防墜網與整流板」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Deterrent net and wind fairing” and propose discriminating checks, corrective actions and prevention.","instruction":"若附加物在未經氣動評估下裝上，可能降低顫振裕度或在某風向引發新的渦振；網片支架與桁架的連接若疲勞或腐蝕鬆脫，部件墜落還會危及航道。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Attachments installed without aerodynamic assessment can lower flutter margin or start new vortex vibration in some wind directions; fatigued or corroded connections between net supports and the truss can loosen and drop parts into the shipping channel. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：這說明一座 1937 年的懸索橋，每次在斷面上加東西，都要重新回答「顫振、抖振、渦振與側向變位是否仍可接受」的問題。","observationEn":"Link to the mechanism: It shows that every addition to the section of a 1937 suspension bridge reopens the question of whether flutter, buffeting, vortex shedding and lateral deflection remain acceptable.","failure":"誤判風險：若相信「防墜網是輕量的附屬設施，對橋梁的結構與風穩定沒有影響。」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The deterrent net is a light accessory with no effect on structure or wind stability.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b015-v13-40-k1","title":"失效模式","titleEn":"Failure mode","text":"若附加物在未經氣動評估下裝上，可能降低顫振裕度或在某風向引發新的渦振；網片支架與桁架的連接若疲勞或腐蝕鬆脫，部件墜落還會危及航道。","textEn":"Attachments installed without aerodynamic assessment can lower flutter margin or start new vortex vibration in some wind directions; fatigued or corroded connections between net supports and the truss can loosen and drop parts into the shipping channel.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]},{"id":"b015-v13-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v7-golden-stats","v7-golden-seismic","v13s-ggb-seismic-phase-3","v13s-ggb-high-wind-sounds","v13s-ggb-deterrent-net"]}],"quiz":{"question":"在「防墜網、整流板與斷面變更管理」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Deterrent net, fairing and section-change management\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","若附加物在未經氣動評估下裝上，可能降低顫振裕度或在某風向引發新的渦振；網片支架與桁架的連接若疲勞或腐蝕鬆脫，部件墜落還會危及航道。","塔頂荷重就等於主纜張力。"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Attachments installed without aerodynamic assessment can lower flutter margin or start new vortex vibration in some wind directions.","The load on the tower equals the cable tension."],"answer":1,"explanation":"若附加物在未經氣動評估下裝上，可能降低顫振裕度或在某風向引發新的渦振；網片支架與桁架的連接若疲勞或腐蝕鬆脫，部件墜落還會危及航道。 需以量測區分可能原因。","explanationEn":"Attachments installed without aerodynamic assessment can lower flutter margin or start new vortex vibration in some wind directions; fatigued or corroded connections between net supports and the truss can loosen and drop parts into the shipping channel. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":64}],"order":9}],"curriculumVersion":7,"enrichmentVersion":13,"learningTrack":"structures","learningSubdiscipline":"st-suspension","learningTags":["structures","st-suspension","suspension"],"subcategory":"st-suspension","subcategoryTitle":"懸索橋巨作與主纜系統","subcategoryTitleEn":"Suspension bridges and main-cable systems","v13Architecture":{"architectureFamily":"suspension","architectureNodes":[["鋼塔與塔底補強","Steel towers and base strengthening"],["空中紡線主纜","Air-spun main cables"],["索夾螺栓與吊索","Cable-band bolts and suspenders"],["加勁桁架與正交異性橋面","Stiffening truss and orthotropic deck"],["消能裝置與伸縮縫","Dampers and expansion joints"],["欄杆、整流板與防墜網","Railing, fairing and deterrent net"]],"architectureEdges":[[3,2],[2,1],[1,0],[3,4],[4,0],[5,3]]},"v13Extension":{"stages":5,"steps":40,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"延伸練習：以業主公開數據核算主纜安全係數的變化。每座塔承受主纜荷重約 61,500 short ton（≈ 547 MN）；假設塔頂兩側 tanθ 為 0.44 與 0.40，H ≈ 651 MN（兩纜），每纜最大張力 T ≈ 356 MN。每纜鋼絲 27,572 根 × 18.68 mm² ≈ 515,000 mm²，以規格最低強度 220,000 psi（1,517 N/mm²）計破斷力 ≈ 781 MN，安全係數 ≈ 781/356 ≈ 2.19；以實測平均 235,600 psi（1,624 N/mm²）計 ≈ 2.35。若 1986 年橋面減重使每纜張力減少約 28.8 MN 的水平分量（最大張力約減 31.5 MN），係數提高到約 781/324.5 ≈ 2.41；若腐蝕使有效鋼絲面積減少 5%，係數回落到約 2.29。數值除業主公布者外均為教學假設，不代表金門大橋的評估結果。","textEn":"Extension exercise: check the change in cable safety factor with the owner's data. Each tower carries about 61,500 short tons (≈ 547 MN) from the cables; assuming tanθ of 0.44 and 0.40 on either side of the tower, H ≈ 651 MN for both cables and the maximum tension per cable T ≈ 356 MN. Each cable has 27,572 wires × 18.68 mm² ≈ 515,000 mm²; at the specified minimum 220,000 psi (1,517 N/mm²) the breaking force is ≈ 781 MN and the safety factor ≈ 781/356 ≈ 2.19, or about 2.35 at the average 235,600 psi (1,624 N/mm²). If the 1986 deck lightening reduced the horizontal tension per cable by about 28.8 MN (about 31.5 MN off the maximum tension), the factor rises to about 781/324.5 ≈ 2.41; a 5% loss of effective wire area from corrosion brings it back to about 2.29. Apart from the owner's published figures, values are teaching assumptions, not the Golden Gate Bridge's evaluation results.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"focus":"以業主公開數據做定量延伸：主纜張力、側向重力勁度、索夾螺栓預力損失、橋面減重抬升、欄杆風鳴與第 3B 期耐震改造","focusEn":"Quantitative extension from owner data: cable tension, lateral gravity stiffness, cable-band bolt preload loss, deck-lightening rise, railing wind tones and Phase 3B seismic retrofit"}}};
